@dataclass
class OperationLogEntry:
    event: str
    room_id: str = ""
    plan_id: str = ""
    batch_id: str = ""
    tool_call_id: str = ""
    message: str = ""
    payload: dict[str, Any] = field(default_factory=dict)
    timestamp: float = field(default_factory=_now)

    def as_dict(self) -> dict[str, Any]:
        return {
            "event": self.event,
            "room_id": self.room_id,
            "plan_id": self.plan_id,
            "batch_id": self.batch_id,
            "tool_call_id": self.tool_call_id,
            "message": self.message,
            "payload": dict(self.payload),
            "timestamp": self.timestamp,
        }


class OperationLog:
    """Append-only replay surface for AgentRuntime decisions and results."""

    def __init__(self) -> None:
        self._entries: list[OperationLogEntry] = []

    def append(
        self,
        event: str,
        *,
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        tool_call_id: str = "",
        message: str = "",
        payload: dict[str, Any] | None = None,
    ) -> OperationLogEntry:
        entry = OperationLogEntry(
            event=event,
            room_id=room_id,
            plan_id=plan_id,
            batch_id=batch_id,
            tool_call_id=tool_call_id,
            message=message,
            payload=dict(payload or {}),
        )
        self._entries.append(entry)
        return entry

    def entries(self) -> list[OperationLogEntry]:
        return list(self._entries)

    def events(self) -> list[str]:
        return [entry.event for entry in self._entries]

    def query(
        self,
        *,
        event: str = "",
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        tool_call_id: str = "",
        limit: int | None = None,
    ) -> list[OperationLogEntry]:
        """Return ordered log entries matching the provided replay filters."""

        entries = [
            entry
            for entry in self._entries
            if (not event or entry.event == event)
            and (not room_id or entry.room_id == room_id)
            and (not plan_id or entry.plan_id == plan_id)
            and (not batch_id or entry.batch_id == batch_id)
            and (not tool_call_id or entry.tool_call_id == tool_call_id)
        ]
        if limit is None:
            return list(entries)
        safe_limit = max(0, int(limit))
        if safe_limit == 0:
            return []
        return entries[-safe_limit:]

    def snapshot(
        self,
        *,
        event: str = "",
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        tool_call_id: str = "",
        limit: int | None = None,
    ) -> dict[str, Any]:
        """Export a structured replay slice without exposing live entry objects."""

        entries = self.query(
            event=event,
            room_id=room_id,
            plan_id=plan_id,
            batch_id=batch_id,
            tool_call_id=tool_call_id,
            limit=limit,
        )
        event_counts: dict[str, int] = {}
        for entry in entries:
            event_counts[entry.event] = event_counts.get(entry.event, 0) + 1
        return {
            "filters": {
                "event": event,
                "room_id": room_id,
                "plan_id": plan_id,
                "batch_id": batch_id,
                "limit": limit,
            },
            "entry_count": len(entries),
            "event_counts": dict(sorted(event_counts.items())),
            "entries": [self._safe_entry(entry) for entry in entries],
        }

    @staticmethod
    def _safe_entry(entry: OperationLogEntry) -> dict[str, Any]:
        row = entry.as_dict()
        row.pop("tool_call_id", None)
        row["message"] = OperationLog._safe_text(entry.message)
        row["payload"] = OperationLog._safe_payload(entry.payload)
        return row

    @staticmethod
    def _safe_text(value: Any) -> str:
        text = str(value or "")
        if not text:
            return ""
        lowered = text.lower()
        blocked_tokens = (
            "api_key",
            "asset_path",
            "context_id",
            "correlation_id",
            "graph_id",
            "message_id",
            "metadata",
            "model_path",
            "patch_id",
            "payload",
            "prompt",
            "provider",
            "raw",
            "request",
            "response",
            "session_id",
            "token",
            "tool_call_id",
            "tool_name",
            "tool_payload",
            "url",
            "://",
            ":\\",
            ":/",
        )
        if any(token in lowered for token in blocked_tokens):
            return "[redacted]"
        return text

    @staticmethod
    def _safe_payload(payload: Mapping[str, Any]) -> dict[str, Any]:
        safe_keys = {
            "action",
            "action_type",
            "applied",
            "available",
            "actor_event_count",
            "actor_id",
            "asset_event_count",
            "asset_id",
            "actor_registry_failed_request_count",
            "batch_count",
            "cancelled_batches",
            "cancelled_graphs",
            "category",
            "command",
            "command_recorded",
            "context_type",
            "created",
            "confirmed_by",
            "confirmed",
            "conflict_item_count",
            "decision",
            "delta_count",
            "entry_count",
            "error_code",
            "engine_write_boundary_fact_count",
            "engine_write_import_boundary_count",
            "engine_write_environment_import_boundary_count",
            "engine_write_transform_boundary_count",
            "engine_write_delete_boundary_count",
            "engine_write_bridge_call_count",
            "engine_write_bridge_error_code_counts",
            "engine_write_bridge_failed_count",
            "engine_write_bridge_success_count",
            "engine_write_runtime_state_only_channels",
            "engine_write_runtime_state_only_count",
            "scene_entity_engine_write_pending_f5_count",
            "scene_entity_engine_write_verification_status_counts",
            "scene_entity_count",
            "game_ready_entity_count",
            "environment_entity_count",
            "planned_substrate_count",
            "materialization_status_counts",
            "event",
            "event_type",
            "execution",
            "failed_count",
            "failure_code",
            "field_count",
            "field_names",
            "fields",
            "guard_reason",
            "graph_count",
            "graph_status",
            "ground_snapped_count",
            "audience",
            "agent_name",
            "agent_id",
            "intent",
            "issue_count",
            "item_count",
            "message_kind",
            "node_count",
            "old_status",
            "new_status",
            "peer_id",
            "plan_id",
            "phase",
            "proposal_id",
            "provider_count",
            "change_key_count",
            "operation_count",
            "operation_log_event",
            "operation_log_index",
            "applied_version",
            "channel",
            "bytes_transferred",
            "chunk_count",
            "chunk_index",
            "progress",
            "reason",
            "recorded",
            "recorded_count",
            "read_only",
            "requires_write",
            "may_create_plan",
            "requires_existing_plan",
            "retryable",
            "risk_level",
            "resumed_graphs",
            "retried_graphs",
            "room_id",
            "room_status",
            "runtime_audience",
            "runtime_batch_id",
            "runtime_event_id",
            "runtime_event_type",
            "runtime_level",
            "runtime_plan_id",
            "runtime_progress",
            "runtime_stage",
            "state_version",
            "tool_call_status",
            "runtime_fact_injection_count",
            "runtime_fact_injection_field_count",
            "runtime_fact_injection_field_counts",
            "runtime_fact_injection_unique_field_count",
            "route",
            "sent",
            "source",
            "stage",
            "status",
            "sync_actor_delete_count",
            "sync_actor_transform_count",
            "sync_event_count",
            "speaker_type",
            "target_agent",
            "target_hint",
            "tool_count",
            "transfer_status",
            "total_bytes",
            "transfer_failed_count",
            "layout_transform_failure_code_counts",
            "transform_failed_count",
            "transform_result_count",
            "transform_success_count",
            "version",
            "overlap_resolved_count",
            "skipped_count",
            "applied_count",
        }
        blocked_keys = {
            "api_key",
            "asset_path",
            "context_id",
            "correlation_id",
            "graph_id",
            "headers",
            "message_id",
            "metadata",
            "model_path",
            "patch_id",
            "path",
            "payload",
            "prompt",
            "provider",
            "raw",
            "request",
            "response",
            "session_id",
            "token",
            "tool_payload",
            "url",
        }
        cleaned: dict[str, Any] = {}
        for key, value in dict(payload or {}).items():
            normalized_key = str(key or "")
            lowered = normalized_key.lower()
            if lowered in blocked_keys:
                continue
            if lowered not in safe_keys:
                continue
            if isinstance(value, str):
                cleaned[normalized_key] = OperationLog._safe_text(value)
            elif isinstance(value, (int, float, bool)) or value is None:
                cleaned[normalized_key] = value
            elif isinstance(value, (list, tuple)):
                cleaned[normalized_key] = [
                    OperationLog._safe_text(item) if isinstance(item, str) else item
                    for item in value
                    if isinstance(item, (str, int, float, bool))
                ][:10]
            elif isinstance(value, Mapping):
                if normalized_key in {
                    "engine_write_bridge_error_code_counts",
                    "environment_import_failure_code_counts",
                    "import_failure_code_counts",
                    "layout_transform_failure_code_counts",
                    "materialization_status_counts",
                    "resource_phase_failure_code_counts",
                    "runtime_fact_injection_field_counts",
                    "sync_failure_code_counts",
                }:
                    count_map: dict[str, int] = {}
                    for nested_key, nested_value in dict(value).items():
                        safe_key = OperationLog._safe_text(str(nested_key or "")).strip()
                        if not safe_key or safe_key == "[redacted]":
                            continue
                        try:
                            count = int(nested_value or 0)
                        except (TypeError, ValueError):
                            continue
                        if count > 0:
                            count_map[safe_key[:80]] = count
                    if count_map:
                        cleaned[normalized_key] = dict(sorted(count_map.items()))
                    continue
                nested = OperationLog._safe_payload(value)
                if nested:
                    cleaned[normalized_key] = nested
        return cleaned


@dataclass
class StatePatch:
    """Versioned RuntimeState patch.

    ToolResult returns patches; only RuntimeState.apply_patch() can merge them.
    """

    room_id: str
    changes: dict[str, Any]
    expected_version: int | None = None
    source_tool_call_id: str = ""
    patch_id: str = field(default_factory=lambda: _id("patch"))
    operations: list[dict[str, Any]] = field(default_factory=list)


@dataclass
class RuntimeEvent:
    """User-visible Runtime event emitted from RuntimeState/OperationLog facts."""

    event_id: str
    room_id: str
    event_type: str
    title: str
    message: str
    plan_id: str = ""
    batch_id: str = ""
    tool_call_id: str = ""
    phase: str = ""
    audience: str = "host"
    level: str = "info"
    progress: int | None = None
    payload: dict[str, Any] = field(default_factory=dict)
    timestamp: float = field(default_factory=_now)

    def as_dict(self) -> dict[str, Any]:
        RuntimeEventValidator.validate(self)
        row = {
            "event_id": self.event_id,
            "room_id": self.room_id,
            "plan_id": self.plan_id,
            "batch_id": self.batch_id,
            "event_type": self.event_type,
            "phase": self.phase,
            "audience": self.audience,
            "level": self.level,
            "title": RuntimeEventValidator.safe_text(self.title),
            "message": RuntimeEventValidator.safe_text(self.message),
            "payload": RuntimeEventValidator.safe_payload(self.payload),
            "timestamp": self.timestamp,
        }
        if self.progress is not None:
            row["progress"] = max(0, min(100, int(self.progress)))
        return row


