@dataclass
class ToolCallGraph:
    graph_id: str
    plan_id: str
    batch_id: str = ""
    nodes: dict[str, ToolCall] = field(default_factory=dict)
    edges: list[tuple[str, str]] = field(default_factory=list)
    status: str = "planned"
    generation: int = 0
    graph_role: str = "internal_state"

    def add(self, call: ToolCall) -> ToolCall:
        self.nodes[call.tool_call_id] = call
        for dependency in call.depends_on:
            self.edges.append((dependency, call.tool_call_id))
        return call

    def ready_calls(self) -> list[ToolCall]:
        ready: list[ToolCall] = []
        for call in self.nodes.values():
            if call.status not in {ToolCallStatus.PLANNED, ToolCallStatus.READY}:
                continue
            dependencies_done = all(
                self.nodes.get(dep) and self.nodes[dep].status == ToolCallStatus.SUCCEEDED
                for dep in call.depends_on
            )
            if dependencies_done:
                call.status = ToolCallStatus.READY
                ready.append(call)
        return ready

    def as_dict(self) -> dict[str, Any]:
        return {
            "graph_id": self.graph_id,
            "plan_id": self.plan_id,
            "batch_id": self.batch_id,
            "status": self.status,
            "generation": self.generation,
            "graph_role": self.graph_role,
            "edges": [list(edge) for edge in self.edges],
            "nodes": {key: call.as_dict() for key, call in self.nodes.items()},
        }


