    _PLAN_ACTIONS = frozenset({"plan", "draft", "propose", "plan_drafting", "draft_plan", "planning"})
    _PLAN_UPDATE_ACTIONS = frozenset({"plan_supplement", "supplement_plan", "revise_plan", "update_plan"})

    _READ_ONLY_MESSAGE_ACTIONS = (
        _TOOL_MANIFEST_ACTIONS
        | _OPERATION_REPLAY_ACTIONS
        | _GM_SUMMARY_ACTIONS
        | _STATUS_QUERY_ACTIONS
        | _ENTITY_STATUS_ACTIONS
        | _SCENE_WORLD_SNAPSHOT_ACTIONS
        | _R3_READINESS_ACTIONS
        | _SCENE_WORLD_CONSISTENCY_ACTIONS
        | _RUNTIME_EVENT_ACTIONS
        | _SYNC_STATUS_ACTIONS
        | _ENGINE_WRITE_STATUS_ACTIONS
    )
    _NO_PLAN_CREATION_ACTIONS = (
        _PROVIDER_STATUS_ACTIONS
        | _ENGINE_WRITE_STATUS_ACTIONS
        | _STATE_PATCH_RECONCILE_ACTIONS
        | _TOOL_MANIFEST_ACTIONS
        | _OPERATION_REPLAY_ACTIONS
        | _REPORT_ACTIONS
        | _REVIEW_ADVISORY_PROPOSAL_ACTIONS
        | _REVIEW_ADVISORY_CONFIRM_ACTIONS
        | _SYNC_EVENT_ACTIONS
        | _SYNC_STATUS_ACTIONS
        | _SCENE_SNAPSHOT_STATUS_ACTIONS
        | _GM_SUMMARY_ACTIONS
        | _STATUS_QUERY_ACTIONS
        | _ENTITY_STATUS_ACTIONS
        | _SCENE_WORLD_SNAPSHOT_ACTIONS
        | _R3_READINESS_ACTIONS
        | _SCENE_WORLD_CONSISTENCY_ACTIONS
        | _AUDIT_EVENT_ACTIONS
        | _WORKER_DRAIN_ACTIONS
        | _RUNTIME_COMMAND_ACTIONS
        | _FINAL_ADJUSTMENT_CONFIRM_ACTIONS
        | _CONFIRM_LAYOUT_ACTIONS
        | _ENQUEUE_INTERVENTION_ACTIONS
        | _PENDING_INTERVENTION_ADJUSTMENT_ACTIONS
        | _PENDING_INTERVENTION_DELETE_ADVISORY_ACTIONS
        | _CONFIRMED_DELETE_ADVISORY_EXECUTION_ACTIONS
        | _FINAL_ADJUSTMENT_ACTIONS
        | _INTERVENTION_ACTIONS
    )

    @staticmethod
    def normalize_message_action(action: str) -> str:
        return str(action or "plan").strip().lower()

    @classmethod
    def message_action_policy(cls, action: str) -> dict[str, Any]:
        normalized = cls.normalize_message_action(action)
        if normalized in cls._READ_ONLY_MESSAGE_ACTIONS:
            category = RuntimeMessageActionCategory.READ_ONLY.value
        elif normalized in cls._NO_PLAN_CREATION_ACTIONS or normalized in cls._CONTEXT_ACTIONS:
            category = RuntimeMessageActionCategory.STATE_WRITE.value
        elif normalized in cls._GENERATION_QUEUE_ACTIONS or normalized in cls._GENERATION_EXECUTE_ACTIONS:
            category = RuntimeMessageActionCategory.EXECUTION.value
        elif normalized in cls._PLAN_ACTIONS or normalized in cls._PLAN_UPDATE_ACTIONS:
            category = RuntimeMessageActionCategory.PLAN_WRITE.value
        else:
            category = RuntimeMessageActionCategory.UNKNOWN.value
        safe_action = normalized if category != RuntimeMessageActionCategory.UNKNOWN.value else "__unknown__"
        return {
            "action": safe_action,
            "category": category,
            "read_only": normalized in cls._READ_ONLY_MESSAGE_ACTIONS,
            "may_create_plan": category in {
                RuntimeMessageActionCategory.PLAN_WRITE.value,
                RuntimeMessageActionCategory.EXECUTION.value,
            },
            "requires_existing_plan": normalized in (
                cls._REPORT_ACTIONS
                | cls._REVIEW_ADVISORY_PROPOSAL_ACTIONS
                | cls._REVIEW_ADVISORY_CONFIRM_ACTIONS
                | cls._FINAL_ADJUSTMENT_ACTIONS
                | cls._FINAL_ADJUSTMENT_CONFIRM_ACTIONS
                | cls._CONFIRM_LAYOUT_ACTIONS
                | cls._ENQUEUE_INTERVENTION_ACTIONS
                | cls._CONFIRMED_DELETE_ADVISORY_EXECUTION_ACTIONS
                | cls._INTERVENTION_ACTIONS
                | cls._GENERATION_QUEUE_ACTIONS
                | cls._RUNTIME_COMMAND_ACTIONS
            ),
        }

    @staticmethod
    def _safe_audit_event_name(value: Any) -> str:
        text = str(value or "").strip().lower()
        cleaned = "".join(ch if ch.isalnum() or ch == "_" else "_" for ch in text)
        cleaned = "_".join(part for part in cleaned.split("_") if part)
        return (cleaned or "runtime_audit_event_recorded")[:96]

    def __init__(
        self,
        *,
        state: RuntimeState | None = None,
        operation_log: OperationLog | None = None,
        registry: ToolRegistry | None = None,
        guard: RuntimeGuard | None = None,
        scene_snapshot_provider: Callable[[str], dict[str, Any]] | None = None,
        scene_element_classifier: Any = None,
        image_resource_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        model_resource_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        environment_component_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        environment_import_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        actor_import_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        actor_delete_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        gameplay_manifest_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        review_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        vlm_review_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        layout_transform_provider: Callable[[dict[str, Any]], dict[str, Any]] | None = None,
        provider_diagnostics: Mapping[str, Any] | None = None,
        require_engine_environment_import: bool = False,
        require_engine_actor_import: bool = False,
        strict_image_to_model_pipeline: bool = False,
        max_queued_tool_graphs: int = 32,
    ) -> None:
        self.state = state or RuntimeState()
        self.operation_log = operation_log or OperationLog()
        self.registry = registry or ToolRegistry()
        self.guard = guard or RuntimeGuard()
        self._scene_snapshot_provider = scene_snapshot_provider
        self._scene_element_classifier = scene_element_classifier
        self._image_resource_provider = image_resource_provider
        self._model_resource_provider = model_resource_provider
        self._environment_component_provider = environment_component_provider
        self._environment_import_provider = environment_import_provider
        self._actor_import_provider = actor_import_provider
        self._actor_delete_provider = actor_delete_provider
        self._gameplay_manifest_provider = gameplay_manifest_provider
        self._review_provider = review_provider
        self._vlm_review_provider = vlm_review_provider
        self._layout_transform_provider = layout_transform_provider
        self._provider_diagnostics = self._normalize_provider_diagnostics(provider_diagnostics)
        self._require_engine_environment_import = bool(require_engine_environment_import)
        self._require_engine_actor_import = bool(require_engine_actor_import)
        self._strict_image_to_model_pipeline = bool(strict_image_to_model_pipeline)
        self._provider_summary = self._build_provider_summary()
        self._provider_readiness_event_rooms: set[str] = set()
        self._max_queued_tool_graphs = max(1, int(max_queued_tool_graphs))
        self._queued_tool_graphs: dict[str, ToolCallGraph] = {}
        self._pending_sync_event_patches: dict[str, dict[str, Any]] = {}
        self._pending_engine_readiness_patches: dict[str, dict[str, Any]] = {}
        self._report_persist_tokens: set[str] = set()
        self._finalizer_lock = RLock()
        self.scene_plans: dict[str, ScenePlan] = {}
        self.batch_plans: dict[str, BatchPlan] = {}
        self.plan_patches: dict[str, PlanPatch] = {}
        self._register_default_runtime_tools()
        self.operation_log.append(
            "runtime_provider_modes_configured",
            payload=self._provider_summary,
        )

