    def _record_pending_intervention_batch_enqueue_tool(self, call: ToolCall) -> ToolResult:
        room = str(call.args.get("room_id") or "default")
        plan_id = str(call.args.get("plan_id") or "").strip()
        batch_id = str(call.args.get("batch_id") or "").strip()
        graph_id = str(call.args.get("graph_id") or "").strip()
        changes = dict(call.args.get("changes") or {})
        if not plan_id or not batch_id or not graph_id or not changes:
            return ToolResult(
                False,
                "invalid pending intervention batch enqueue request",
                error_code="invalid_pending_intervention_batch_enqueue_request",
                user_visible_message="介入追加批队列写入缺少必要信息，已停止该步骤。",
            )
        scene_plan = dict(dict(changes.get("scene_plans") or {}).get(plan_id) or {})
        batch_plan = dict(dict(changes.get("batch_plans") or {}).get(batch_id) or {})
        graph_fact = dict(dict(changes.get("tool_graphs") or {}).get(graph_id) or {})
        queue_item = dict(dict(changes.get("tool_graph_queue") or {}).get(graph_id) or {})
        accepted_interventions = dict(changes.get("accepted_interventions") or {})
        pending_interventions = dict(changes.get("pending_interventions") or {})
        if not scene_plan or not batch_plan or not graph_fact or not queue_item:
            return ToolResult(
                False,
                "incomplete pending intervention batch enqueue state",
                error_code="incomplete_pending_intervention_batch_enqueue_state",
                user_visible_message="介入追加批队列状态不完整，已停止该步骤。",
            )
        try:
            ScenePlanValidator.validate(scene_plan)
            BatchPlanValidator.validate(batch_plan, fallback_batch_id=batch_id)
            ToolCallGraphValidator.validate_graph_fact(graph_fact, fallback_graph_id=graph_id)
            ToolCallGraphValidator.validate_queue_items({graph_id: queue_item})
            for patch_id, patch_state in accepted_interventions.items():
                PlanPatchValidator.validate(patch_state, fallback_patch_id=str(patch_id or ""))
            for patch_id, patch_state in pending_interventions.items():
                PlanPatchValidator.validate(patch_state, fallback_patch_id=str(patch_id or ""))
        except ValueError:
            return ToolResult(
                False,
                "invalid pending intervention batch enqueue state",
                error_code="invalid_pending_intervention_batch_enqueue_state",
                user_visible_message="介入追加批队列状态未通过结构校验，已停止该步骤。",
            )
        state_patch = StatePatch(
            room_id=room,
            changes=changes,
            expected_version=self.state.version,
            source_tool_call_id=call.tool_call_id,
        )
        try:
            StatePatchValidator.validate(state_patch, self.state.room(room))
        except ValueError:
            return ToolResult(
                False,
                "invalid pending intervention batch enqueue patch",
                error_code="invalid_pending_intervention_batch_enqueue_patch",
                user_visible_message="介入追加批队列状态写入未通过结构校验，已停止该步骤。",
            )
        return ToolResult(
            True,
            "pending intervention batch enqueue state recorded",
            state_patch=state_patch,
            payload={
                "status": str(scene_plan.get("status") or ""),
                "batch_status": str(batch_plan.get("status") or ""),
                "queue_status": str(queue_item.get("status") or ""),
                "graph_status": str(graph_fact.get("status") or ""),
                "accepted_count": len(accepted_interventions),
            },
        )

    def _record_plan_patch_tool(self, call: ToolCall) -> ToolResult:
        room = str(call.args.get("room_id") or "default")
        plan_id = str(call.args.get("plan_id") or "").strip()
        patch_id = str(call.args.get("patch_id") or "").strip()
        bucket = str(call.args.get("bucket") or "").strip()
        patch_data = dict(call.args.get("patch") or {})
        allowed_buckets = {
            "pending_interventions",
            "accepted_interventions",
            "deferred_interventions",
            "rejected_interventions",
        }
        if not plan_id or not patch_id or bucket not in allowed_buckets or not patch_data:
            return ToolResult(
                False,
                "invalid plan patch record request",
                error_code="invalid_plan_patch_record_request",
                user_visible_message="用户介入记录请求缺少必要信息，已停止该步骤。",
            )
        try:
            PlanPatchValidator.validate(patch_data)
        except ValueError as exc:
            return ToolResult(
                False,
                "invalid plan patch fact",
                error_code="invalid_plan_patch_fact",
                user_visible_message="用户介入记录未通过结构校验，已停止该步骤。",
            )
        return ToolResult(
            True,
            "plan patch state recorded",
            state_patch=StatePatch(
                room_id=room,
                changes={
                    "pending_interventions": {patch_id: patch_data},
                    bucket: {patch_id: patch_data},
                },
                expected_version=self.state.version,
                source_tool_call_id=call.tool_call_id,
            ),
            payload={
                "status": str(patch_data.get("status") or ""),
                "bucket": bucket,
                "patch_type": str(patch_data.get("patch_type") or ""),
            },
        )

    def _record_batch_plan_state_tool(self, call: ToolCall) -> ToolResult:
        room = str(call.args.get("room_id") or "default")
        plan_id = str(call.args.get("plan_id") or "").strip()
        changes = dict(call.args.get("changes") or {})
        batch_plans = dict(changes.get("batch_plans") or {})
        if not plan_id or not batch_plans:
            return ToolResult(
                False,
                "invalid batch plan record request",
                error_code="invalid_batch_plan_record_request",
                user_visible_message="批次规划记录请求缺少必要信息，已停止该步骤。",
            )
        try:
            for batch_id, batch_plan in batch_plans.items():
                BatchPlanValidator.validate(batch_plan, fallback_batch_id=str(batch_id))
            if "scene_plans" in changes:
                for scene_plan_id, scene_plan in dict(changes.get("scene_plans") or {}).items():
                    ScenePlanValidator.validate(scene_plan, fallback_plan_id=str(scene_plan_id))
            for key in (
                "pending_interventions",
                "accepted_interventions",
                "deferred_interventions",
                "rejected_interventions",
            ):
                if key in changes:
                    PlanPatchValidator.validate_patch_map(changes.get(key) or {}, bucket_name=key)
        except ValueError:
            return ToolResult(
                False,
                "invalid batch plan state",
                error_code="invalid_batch_plan_state",
                user_visible_message="批次规划状态未通过结构校验，已停止该步骤。",
            )
        return ToolResult(
            True,
            "batch plan state recorded",
            state_patch=StatePatch(
                room_id=room,
                changes=changes,
                expected_version=self.state.version,
                source_tool_call_id=call.tool_call_id,
            ),
            payload={
                "status": "planned",
                "batch_count": len(batch_plans),
            },
            user_visible_message=f"批次规划完成：已形成 {len(batch_plans)} 个 Runtime 批次。",
        )

    def _mark_batch_terminal_status_tool(self, call: ToolCall) -> ToolResult:
        room = str(call.args.get("room_id") or "default")
        plan_id = str(call.args.get("plan_id") or "").strip()
        batch_id = str(call.args.get("batch_id") or "").strip()
        graph_status = str(call.args.get("graph_status") or "").strip()
        if not plan_id or not batch_id:
            return ToolResult(
                False,
                "invalid batch terminal status request",
                error_code="invalid_batch_terminal_status_request",
                user_visible_message="批次终态写入缺少必要信息，已停止该步骤。",
            )
        if call.tool_name == "batch.mark_completed":
            next_status = BatchPlanStatus.COMPLETED
        elif call.tool_name == "batch.mark_partial":
            next_status = BatchPlanStatus.PARTIAL
        elif call.tool_name == "batch.mark_failed":
            next_status = BatchPlanStatus.FAILED
        elif call.tool_name == "batch.mark_cancelled":
            next_status = BatchPlanStatus.CANCELLED
        else:
            return ToolResult(
                False,
                "unsupported batch terminal status tool",
                error_code="unsupported_batch_terminal_status_tool",
                user_visible_message="批次终态工具未被识别，已停止该步骤。",
            )
        batch_plan = dict(dict(self.state.room(room).get("batch_plans") or {}).get(batch_id) or {})
        if not batch_plan:
            return ToolResult(
                False,
                "batch plan not found",
                error_code="batch_plan_not_found",
                user_visible_message="批次终态写入找不到对应 Runtime 批次，已停止该步骤。",
            )
        batch_plan["batch_id"] = str(batch_plan.get("batch_id") or batch_id)
        batch_plan["plan_id"] = str(batch_plan.get("plan_id") or plan_id)
        batch_plan["room_id"] = str(batch_plan.get("room_id") or room)
        batch_plan["status"] = next_status.value
        batch_plan["updated_at"] = _now()
        try:
            BatchPlanValidator.validate(batch_plan, fallback_batch_id=batch_id)
        except ValueError:
            return ToolResult(
                False,
                "invalid batch terminal status state",
                error_code="invalid_batch_terminal_status_state",
                user_visible_message="批次终态状态未通过结构校验，已停止该步骤。",
            )
        return ToolResult(
            True,
            "batch terminal status recorded",
            state_patch=StatePatch(
                room_id=room,
                changes={"batch_plans": {batch_id: batch_plan}},
                expected_version=self.state.version,
                source_tool_call_id=call.tool_call_id,
            ),
            payload={
                "batch_status": next_status.value,
                "graph_status": graph_status,
            },
        )

