    def _record_runtime_events_snapshot_tool(self, call: ToolCall) -> ToolResult:
        room = str(call.args.get("room_id") or "default")
        source_room = str(call.args.get("source_room_id") or "").strip()
        plan_id = str(call.args.get("plan_id") or "").strip()
