    @staticmethod
    def _snapshot_failure_audit_payload(
        *,
        summary_type: str,
        reason: Any,
        event: str = "",
        limit: Any = None,
        external_plan_id: str = "",
    ) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "summary_type": AgentRuntime._safe_report_text(summary_type).replace("_", "-")[:80],
            "recorded": False,
            "failure_code": "snapshot_record_failed",
            "reason": AgentRuntime._safe_report_text(reason or "unknown")[:160],
        }
        if event:
            payload["event"] = AgentRuntime._safe_report_text(event)[:80]
        if limit is not None:
            payload["limit"] = limit
        if external_plan_id:
            payload["external_plan_id"] = AgentRuntime._safe_report_text(external_plan_id)[:120]
        return payload

    @staticmethod
    def _runtime_event_snapshot_summary(
        events: Iterable[Mapping[str, Any]],
        *,
        audience: str = "",
        limit: Any = None,
    ) -> dict[str, Any]:
        rows = [dict(event) for event in events if isinstance(event, Mapping)]
        event_type_counts: dict[str, int] = {}
        level_counts: dict[str, int] = {}
        audience_counts: dict[str, int] = {}
        progress_event_count = 0
        latest_event_type = ""
        for row in rows:
            event_type = AgentRuntime._safe_report_text(row.get("event_type")).replace("_", "-")[:64]
            level = AgentRuntime._safe_report_text(row.get("level") or "info").replace("_", "-")[:32]
            row_audience = AgentRuntime._safe_report_text(row.get("audience") or "host").replace("_", "-")[:32]
            if event_type:
                event_type_counts[event_type] = event_type_counts.get(event_type, 0) + 1
                latest_event_type = event_type
            if level:
                level_counts[level] = level_counts.get(level, 0) + 1
            if row_audience:
                audience_counts[row_audience] = audience_counts.get(row_audience, 0) + 1
            if row.get("progress") is not None:
                progress_event_count += 1
        return {
            "event_count": len(rows),
            "requested_audience": AgentRuntime._safe_report_text(audience).replace("_", "-")[:32],
            "limit": limit if isinstance(limit, int) or limit is None else None,
            "event_type_counts": dict(sorted(event_type_counts.items())),
            "level_counts": dict(sorted(level_counts.items())),
            "audience_counts": dict(sorted(audience_counts.items())),
            "progress_event_count": progress_event_count,
            "warning_count": int(level_counts.get("warning") or 0),
            "error_count": int(level_counts.get("error") or 0),
            "latest_event_type": latest_event_type,
        }

    @staticmethod
    def _ready_resource_count(resources: Mapping[str, Any]) -> int:
        failed_statuses = {"failed", "failure", "error", "missing"}
        return sum(
            1
            for resource in dict(resources or {}).values()
            if isinstance(resource, Mapping)
            and str(resource.get("status") or "").strip().lower() not in failed_statuses
        )

    @staticmethod
    def _importable_model_resource_count(resources: Mapping[str, Any]) -> int:
        failed_statuses = {"failed", "failure", "error", "missing", "pending", "queued", "running"}
        return sum(
            1
            for resource in dict(resources or {}).values()
            if isinstance(resource, Mapping)
            and str(resource.get("status") or "").strip().lower() not in failed_statuses
            and bool(str(resource.get("local_path") or resource.get("model_path") or "").strip())
        )

    @staticmethod
    def _classification_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        batch_ids = [
            str(batch.get("batch_id") or "")
            for batch in dict(room.get("batch_plans") or {}).values()
            if isinstance(batch, Mapping)
            and (not active_plan_id or str(batch.get("plan_id") or "") == active_plan_id)
        ]
        if active_batch_id:
            batch_ids = [batch for batch in batch_ids if batch == active_batch_id]
        candidate_keys = batch_ids if batch_ids else [key for key in [active_plan_id] if key]
        routes_by_key = dict(room.get("element_routes") or {})
        model_lists = dict(room.get("model_item_lists") or {})
        summaries = dict(room.get("classification_summaries") or {})
        if not candidate_keys:
            candidate_keys = list(routes_by_key) or list(model_lists) or list(summaries)

        def add_unique(target: list[str], value: Any) -> None:
            text = str(value or "").strip()
            if text and text not in target:
                target.append(text)

        model_items: list[str] = []
        substrate_items: list[str] = []
        layout_items: list[str] = []
        guarded_items: list[str] = []
        summary_texts: list[str] = []
        route_count = 0
        for key in candidate_keys:
            summary_text = str(summaries.get(key) or "").strip()
            if summary_text and summary_text not in summary_texts:
                summary_texts.append(summary_text[:360])
            routes = routes_by_key.get(key, [])
            if not isinstance(routes, list) or not routes:
                for item in model_lists.get(key, []) if isinstance(model_lists.get(key, []), list) else []:
                    add_unique(model_items, item)
                continue
            for route in routes:
                if not isinstance(route, Mapping):
                    continue
                route_count += 1
                name = str(route.get("name") or "").strip()
                if not name:
                    continue
                pipeline = str(route.get("target_pipeline") or "").strip()
                if pipeline == "model":
                    add_unique(model_items, name)
                    if str(route.get("generation_mode_hint") or "").strip():
                        add_unique(guarded_items, name)
                elif pipeline == "layout_structure":
                    add_unique(layout_items, name)
                else:
                    add_unique(substrate_items, name)
        return {
            "route_count": route_count,
            "model_items": model_items,
            "substrate_items": substrate_items,
            "layout_items": layout_items,
            "guarded_items": guarded_items,
            "summary_texts": summary_texts[-3:],
        }

    @staticmethod
    def _environment_component_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        batch_ids = [
            str(batch.get("batch_id") or "")
            for batch in dict(room.get("batch_plans") or {}).values()
            if isinstance(batch, Mapping)
            and (not active_plan_id or str(batch.get("plan_id") or "") == active_plan_id)
        ]
        if active_batch_id:
            batch_ids = [batch for batch in batch_ids if batch == active_batch_id]
        batch_lookup = {
            str(batch.get("batch_id") or ""): dict(batch)
            for batch in dict(room.get("batch_plans") or {}).values()
            if isinstance(batch, Mapping)
            and str(batch.get("batch_id") or "")
            and (not active_plan_id or str(batch.get("plan_id") or "") == active_plan_id)
            and (not active_batch_id or str(batch.get("batch_id") or "") == active_batch_id)
        }
        components_by_batch = dict(room.get("environment_components") or {})
        if batch_ids:
            candidate_keys = batch_ids
        elif active_plan_id:
            candidate_keys = []
        else:
            candidate_keys = list(components_by_batch)
        type_counts: dict[str, int] = {}
        component_status_counts: dict[str, int] = {}
        latest_components: list[dict[str, Any]] = []
        component_count = 0
        imported_component_count = 0
        seen_component_ids: set[str] = set()
        for key in candidate_keys:
            components = components_by_batch.get(key, {})
            if not isinstance(components, Mapping):
                continue
            for component in components.values():
                if not isinstance(component, Mapping):
                    continue
                component_id = str(component.get("component_id") or "").strip()
                if component_id and component_id in seen_component_ids:
                    continue
                if component_id:
                    seen_component_ids.add(component_id)
                component_type = str(component.get("component_type") or "environment").strip() or "environment"
                component_status = str(component.get("status") or "unknown").strip() or "unknown"
                type_counts[component_type] = type_counts.get(component_type, 0) + 1
                component_status_counts[component_status] = component_status_counts.get(component_status, 0) + 1
                component_count += 1
                if component_status == "imported":
                    imported_component_count += 1
                batch_info = batch_lookup.get(str(key), {})
                latest_components.append({
                    "batch_id": str(key),
                    "batch_index": int(batch_info.get("batch_index") or 0),
                    "component_id": component_id,
                    "name": str(component.get("name") or ""),
                    "component_type": component_type,
                    "status": component_status,
                    "total_batches": int(batch_info.get("total_batches") or 0),
                    "requires_engine_write": bool(component.get("requires_engine_write")),
                })
        events = [
            dict(event)
            for event in list(room.get("runtime_events") or [])
            if str(event.get("event_type") or "") in {
                "environment_components_ready",
                "environment_components_failed",
                "environment_components_imported",
                "environment_components_import_failed",
            }
            and (
                not active_plan_id
                or AgentRuntime._event_belongs_to_plan(event, active_plan_id, set(batch_ids))
            )
            and (not active_batch_id or str(event.get("batch_id") or "") == active_batch_id)
        ]
        environment_import_event_batch_ids = {
            str(event.get("batch_id") or "")
            for event in events
            if str(event.get("event_type") or "") in {
                "environment_components_imported",
                "environment_components_import_failed",
            }
            and str(event.get("batch_id") or "")
        }
        environment_import_fact_rows: list[dict[str, Any]] = []
        for key, fact in dict(room.get("custom_import_facts") or {}).items():
            if not isinstance(fact, Mapping):
                continue
            if not str(key or "").endswith(":environment_import_result"):
                continue
            fact_batch_id = str(fact.get("batch_id") or str(key).split(":", 1)[0] or "")
            if not fact_batch_id:
                continue
            if fact_batch_id in environment_import_event_batch_ids:
                continue
            if active_batch_id and fact_batch_id != active_batch_id:
                continue
            fact_plan_id = str(fact.get("plan_id") or "")
            if active_plan_id:
                if fact_plan_id and fact_plan_id != active_plan_id:
                    continue
                if not fact_plan_id:
                    if not batch_ids or fact_batch_id not in batch_ids:
                        continue
            environment_import_fact_rows.append(dict(fact))
        status_counts: dict[str, int] = {}
        requested_count = 0
        ready_count = 0
        failed_count = 0
        import_event_count = 0
        import_requested_count = 0
        imported_count = 0
        import_failed_count = 0
        import_failure_code_counts: dict[str, int] = {}
        latest_events: list[dict[str, Any]] = []
        for event in events:
            event_type = str(event.get("event_type") or "")
            payload = RuntimeEventValidator.safe_payload(dict(event.get("payload") or {}))
            status = str(payload.get("status") or event.get("level") or "unknown")
            event_requested = int(payload.get("requested_count") or 0)
            event_ready = int(payload.get("component_count") or 0)
            event_failed = int(payload.get("failed_count") or 0)
            status_counts[status] = status_counts.get(status, 0) + 1
            if event_type in {"environment_components_imported", "environment_components_import_failed"}:
                import_event_count += 1
                import_requested_count += event_requested
                imported_count += event_ready
                import_failed_count += event_failed
                for failure_code, count in dict(payload.get("environment_import_failure_code_counts") or {}).items():
                    normalized_failure_code = RuntimeEventValidator.safe_text(failure_code).strip()
                    if not normalized_failure_code:
                        continue
                    import_failure_code_counts[normalized_failure_code[:80]] = (
                        import_failure_code_counts.get(normalized_failure_code[:80], 0) + int(count or 0)
                    )
            else:
                requested_count += event_requested
                ready_count += event_ready
                failed_count += event_failed
            latest_events.append({
                "batch_id": str(event.get("batch_id") or ""),
                "batch_index": int(payload.get("batch_index") or 0),
                "event_type": event_type,
                "total_batches": int(payload.get("total_batches") or 0),
                "status": status,
                "component_count": event_ready,
                "requested_count": event_requested,
                "failed_count": event_failed,
            })
        for fact in environment_import_fact_rows:
            fact_batch_id = str(fact.get("batch_id") or "")
            batch_info = batch_lookup.get(fact_batch_id, {})
            status = str(fact.get("status") or "unknown").strip() or "unknown"
            fact_requested = int(fact.get("component_count") or fact.get("requested_count") or 0)
            fact_imported = int(fact.get("imported_count") or fact.get("ready_count") or 0)
            fact_failed = int(fact.get("failed_count") or max(0, fact_requested - fact_imported))
            status_counts[status] = status_counts.get(status, 0) + 1
            import_event_count += 1
            import_requested_count += fact_requested
            imported_count += fact_imported
            import_failed_count += fact_failed
            fact_failure_code_counts = dict(fact.get("failure_code_counts") or {})
            if not fact_failure_code_counts:
                for result in fact.get("environment_import_results") or []:
                    if not isinstance(result, Mapping):
                        continue
                    if str(result.get("status") or "").strip() not in {"failed", "error", "skipped"}:
                        continue
                    failure_code = RuntimeEventValidator.safe_text(
                        result.get("failure_code") or result.get("reason") or "environment_import_failed"
                    ).strip()
                    if failure_code:
                        fact_failure_code_counts[failure_code[:80]] = fact_failure_code_counts.get(failure_code[:80], 0) + 1
            for failure_code, count in fact_failure_code_counts.items():
                normalized_failure_code = RuntimeEventValidator.safe_text(failure_code).strip()
                if not normalized_failure_code:
                    continue
                import_failure_code_counts[normalized_failure_code[:80]] = (
                    import_failure_code_counts.get(normalized_failure_code[:80], 0) + int(count or 0)
                )
            latest_events.append({
                "batch_id": fact_batch_id,
                "batch_index": int(batch_info.get("batch_index") or 0),
                "event_type": "environment_import_result",
                "total_batches": int(batch_info.get("total_batches") or 0),
                "status": status,
                "component_count": fact_imported,
                "requested_count": fact_requested,
                "failed_count": fact_failed,
            })
        effective_ready_count = max(ready_count, component_count)
        effective_requested_count = max(requested_count, effective_ready_count)
        effective_imported_count = max(imported_count, imported_component_count)
        effective_import_requested_count = max(import_requested_count, effective_imported_count)
        return {
            "component_count": component_count,
            "event_count": len(events),
            "requested_count": effective_requested_count,
            "ready_count": effective_ready_count,
            "failed_count": failed_count,
            "import_event_count": import_event_count,
            "import_requested_count": effective_import_requested_count,
            "imported_count": effective_imported_count,
            "import_failed_count": import_failed_count,
            "import_failure_code_counts": dict(sorted(import_failure_code_counts.items())),
            "status_counts": dict(
                sorted((status_counts if events or environment_import_fact_rows else component_status_counts).items())
            ),
            "type_counts": dict(sorted(type_counts.items())),
            "latest_components": latest_components[-6:],
            "latest_events": latest_events[-3:],
        }

    @staticmethod
    def _review_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        active_batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id)
        reviews = dict(room.get("geometry_reviews") or {})
        vlm_checkpoint_facts = dict(room.get("custom_vlm_checkpoint_facts") or {})
        review_summary_facts = dict(room.get("custom_review_summary_facts") or {})
        status_counts: dict[str, int] = {}
        checkpoint_counts: dict[str, int] = {}
        latest_reviews: list[dict[str, Any]] = []
        latest_batch_summaries: list[dict[str, Any]] = []
        seen_batch_summary_keys: set[tuple[str, str]] = set()
        review_count = 0
        issue_count = 0
        advisory_count = 0
        for key, review in {**reviews, **vlm_checkpoint_facts}.items():
            if not isinstance(review, Mapping):
                continue
            key_text = str(key or "")
            key_parts = key_text.split(":")
            key_plan_id = key_parts[0] if key_parts else ""
            key_batch_id = key_parts[1] if len(key_parts) > 1 else ""
            review_plan_id = str(review.get("plan_id") or key_plan_id)
            review_batch_id = str(review.get("batch_id") or key_batch_id)
            if active_batch_id and review_batch_id != active_batch_id:
                continue
            if (
                active_plan_id
                and review_plan_id != active_plan_id
                and str(key) != active_plan_id
                and not (review_batch_id and review_batch_id in active_batch_ids)
            ):
                continue
            status = str(review.get("status") or "unknown").strip() or "unknown"
            checkpoint_type = str(review.get("checkpoint_type") or "geometry_review").strip() or "geometry_review"
            issues = review.get("issues") if isinstance(review.get("issues"), list) else []
            advisory_items = review.get("advisory_items") if isinstance(review.get("advisory_items"), list) else []
            advisory_item_count = int(review.get("advisory_item_count") or len(advisory_items))
            reviewed_targets = [
                str(item or "").strip()
                for item in (review.get("reviewed_targets") or [])
                if str(item or "").strip()
            ]
            status_counts[status] = status_counts.get(status, 0) + 1
            checkpoint_counts[checkpoint_type] = checkpoint_counts.get(checkpoint_type, 0) + 1
            review_count += 1
            issue_count += int(review.get("issue_count") or len(issues))
            advisory_count += advisory_item_count
            latest_reviews.append(
                {
                    "plan_id": review_plan_id,
                    "batch_id": str(review.get("batch_id") or ""),
                    "checkpoint_type": checkpoint_type,
                    "status": status,
                    "overall": str(review.get("overall") or ""),
                    "issue_count": int(review.get("issue_count") or len(issues)),
                    "advisory_count": advisory_item_count,
                    "reviewed_targets": reviewed_targets[:6],
                }
            )
        for key, summary in review_summary_facts.items():
            if not isinstance(summary, Mapping):
                continue
            key_text = str(key or "")
            key_parts = key_text.split(":")
            key_plan_id = key_parts[0] if key_parts else ""
            key_batch_id = key_parts[1] if len(key_parts) > 1 else ""
            summary_plan_id = str(summary.get("plan_id") or key_plan_id)
            summary_batch_id = str(summary.get("batch_id") or key_batch_id or key_text)
            dedupe_key = (summary_plan_id, summary_batch_id)
            if dedupe_key in seen_batch_summary_keys:
                continue
            seen_batch_summary_keys.add(dedupe_key)
            if active_batch_id and summary_batch_id != active_batch_id:
                continue
            if (
                active_plan_id
                and summary_plan_id != active_plan_id
                and str(key) != active_plan_id
                and not (summary_batch_id and summary_batch_id in active_batch_ids)
                and str(key) != f"{active_plan_id}:{summary_batch_id}"
            ):
                continue
            latest_batch_summaries.append(
                {
                    "plan_id": summary_plan_id,
                    "batch_id": summary_batch_id,
                    "status": str(summary.get("status") or "unknown"),
                    "geometry_issue_count": int(summary.get("geometry_issue_count") or 0),
                    "vlm_checkpoint_count": int(summary.get("vlm_checkpoint_count") or 0),
                    "vlm_advisory_count": int(summary.get("vlm_advisory_count") or 0),
                    "import_actor_count": int(summary.get("import_actor_count") or 0),
                    "import_ready_count": int(summary.get("import_ready_count") or 0),
                }
            )
        return {
            "review_count": review_count,
            "issue_count": issue_count,
            "advisory_count": advisory_count,
            "batch_summary_count": len(latest_batch_summaries),
            "status_counts": dict(sorted(status_counts.items())),
            "checkpoint_counts": dict(sorted(checkpoint_counts.items())),
            "latest_reviews": latest_reviews[-5:],
            "latest_batch_summaries": latest_batch_summaries[-5:],
        }

    @staticmethod
    def _summarize_geometry_facts_for_replay(facts: Mapping[str, Any]) -> dict[str, Any]:
        fact_count = 0
        aabb_actor_count = 0
        aabb_skipped_count = 0
        overlap_issue_count = 0
        status_counts: dict[str, int] = {}
        fact_type_counts: dict[str, int] = {}
        latest_fact: dict[str, Any] = {}
        for key, fact in dict(facts or {}).items():
            if not isinstance(fact, Mapping):
                continue
            fact_type = str(fact.get("fact_type") or "geometry_fact").strip() or "geometry_fact"
            status = str(fact.get("status") or "recorded").strip() or "recorded"
            fact_count += 1
            fact_type_counts[fact_type] = fact_type_counts.get(fact_type, 0) + 1
            status_counts[status] = status_counts.get(status, 0) + 1
            actor_count = int(fact.get("actor_count") or 0)
            skipped_count = int(fact.get("skipped_count") or 0)
            issue_count = int(fact.get("issue_count") or 0)
            if fact_type in {"runtime_geometry_aabb", "runtime_geometry_ground_snap"}:
                aabb_actor_count += actor_count
                aabb_skipped_count += skipped_count
            if fact_type == "runtime_geometry_overlap":
                overlap_issue_count += issue_count
            latest_fact = {
                "fact_key": AgentRuntime._safe_report_text(key)[:120],
                "fact_type": fact_type,
                "plan_id": AgentRuntime._safe_report_text(fact.get("plan_id"))[:120],
                "batch_id": AgentRuntime._safe_report_text(fact.get("batch_id"))[:120],
                "status": status,
                "actor_count": actor_count,
                "issue_count": issue_count,
                "skipped_count": skipped_count,
            }
        return {
            "fact_count": fact_count,
            "aabb_actor_count": aabb_actor_count,
            "aabb_skipped_count": aabb_skipped_count,
            "overlap_issue_count": overlap_issue_count,
            "status_counts": dict(sorted(status_counts.items())),
            "fact_type_counts": dict(sorted(fact_type_counts.items())),
            "latest_fact": latest_fact,
        }

    @staticmethod
    def _geometry_fact_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        facts = dict(room.get("custom_geometry_facts") or {})
        fact_count = 0
        aabb_actor_count = 0
        aabb_skipped_count = 0
        overlap_issue_count = 0
        status_counts: dict[str, int] = {}
        fact_type_counts: dict[str, int] = {}
        latest_facts: list[dict[str, Any]] = []
        for key, fact in facts.items():
            if not isinstance(fact, Mapping):
                continue
            key_text = str(key or "")
            key_parts = key_text.split(":")
            key_plan_id = key_parts[0] if key_parts else ""
            key_batch_id = key_parts[1] if len(key_parts) > 1 else ""
            fact_plan_id = str(fact.get("plan_id") or key_plan_id)
            fact_batch_id = str(fact.get("batch_id") or key_batch_id)
            if active_plan_id and fact_plan_id != active_plan_id and str(key) != active_plan_id:
                continue
            if active_batch_id and fact_batch_id != active_batch_id:
                continue
            fact_type = str(fact.get("fact_type") or "geometry_fact").strip() or "geometry_fact"
            status = str(fact.get("status") or "recorded").strip() or "recorded"
            fact_count += 1
            fact_type_counts[fact_type] = fact_type_counts.get(fact_type, 0) + 1
            status_counts[status] = status_counts.get(status, 0) + 1
            aabb_actor_count += (
                int(fact.get("actor_count") or 0)
                if fact_type in {"runtime_geometry_aabb", "runtime_geometry_ground_snap"}
                else 0
            )
            aabb_skipped_count += (
                int(fact.get("skipped_count") or 0)
                if fact_type in {"runtime_geometry_aabb", "runtime_geometry_ground_snap"}
                else 0
            )
            overlap_issue_count += int(fact.get("issue_count") or 0) if fact_type == "runtime_geometry_overlap" else 0
            latest_facts.append(
                {
                    "fact_type": fact_type,
                    "plan_id": fact_plan_id,
                    "batch_id": fact_batch_id,
                    "status": status,
                    "actor_count": int(fact.get("actor_count") or 0),
                    "issue_count": int(fact.get("issue_count") or 0),
                    "skipped_count": int(fact.get("skipped_count") or 0),
                }
            )
        return {
            "fact_count": fact_count,
            "aabb_actor_count": aabb_actor_count,
            "aabb_skipped_count": aabb_skipped_count,
            "overlap_issue_count": overlap_issue_count,
            "status_counts": dict(sorted(status_counts.items())),
            "fact_type_counts": dict(sorted(fact_type_counts.items())),
            "latest_facts": latest_facts[-5:],
        }

    @staticmethod
    def _review_advisory_proposal_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        proposals = dict(room.get("review_advisory_proposals") or {})
        status_counts: dict[str, int] = {}
        proposal_rows: list[dict[str, Any]] = []
        item_count = 0
        for key, proposal in proposals.items():
            if not isinstance(proposal, Mapping):
                continue
            proposal_plan_id = str(proposal.get("plan_id") or key or "")
            if active_plan_id and proposal_plan_id != active_plan_id and str(key) != active_plan_id:
                continue
            status = str(proposal.get("status") or "unknown").strip() or "unknown"
            items = proposal.get("items") if isinstance(proposal.get("items"), list) else []
            if active_batch_id:
                proposal_batch_id = str(proposal.get("batch_id") or "")
                items = [
                    item for item in items
                    if isinstance(item, Mapping)
                    and str(item.get("batch_id") or proposal_batch_id or "") == active_batch_id
                ]
                if not items:
                    continue
            status_counts[status] = status_counts.get(status, 0) + 1
            item_count += len(items)
            proposal_rows.append(
                {
                    "proposal_id": str(proposal.get("proposal_id") or ""),
                    "plan_id": proposal_plan_id,
                    "status": status,
                    "risk_level": str(proposal.get("risk_level") or "advisory"),
                    "item_count": len(items),
                    "requires_confirmation": bool(proposal.get("requires_confirmation", True)),
                    "source": str(proposal.get("source") or "review_advisory"),
                }
            )
        return {
            "proposal_count": len(proposal_rows),
            "item_count": item_count,
            "status_counts": dict(sorted(status_counts.items())),
            "latest_proposals": proposal_rows[-5:],
        }

    @staticmethod
    def _layout_adjustment_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        layout_proposals = [
            dict(item)
            for key, item in room.get("layout_adjustment_proposals", {}).items()
            if not active_plan_id or str(key) == active_plan_id or str(item.get("plan_id") or "") == active_plan_id
        ]
        status_counts: dict[str, int] = {}
        risk_counts: dict[str, int] = {}
        transform_status_counts: dict[str, int] = {}
        proposal_rows: list[dict[str, Any]] = []
        delta_count = 0
        applied_delta_count = 0
        skipped_delta_count = 0
        transform_result_count = 0
        ground_snapped_count = 0
        overlap_resolved_count = 0
        transform_failure_code_counts: dict[str, int] = {}
        seen_transform_fact_proposal_ids: set[str] = set()
        for item in layout_proposals:
            status = str(item.get("status") or "unknown").strip() or "unknown"
            risk_level = str(item.get("risk_level") or "unknown").strip() or "unknown"
            proposal_id = str(item.get("proposal_id") or "")
            if proposal_id:
                seen_transform_fact_proposal_ids.add(proposal_id)
            deltas = item.get("deltas") if isinstance(item.get("deltas"), list) else []
            applied_deltas = item.get("applied_deltas") if isinstance(item.get("applied_deltas"), list) else []
            skipped_deltas = item.get("skipped_deltas") if isinstance(item.get("skipped_deltas"), list) else []
            transform_results = (
                item.get("engine_transform_results")
                if isinstance(item.get("engine_transform_results"), list)
                else []
            )
            if active_batch_id:
                deltas = [
                    delta for delta in deltas
                    if isinstance(delta, Mapping) and str(delta.get("batch_id") or "") == active_batch_id
                ]
                applied_deltas = [
                    delta for delta in applied_deltas
                    if isinstance(delta, Mapping) and str(delta.get("batch_id") or "") == active_batch_id
                ]
                skipped_deltas = [
                    delta for delta in skipped_deltas
                    if isinstance(delta, Mapping) and str(delta.get("batch_id") or "") == active_batch_id
                ]
                transform_results = [
                    result for result in transform_results
                    if isinstance(result, Mapping) and str(result.get("batch_id") or "") == active_batch_id
                ]
                if not deltas and not applied_deltas and not skipped_deltas and not transform_results:
                    continue
            status_counts[status] = status_counts.get(status, 0) + 1
            risk_counts[risk_level] = risk_counts.get(risk_level, 0) + 1
            delta_count += len(deltas)
            applied_delta_count += len(applied_deltas)
            skipped_delta_count += len(skipped_deltas)
            transform_result_count += len(transform_results)
            for result in transform_results:
                if not isinstance(result, Mapping):
                    continue
                transform_status = str(result.get("status") or "unknown").strip() or "unknown"
                transform_status_counts[transform_status] = transform_status_counts.get(transform_status, 0) + 1
                if transform_status in {"failed", "failure", "error", "rejected"}:
                    failure_code = RuntimeEventValidator.safe_text(
                        result.get("failure_code") or result.get("reason") or "layout_transform_failed"
                    ).strip()
                    if failure_code:
                        transform_failure_code_counts[failure_code[:80]] = (
                            transform_failure_code_counts.get(failure_code[:80], 0) + 1
                        )
                if bool(result.get("ground_snapped")):
                    ground_snapped_count += 1
                if bool(result.get("overlap_resolved")):
                    overlap_resolved_count += 1
            if not transform_results:
                for applied_delta in applied_deltas:
                    if isinstance(applied_delta, Mapping) and bool(applied_delta.get("ground_snapped")):
                        ground_snapped_count += 1
            proposal_rows.append(
                {
                    "proposal_id": proposal_id,
                    "status": status,
                    "risk_level": risk_level,
                    "delta_count": len(deltas),
                    "applied_delta_count": len(applied_deltas),
                    "skipped_delta_count": len(skipped_deltas),
                    "transform_result_count": len(transform_results),
                }
            )
        for key, fact in dict(room.get("custom_report_facts") or {}).items():
            if not str(key or "").endswith(":layout_transform_result"):
                continue
            if not isinstance(fact, Mapping):
                continue
            if str(fact.get("source") or "") != "runtime_layout_transform_result":
                continue
            fact_plan_id = str(fact.get("plan_id") or "")
            if active_plan_id and fact_plan_id != active_plan_id:
                continue
            fact_batch_id = str(fact.get("batch_id") or "")
            if active_batch_id and fact_batch_id != active_batch_id:
                continue
            proposal_id = str(fact.get("proposal_id") or "")
            if proposal_id and proposal_id in seen_transform_fact_proposal_ids:
                continue
            seen_transform_fact_proposal_ids.add(proposal_id or str(key))
            status = str(fact.get("status") or "unknown").strip() or "unknown"
            status_counts[status] = status_counts.get(status, 0) + 1
            risk_counts["runtime_fact"] = risk_counts.get("runtime_fact", 0) + 1
            applied_delta_count += int(fact.get("applied_count") or 0)
            skipped_delta_count += int(fact.get("skipped_count") or 0)
            fact_transform_count = int(fact.get("transform_result_count") or 0)
            transform_result_count += fact_transform_count
            transform_success_count = int(fact.get("transform_success_count") or 0)
            transform_failed_count = int(fact.get("transform_failed_count") or 0)
            if transform_success_count:
                transform_status_counts["success"] = transform_status_counts.get("success", 0) + transform_success_count
            if transform_failed_count:
                transform_status_counts["failed"] = transform_status_counts.get("failed", 0) + transform_failed_count
            ground_snapped_count += int(fact.get("ground_snapped_count") or 0)
            overlap_resolved_count += int(fact.get("overlap_resolved_count") or 0)
            for code, value in dict(fact.get("layout_transform_failure_code_counts") or {}).items():
                safe_code = RuntimeEventValidator.safe_text(code).strip()[:80]
                if not safe_code:
                    continue
                transform_failure_code_counts[safe_code] = (
                    transform_failure_code_counts.get(safe_code, 0) + int(value or 0)
                )
            proposal_rows.append(
                {
                    "proposal_id": proposal_id,
                    "status": status,
                    "risk_level": "runtime_fact",
                    "delta_count": 0,
                    "applied_delta_count": int(fact.get("applied_count") or 0),
                    "skipped_delta_count": int(fact.get("skipped_count") or 0),
                    "transform_result_count": fact_transform_count,
                }
            )
        return {
            "proposal_count": len(proposal_rows),
            "delta_count": delta_count,
            "applied_delta_count": applied_delta_count,
            "skipped_delta_count": skipped_delta_count,
            "transform_result_count": transform_result_count,
            "ground_snapped_count": ground_snapped_count,
            "overlap_resolved_count": overlap_resolved_count,
            "status_counts": dict(sorted(status_counts.items())),
            "risk_counts": dict(sorted(risk_counts.items())),
            "transform_status_counts": dict(sorted(transform_status_counts.items())),
            "layout_transform_failure_code_counts": dict(sorted(transform_failure_code_counts.items())),
            "proposals": proposal_rows[-5:],
        }

    @staticmethod
    def _sync_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
        include_peer_count: bool = False,
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        active_batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id)
        sync_state = dict(room.get("sync_state") or {})
        actor_facts = dict(room.get("actors") or {})
        asset_facts = dict(room.get("assets") or {})

        def belongs_to_plan(event: Mapping[str, Any], fact: Mapping[str, Any]) -> bool:
            event_batch_id = str(event.get("batch_id") or "")
            fact_batch_id = str(fact.get("batch_id") or "")
            if active_batch_id:
                if event_batch_id != active_batch_id and fact_batch_id != active_batch_id:
                    return False
                if not active_plan_id:
                    return True
                event_plan_id = str(event.get("plan_id") or "")
                fact_plan_id = str(fact.get("plan_id") or "")
                if event_plan_id:
                    return event_plan_id == active_plan_id
                if fact_plan_id:
                    return fact_plan_id == active_plan_id
                return not active_batch_ids or active_batch_id in active_batch_ids
            if not active_plan_id:
                return True
            event_plan_id = str(event.get("plan_id") or "")
            fact_plan_id = str(fact.get("plan_id") or "")
            if event_plan_id:
                return event_plan_id == active_plan_id
            if fact_plan_id:
                return fact_plan_id == active_plan_id
            return (
                bool(event_batch_id and event_batch_id in active_batch_ids)
                or bool(fact_batch_id and fact_batch_id in active_batch_ids)
            )

        def fact_for_event(event: Mapping[str, Any]) -> dict[str, Any]:
            fact: dict[str, Any] = {}
            actor_id = str(event.get("actor_id") or "")
            asset_id = str(event.get("asset_id") or "")
            if actor_id:
                fact.update(dict(actor_facts.get(actor_id) or {}))
            if asset_id:
                fact.update(dict(asset_facts.get(asset_id) or {}))
            return fact

        actor_events = [
            dict(event)
            for event in dict(sync_state.get("actor_events") or {}).values()
            if isinstance(event, Mapping)
            and belongs_to_plan(event, dict(actor_facts.get(str(event.get("actor_id") or "")) or {}))
        ]
        asset_events = [
            dict(event)
            for event in dict(sync_state.get("asset_events") or {}).values()
            if isinstance(event, Mapping)
            and belongs_to_plan(event, dict(asset_facts.get(str(event.get("asset_id") or "")) or {}))
        ]
        scoped_sync_events = [
            dict(event)
            for event in list(room.get("sync_events") or [])
            if isinstance(event, Mapping) and belongs_to_plan(event, fact_for_event(event))
        ]
        last_sync_event = dict(sync_state.get("last_event") or {})
        if active_plan_id or active_batch_id:
            last_sync_event = dict(scoped_sync_events[-1]) if scoped_sync_events else {}
        scoped_event_count = len(scoped_sync_events) if scoped_sync_events else len(actor_events) + len(asset_events)
        sync_event_rows = scoped_sync_events or actor_events + asset_events
        event_type_counts: dict[str, int] = {}
        for event in sync_event_rows:
            event_type = str(event.get("event_type") or "")
            if event_type:
                event_type_counts[event_type] = event_type_counts.get(event_type, 0) + 1
        actor_transform_events = {
            "actor_transform",
            "actor_updated",
            "actor_moved",
            "actor_position",
            "actor_scaled",
            "actor_rotated",
        }
        actor_delete_events = {"actor_removed", "actor_deleted", "actor_destroyed", "actor_delete"}
        summary = {
            "event_count": scoped_event_count if (active_plan_id or active_batch_id) else int(sync_state.get("event_count") or len(room.get("sync_events") or [])),
            "room_status": str(sync_state.get("room_status") or "active"),
            "actor_event_count": len(actor_events),
            "actor_transform_count": sum(1 for event in actor_events if str(event.get("event_type") or "") in actor_transform_events),
            "actor_delete_count": sum(1 for event in actor_events if str(event.get("event_type") or "") in actor_delete_events),
            "asset_event_count": len(asset_events),
            "event_type_counts": dict(sorted(event_type_counts.items())),
            "latest_actors": [
                {
                    "actor_id": str(event.get("actor_id") or ""),
                    "actor_name": str(
                        event.get("actor_name")
                        or dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("name")
                        or ""
                    ),
                    "event_type": str(event.get("event_type") or ""),
                    "lifecycle_status": str(
                        dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("sync_lifecycle_status")
                        or ""
                    ),
                    "deleted": bool(
                        dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("deleted")
                    ),
                    "scene_name": str(
                        dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("scene_name")
                        or event.get("scene_name")
                        or ""
                    ),
                    "position": list(
                        dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("position")
                        or event.get("position")
                        or []
                    )[:3],
                    "rotation": list(
                        dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("rotation")
                        or event.get("rotation")
                        or []
                    )[:3],
                    "scale": list(
                        dict(actor_facts.get(str(event.get("actor_id") or "")) or {}).get("scale")
                        or event.get("scale")
                        or []
                    )[:3],
                }
                for event in actor_events[-5:]
            ],
            "latest_assets": [
                {
                    "asset_id": str(event.get("asset_id") or ""),
                    "event_type": str(event.get("event_type") or ""),
                    "status": str(event.get("status") or ""),
                    "timestamp": event.get("timestamp", 0),
                    "transfer_status": str(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("transfer_status")
                        or ""
                    ),
                    "ready": bool(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("ready")
                    ),
                    "failed": bool(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("failed")
                    ),
                    "progress": int(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("progress")
                        or event.get("progress")
                        or 0
                    ),
                    "chunk_index": int(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("chunk_index")
                        or event.get("chunk_index")
                        or 0
                    ),
                    "chunk_count": int(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("chunk_count")
                        or event.get("chunk_count")
                        or 0
                    ),
                    "bytes_transferred": int(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("bytes_transferred")
                        or event.get("bytes_transferred")
                        or 0
                    ),
                    "total_bytes": int(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("total_bytes")
                        or event.get("total_bytes")
                        or 0
                    ),
                    "scene_name": str(
                        dict(asset_facts.get(str(event.get("asset_id") or "")) or {}).get("scene_name")
                        or event.get("scene_name")
                        or ""
                    ),
                }
                for event in asset_events[-5:]
            ],
        }
        if include_peer_count:
            summary["peer_event_count"] = len(sync_state.get("peer_events") or {})
            summary["last_event"] = {
                "event_type": str(last_sync_event.get("event_type") or ""),
                "source": str(last_sync_event.get("source") or ""),
                "actor_id": str(last_sync_event.get("actor_id") or ""),
                "actor_name": str(last_sync_event.get("actor_name") or ""),
                "asset_id": str(last_sync_event.get("asset_id") or ""),
                "peer_id": str(last_sync_event.get("peer_id") or ""),
                "status": str(last_sync_event.get("status") or ""),
                "timestamp": last_sync_event.get("timestamp", 0),
            }
        return summary

    @staticmethod
    def _asset_transfer_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        active_batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id)
        assets = dict(room.get("assets") or {})

        def belongs_to_scope(asset: Mapping[str, Any]) -> bool:
            asset_batch_id = str(asset.get("batch_id") or "")
            if active_batch_id:
                if asset_batch_id != active_batch_id:
                    return False
                if not active_plan_id:
                    return True
                asset_plan_id = str(asset.get("plan_id") or "")
                if asset_plan_id:
                    return asset_plan_id == active_plan_id
                return not active_batch_ids or active_batch_id in active_batch_ids
            if not active_plan_id:
                return True
            asset_plan_id = str(asset.get("plan_id") or "")
            if asset_plan_id:
                return asset_plan_id == active_plan_id
            return bool(asset_batch_id and asset_batch_id in active_batch_ids)

        scoped_assets = [
            dict(asset)
            for asset in assets.values()
            if isinstance(asset, Mapping) and belongs_to_scope(asset)
        ]
        status_counts: dict[str, int] = {}
        ready_count = 0
        failed_count = 0
        bytes_transferred = 0
        total_bytes = 0
        progress_values: list[int] = []
        latest_assets: list[dict[str, Any]] = []
        for asset in scoped_assets:
            transfer_status = str(asset.get("transfer_status") or asset.get("status") or "")
            if transfer_status:
                status_counts[transfer_status] = status_counts.get(transfer_status, 0) + 1
            if bool(asset.get("ready")):
                ready_count += 1
            if bool(asset.get("failed")):
                failed_count += 1
            bytes_transferred += int(asset.get("bytes_transferred") or 0)
            total_bytes += int(asset.get("total_bytes") or 0)
            progress = int(asset.get("progress") or 0)
            if progress:
                progress_values.append(max(0, min(100, progress)))
            latest_assets.append({
                "asset_id": str(asset.get("asset_id") or ""),
                "transfer_status": transfer_status,
                "ready": bool(asset.get("ready")),
                "failed": bool(asset.get("failed")),
                "progress": max(0, min(100, progress)),
                "chunk_index": int(asset.get("chunk_index") or 0),
                "chunk_count": int(asset.get("chunk_count") or 0),
                "bytes_transferred": int(asset.get("bytes_transferred") or 0),
                "total_bytes": int(asset.get("total_bytes") or 0),
                "scene_name": str(asset.get("scene_name") or ""),
                "last_sync_event": str(asset.get("last_sync_event") or ""),
            })
        incomplete_count = max(0, len(scoped_assets) - ready_count - failed_count)
        weighted_progress = int((bytes_transferred / total_bytes) * 100) if total_bytes > 0 else 0
        if not weighted_progress and progress_values:
            weighted_progress = max(progress_values)
        return {
            "asset_count": len(scoped_assets),
            "status_counts": dict(sorted(status_counts.items())),
            "ready_count": ready_count,
            "failed_count": failed_count,
            "incomplete_count": incomplete_count,
            "transferring_count": int(status_counts.get("transferring", 0)),
            "completed_count": int(status_counts.get("completed", 0)),
            "bytes_transferred": bytes_transferred,
            "total_bytes": total_bytes,
            "overall_progress": max(0, min(100, weighted_progress)),
            "latest_assets": latest_assets[-5:],
        }

    @staticmethod
    def _sync_health_digest_for_report(
        *,
        sync_summary: Mapping[str, Any],
        asset_transfer_summary: Mapping[str, Any],
        sync_replay_summary: Mapping[str, Any] | None = None,
        message_delivery_summary: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        sync = dict(sync_summary or {})
        asset = dict(asset_transfer_summary or {})
        replay = dict(sync_replay_summary or {})
        delivery = dict(message_delivery_summary or {})

        event_count = int(sync.get("event_count") or 0)
        actor_event_count = int(sync.get("actor_event_count") or 0)
        asset_event_count = int(sync.get("asset_event_count") or 0)
        event_type_counts = {
            str(key): int(value or 0)
            for key, value in dict(replay.get("event_type_counts") or {}).items()
        }
        actor_create_count = sum(
            int(event_type_counts.get(key) or 0)
            for key in ("actor_created", "actor_added", "actor_imported")
        )
        actor_transform_count = int(replay.get("actor_transform_count") or 0)
        actor_delete_count = int(replay.get("actor_delete_count") or 0)
        latest_actors = [
            dict(item)
            for item in list(sync.get("latest_actors") or [])
            if isinstance(item, Mapping)
        ]
        latest_active_actor_count = sum(
            1
            for item in latest_actors
            if str(item.get("lifecycle_status") or "") == "active"
            and not bool(item.get("deleted"))
        )
        latest_deleted_actor_count = sum(
            1
            for item in latest_actors
            if bool(item.get("deleted")) or str(item.get("lifecycle_status") or "") == "deleted"
        )
        asset_count = int(asset.get("asset_count") or 0)
        ready_count = int(asset.get("ready_count") or 0)
        failed_count = int(asset.get("failed_count") or 0)
        incomplete_count = int(asset.get("incomplete_count") or max(0, asset_count - ready_count - failed_count))
        transferring_count = int(asset.get("transferring_count") or 0)
        completed_count = int(asset.get("completed_count") or 0)
        peer_join_count = int(replay.get("peer_join_count") or 0)
        peer_leave_count = int(replay.get("peer_leave_count") or 0)
        room_close_count = int(replay.get("room_close_count") or 0)
        latest_peer_id = str(replay.get("latest_peer_id") or "")
        latest_peer_event_type = str(replay.get("latest_peer_event_type") or "")
        latest_room_status = str(replay.get("latest_room_status") or sync.get("room_status") or "")
        transfer_failed_count = int(replay.get("transfer_failed_count") or 0)
        transfer_progress_count = int(replay.get("transfer_progress_count") or 0)
        sync_failure_code_counts = {
            str(key): int(value or 0)
            for key, value in dict(replay.get("failure_code_counts") or {}).items()
        }
        latest_sync_failure_code = str(replay.get("latest_failure_code") or "")
        message_delivery_failed_count = int(delivery.get("failed_count") or 0)
        message_delivery_requested_count = int(delivery.get("requested_count") or 0)
        overall_progress = int(asset.get("overall_progress") or replay.get("latest_transfer_progress") or 0)

        needs_attention: list[str] = []
        if room_close_count or latest_room_status == "closed":
            needs_attention.append("room_closed")
        if failed_count or transfer_failed_count:
            needs_attention.append("asset_transfer_failed")
        if message_delivery_failed_count:
            needs_attention.append("message_delivery_failed")
        if transferring_count:
            needs_attention.append("asset_transfer_in_progress")
        if incomplete_count and not transferring_count:
            needs_attention.append("asset_transfer_incomplete")

        if room_close_count or latest_room_status == "closed" or failed_count or transfer_failed_count or message_delivery_failed_count:
            status = "needs_attention"
        elif transferring_count or (asset_count and ready_count < asset_count):
            status = "partial"
        elif event_count or actor_event_count or asset_event_count or asset_count or int(replay.get("recorded_count") or 0):
            status = "healthy"
        else:
            status = "no_sync_facts"

        return {
            "status": status,
            "room_status": str(sync.get("room_status") or ""),
            "latest_room_status": latest_room_status,
            "event_count": event_count,
            "peer_join_count": peer_join_count,
            "peer_leave_count": peer_leave_count,
            "room_close_count": room_close_count,
            "latest_peer_id": latest_peer_id,
            "latest_peer_event_type": latest_peer_event_type,
            "actor_event_count": actor_event_count,
            "actor_create_count": actor_create_count,
            "actor_transform_count": actor_transform_count,
            "actor_delete_count": actor_delete_count,
            "latest_actor_count": len(latest_actors),
            "latest_active_actor_count": latest_active_actor_count,
            "latest_deleted_actor_count": latest_deleted_actor_count,
            "asset_event_count": asset_event_count,
            "asset_count": asset_count,
            "asset_ready_count": ready_count,
            "asset_completed_count": completed_count,
            "asset_transferring_count": transferring_count,
            "asset_incomplete_count": incomplete_count,
            "asset_failed_count": failed_count,
            "asset_overall_progress": max(0, min(100, overall_progress)),
            "transfer_failed_count": transfer_failed_count,
            "transfer_progress_count": transfer_progress_count,
            "sync_failure_code_counts": dict(sorted(sync_failure_code_counts.items())),
            "latest_sync_failure_code": latest_sync_failure_code,
            "message_delivery_requested_count": message_delivery_requested_count,
            "message_delivery_failed_count": message_delivery_failed_count,
            "needs_attention": sorted(set(needs_attention)),
        }

    @staticmethod
    def _report_health_summary(
        *,
        batch_resource_flow_summary: Mapping[str, Any],
        import_summary: Mapping[str, Any],
        sync_health_digest: Mapping[str, Any],
        resource_summary: Mapping[str, Any] | None = None,
        environment_component_summary: Mapping[str, Any] | None = None,
        engine_write_summary: Mapping[str, Any] | None = None,
        scene_entity_registry: Mapping[str, Any] | None = None,
        worker_drain_replay_summary: Mapping[str, Any] | None = None,
        tool_queue_health_summary: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        batch_flow = dict(batch_resource_flow_summary or {})
        import_state = dict(import_summary or {})
        sync_health = dict(sync_health_digest or {})
        resource_state = dict(resource_summary or {})
        environment_state = dict(environment_component_summary or {})
        engine_write_state = dict(engine_write_summary or {})
        registry_state = dict(scene_entity_registry or {})
        worker_drain_state = dict(worker_drain_replay_summary or {})
        queue_health_state = dict(tool_queue_health_summary or {})
        batch_failed_count = int(batch_flow.get("failed_count") or 0)
        batch_partial_count = int(batch_flow.get("partial_count") or 0)
        batch_waiting_count = int(batch_flow.get("waiting_count") or 0)
        import_failed_count = int(import_state.get("failed_count") or 0)
        import_requested_count = int(import_state.get("requested_count") or 0)
        import_imported_count = int(import_state.get("imported_count") or 0)
        environment_failed_count = int(environment_state.get("failed_count") or 0)
        environment_import_failed_count = int(environment_state.get("import_failed_count") or 0)
        environment_import_requested_count = int(environment_state.get("import_requested_count") or 0)
        environment_imported_count = int(environment_state.get("imported_count") or 0)
        environment_import_failure_code_counts = {
            str(key): int(value)
            for key, value in dict(environment_state.get("import_failure_code_counts") or {}).items()
            if str(key or "").strip()
        }
        asset_incomplete_count = int(sync_health.get("asset_incomplete_count") or 0)
        asset_failed_count = int(sync_health.get("asset_failed_count") or 0)
        asset_transferring_count = int(sync_health.get("asset_transferring_count") or 0)
        asset_overall_progress = int(sync_health.get("asset_overall_progress") or 0)
        sync_actor_transform_count = int(sync_health.get("actor_transform_count") or 0)
        sync_actor_delete_count = int(sync_health.get("actor_delete_count") or 0)
        sync_status = str(sync_health.get("status") or "")
        sync_failure_code_counts = {
            str(key): int(value)
            for key, value in dict(sync_health.get("sync_failure_code_counts") or {}).items()
            if str(key or "").strip()
        }
        latest_sync_failure_code = str(sync_health.get("latest_sync_failure_code") or "")
        engine_write_readiness_mismatch_count = int(
            engine_write_state.get("readiness_mismatch_count") or 0
        )
        engine_write_readiness_mismatch_channels = [
            str(item).strip().replace("_", "-")[:48]
            for item in list(engine_write_state.get("readiness_mismatch_channels") or [])[:8]
            if str(item).strip()
        ]
        engine_write_runtime_state_only_count = int(
            engine_write_state.get("runtime_state_only_write_attempt_count") or 0
        )
        engine_write_bridge_failed_count = int(
            engine_write_state.get("engine_write_bridge_failed_count")
            or engine_write_state.get("bridge_failed_count")
            or 0
        )
        engine_write_bridge_error_code_counts = {
            str(key): int(value)
            for key, value in dict(engine_write_state.get("engine_write_bridge_error_code_counts") or {}).items()
            if str(key or "").strip()
        }
        latest_engine_write_status_export = (
            engine_write_state.get("latest_status_export")
            if isinstance(engine_write_state.get("latest_status_export"), Mapping)
            else {}
        )
        engine_write_runtime_state_only_channels = [
            str(item).strip().replace("_", "-")[:48]
            for item in list(
                latest_engine_write_status_export.get(
                    "engine_write_readiness_runtime_state_only_channels"
                )
                or []
            )[:8]
            if str(item).strip()
        ]
        if engine_write_runtime_state_only_count and not engine_write_runtime_state_only_channels:
            engine_write_runtime_state_only_channels = (
                AgentRuntime._infer_engine_write_runtime_state_only_channels(engine_write_state)
            )
        actor_registry_readiness_status = str(registry_state.get("readiness_status") or "").strip()
        actor_registry_count = int(registry_state.get("actor_count") or 0)
        actor_registry_missing_transform_count = int(registry_state.get("missing_transform_count") or 0)
        actor_registry_missing_aabb_count = int(registry_state.get("missing_aabb_count") or 0)
        actor_registry_estimated_aabb_count = int(registry_state.get("estimated_actor_bounds_count") or 0)
        actor_registry_failed_request_count = int(registry_state.get("failed_actor_request_count") or 0)
        scene_entity_engine_write_pending_f5_count = int(
            registry_state.get("engine_write_pending_f5_count") or 0
        )
        scene_entity_engine_write_verification_status_counts = {
            str(key): int(value or 0)
            for key, value in dict(
                registry_state.get("engine_write_verification_status_counts") or {}
            ).items()
            if str(key or "").strip()
        }
        materialization_status_counts = {
            str(key): int(value or 0)
            for key, value in dict(registry_state.get("materialization_status_counts") or {}).items()
            if str(key or "").strip()
        }
        game_ready_needs_review_count = int(
            materialization_status_counts.get("engine_ready_needs_review") or 0
        )
        registry_entities = [
            dict(entity)
            for entity in list(registry_state.get("entities") or [])
            if isinstance(entity, Mapping)
        ]
        verified_actor_count = sum(
            1
            for entity in registry_entities
            if str(entity.get("entity_type") or "") == "actor"
            and str(entity.get("engine_write_verification_status") or "") == "engine_verified"
        )
        verified_environment_count = sum(
            1
            for entity in registry_entities
            if str(entity.get("entity_type") or "") == "environment"
            and str(entity.get("engine_write_verification_status") or "") == "engine_verified"
        )
        resolved_mismatch_channels: set[str] = set()
        if import_imported_count > 0 and verified_actor_count >= import_imported_count:
            resolved_mismatch_channels.add("actor-import")
        if (
            environment_imported_count > 0
            and verified_environment_count >= environment_imported_count
        ):
            resolved_mismatch_channels.add("environment-import")
        if resolved_mismatch_channels:
            original_mismatch_channel_count = len(engine_write_readiness_mismatch_channels)
            engine_write_readiness_mismatch_channels = [
                channel
                for channel in engine_write_readiness_mismatch_channels
                if channel not in resolved_mismatch_channels
            ]
            resolved_count = original_mismatch_channel_count - len(
                engine_write_readiness_mismatch_channels
            )
            engine_write_readiness_mismatch_count = max(
                len(engine_write_readiness_mismatch_channels),
                engine_write_readiness_mismatch_count - resolved_count,
            )
        worker_drain_failed_count = int(worker_drain_state.get("failed_count") or 0)
        worker_drain_exception_count = int(worker_drain_state.get("exception_count") or 0)
        worker_drain_status_failed_count = int(worker_drain_state.get("status_failed_count") or 0)
        worker_drain_plan_resolve_failed_count = int(
            worker_drain_state.get("plan_resolve_failed_count") or 0
        )
        latest_worker_drain_event_raw = (
            worker_drain_state.get("latest_drain_event")
            if isinstance(worker_drain_state.get("latest_drain_event"), Mapping)
            else {}
        )
        latest_worker_drain_event = {
            "event": str(latest_worker_drain_event_raw.get("event") or "")[:80],
            "plan_id": str(latest_worker_drain_event_raw.get("plan_id") or "")[:80],
            "batch_id": str(latest_worker_drain_event_raw.get("batch_id") or "")[:80],
            "drained_count": int(latest_worker_drain_event_raw.get("drained_count") or 0),
            "reason": str(latest_worker_drain_event_raw.get("reason") or "")[:160],
        }
        if not any(value for value in latest_worker_drain_event.values()):
            latest_worker_drain_event = {}
        missing_batch_graph_ref_count = int(queue_health_state.get("missing_batch_graph_ref_count") or 0)
        missing_graph_fact_count = int(queue_health_state.get("missing_graph_fact_count") or 0)
        orphan_queue_item_count = int(queue_health_state.get("orphan_queue_item_count") or 0)
        tool_queue_failed_count = int(queue_health_state.get("failed_count") or 0)
        tool_queue_cancelled_count = int(queue_health_state.get("cancelled_count") or 0)
        tool_queue_incomplete_count = int(queue_health_state.get("incomplete_count") or 0)
        tool_queue_blocked_count = int(queue_health_state.get("blocked_count") or 0)
        actor_registry_incomplete = (
            import_imported_count > 0
            and (
                actor_registry_readiness_status not in {"", "ready"}
                or actor_registry_count <= 0
                or actor_registry_missing_transform_count > 0
                or actor_registry_missing_aabb_count > 0
            )
        )
        status_by_batch_id = {
            str(key): str(value or "unknown")
            for key, value in dict(batch_flow.get("status_by_batch_id") or {}).items()
            if str(key or "").strip()
        }
        resource_phase_failed_count = 0
        resource_phase_partial_count = 0
        resource_phase_waiting_count = 0
        resource_phase_status_counts: dict[str, int] = {}
        resource_phase_failure_code_counts: dict[str, int] = {}
        import_failure_code_counts = {
            str(key): int(value)
            for key, value in dict(batch_flow.get("import_failure_code_counts") or {}).items()
            if str(key or "").strip()
        }
        by_phase = resource_state.get("by_phase") if isinstance(resource_state.get("by_phase"), Mapping) else {}
        for phase, row in dict(by_phase or {}).items():
            if not isinstance(row, Mapping):
                continue
            phase_name = str(phase or "").strip()
            failed = int(row.get("failed_count") or 0)
            requested = int(row.get("requested_count") or 0)
            ready = int(row.get("item_count") or 0)
            status_counts = dict(row.get("status_counts") or {})
            failure_code_counts = dict(row.get("failure_code_counts") or {})
            has_status_counts = bool(status_counts)
            for status_key, count in status_counts.items():
                normalized_status = str(status_key or "unknown").strip().lower() or "unknown"
                count_value = int(count or 0)
                resource_phase_status_counts[normalized_status] = (
                    resource_phase_status_counts.get(normalized_status, 0) + count_value
                )
                if normalized_status in {"failed", "error"}:
                    resource_phase_failed_count += count_value
                elif normalized_status in {"partial", "degraded"}:
                    resource_phase_partial_count += count_value
                elif normalized_status in {"waiting", "queued", "planned", "running"}:
                    resource_phase_waiting_count += count_value
            if failed and not has_status_counts:
                resource_phase_failed_count += failed
            if requested > 0 and ready + failed < requested:
                resource_phase_partial_count += 1
            if phase_name and requested > 0 and ready == 0 and failed == 0:
                resource_phase_waiting_count += 1
            for failure_code, count in failure_code_counts.items():
                normalized_failure_code = str(failure_code or "").strip()
                if not normalized_failure_code:
                    continue
                resource_phase_failure_code_counts[normalized_failure_code] = (
                    resource_phase_failure_code_counts.get(normalized_failure_code, 0) + int(count or 0)
                )
        batch_semantic_status_counts: dict[str, int] = {}
        for status in status_by_batch_id.values():
            status_text = str(status or "unknown").strip() or "unknown"
            batch_semantic_status_counts[status_text] = batch_semantic_status_counts.get(status_text, 0) + 1
        reasons: list[str] = []
        if batch_failed_count:
            reasons.append("batch_failed")
        if import_failed_count:
            reasons.append("import_failed")
        if environment_failed_count:
            reasons.append("environment_component_failed")
        if environment_import_failed_count:
            reasons.append("environment_import_failed")
        if asset_failed_count:
            reasons.append("asset_transfer_failed")
        if resource_phase_failed_count:
            reasons.append("resource_phase_failed")
        if batch_partial_count:
            reasons.append("batch_partial")
        if resource_phase_partial_count:
            reasons.append("resource_phase_partial")
        if asset_incomplete_count:
            reasons.append("asset_transfer_incomplete")
        if asset_transferring_count:
            reasons.append("asset_transfer_in_progress")
        if sync_status in {"partial", "needs_attention"}:
            reasons.append(f"sync_{sync_status}")
        sync_failure_count = sum(int(value or 0) for value in sync_failure_code_counts.values())
        if sync_failure_count or latest_sync_failure_code:
            reasons.append("sync_failed")
        if engine_write_readiness_mismatch_count:
            reasons.append("engine_write_readiness_mismatch")
        if engine_write_runtime_state_only_count:
            reasons.append("engine_write_runtime_state_only")
        if engine_write_bridge_failed_count or engine_write_bridge_error_code_counts:
            reasons.append("engine_write_bridge_failed")
        if actor_registry_incomplete:
            reasons.append("actor_registry_incomplete")
        if actor_registry_failed_request_count:
            reasons.append("actor_registry_failed_request")
        if game_ready_needs_review_count:
            reasons.append("game_ready_entities_need_review")
        if worker_drain_failed_count:
            reasons.append("worker_drain_failed")
        if worker_drain_exception_count:
            reasons.append("worker_drain_exception")
        if worker_drain_status_failed_count:
            reasons.append("worker_drain_status_failed")
        if worker_drain_plan_resolve_failed_count:
            reasons.append("worker_drain_plan_resolve_failed")
        if missing_batch_graph_ref_count:
            reasons.append("batch_missing_tool_graph")
        if missing_graph_fact_count:
            reasons.append("tool_graph_fact_missing")
        if orphan_queue_item_count:
            reasons.append("tool_graph_queue_orphan")
        if tool_queue_failed_count:
            reasons.append("tool_graph_failed")
        if tool_queue_cancelled_count:
            reasons.append("tool_graph_cancelled")
        if tool_queue_incomplete_count:
            reasons.append("tool_graph_incomplete")
        if tool_queue_blocked_count:
            reasons.append("tool_graph_blocked")
        if batch_waiting_count:
            reasons.append("batch_waiting")
        if resource_phase_waiting_count:
            reasons.append("resource_phase_waiting")
        import_all_failed = import_failed_count > 0 and import_imported_count <= 0
        import_partial = import_failed_count > 0 and import_imported_count > 0
        environment_import_partial = environment_import_failed_count > 0 and environment_imported_count > 0
        environment_import_all_failed = (
            environment_import_failed_count > 0
            and environment_import_requested_count > 0
            and environment_imported_count <= 0
        )
        if (
            batch_failed_count
            or import_all_failed
            or asset_failed_count
            or resource_phase_failed_count
            or tool_queue_failed_count
        ):
            status = "failed"
        elif (
            batch_partial_count
            or import_partial
            or environment_import_partial
            or environment_import_all_failed
            or environment_failed_count
            or resource_phase_partial_count
            or asset_incomplete_count
            or actor_registry_incomplete
            or sync_status == "partial"
        ):
            status = "partial"
        elif batch_waiting_count or resource_phase_waiting_count:
            status = "waiting"
        elif (
            sync_status == "needs_attention"
            or sync_failure_count
            or latest_sync_failure_code
            or engine_write_readiness_mismatch_count
            or engine_write_runtime_state_only_count
            or engine_write_bridge_failed_count
            or engine_write_bridge_error_code_counts
            or game_ready_needs_review_count
            or worker_drain_failed_count
            or worker_drain_exception_count
            or worker_drain_status_failed_count
            or worker_drain_plan_resolve_failed_count
            or missing_batch_graph_ref_count
            or missing_graph_fact_count
            or orphan_queue_item_count
            or tool_queue_failed_count
            or tool_queue_cancelled_count
            or tool_queue_incomplete_count
            or tool_queue_blocked_count
        ):
            status = "needs_attention"
        elif batch_flow.get("batch_count") or import_requested_count or sync_status:
            status = "ok"
        else:
            status = "unknown"
        return {
            "status": status,
            "attention_required": status in {"failed", "partial", "waiting", "needs_attention"},
            "reasons": list(dict.fromkeys(reasons))[:8],
            "batch_count": int(batch_flow.get("batch_count") or 0),
            "batch_failed_count": batch_failed_count,
            "batch_partial_count": batch_partial_count,
            "batch_waiting_count": batch_waiting_count,
            "batch_semantic_status_counts": dict(sorted(batch_semantic_status_counts.items())),
            "import_requested_count": import_requested_count,
            "import_imported_count": import_imported_count,
            "import_failed_count": import_failed_count,
            "environment_failed_count": environment_failed_count,
            "environment_import_requested_count": environment_import_requested_count,
            "environment_imported_count": environment_imported_count,
            "environment_import_failed_count": environment_import_failed_count,
            "environment_import_failure_code_counts": dict(
                sorted(environment_import_failure_code_counts.items())
            ),
            "resource_phase_failed_count": resource_phase_failed_count,
            "resource_phase_partial_count": resource_phase_partial_count,
            "resource_phase_waiting_count": resource_phase_waiting_count,
            "resource_phase_status_counts": dict(sorted(resource_phase_status_counts.items())),
            "resource_phase_failure_code_counts": dict(sorted(resource_phase_failure_code_counts.items())),
            "import_failure_code_counts": dict(sorted(import_failure_code_counts.items())),
            "sync_health_status": sync_status,
            "sync_actor_transform_count": sync_actor_transform_count,
            "sync_actor_delete_count": sync_actor_delete_count,
            "sync_failure_code_counts": dict(sorted(sync_failure_code_counts.items())),
            "latest_sync_failure_code": latest_sync_failure_code,
            "engine_write_readiness_mismatch_count": engine_write_readiness_mismatch_count,
            "engine_write_readiness_mismatch_channels": engine_write_readiness_mismatch_channels,
            "engine_write_runtime_state_only_count": engine_write_runtime_state_only_count,
            "engine_write_runtime_state_only_channels": engine_write_runtime_state_only_channels,
            "scene_entity_engine_write_pending_f5_count": scene_entity_engine_write_pending_f5_count,
            "scene_entity_engine_write_verification_status_counts": dict(
                sorted(scene_entity_engine_write_verification_status_counts.items())
            ),
            "game_ready_needs_review_count": game_ready_needs_review_count,
            "engine_write_bridge_failed_count": engine_write_bridge_failed_count,
            "engine_write_bridge_error_code_counts": dict(sorted(engine_write_bridge_error_code_counts.items())),
            "actor_registry_readiness_status": actor_registry_readiness_status,
            "actor_registry_actor_count": actor_registry_count,
            "actor_registry_missing_transform_count": actor_registry_missing_transform_count,
            "actor_registry_missing_aabb_count": actor_registry_missing_aabb_count,
            "actor_registry_estimated_aabb_count": actor_registry_estimated_aabb_count,
            "actor_registry_failed_request_count": actor_registry_failed_request_count,
            "worker_drain_failed_count": worker_drain_failed_count,
            "worker_drain_exception_count": worker_drain_exception_count,
            "worker_drain_status_failed_count": worker_drain_status_failed_count,
            "worker_drain_plan_resolve_failed_count": worker_drain_plan_resolve_failed_count,
            "latest_worker_drain_event": latest_worker_drain_event,
            "missing_batch_graph_ref_count": missing_batch_graph_ref_count,
            "missing_graph_fact_count": missing_graph_fact_count,
            "orphan_queue_item_count": orphan_queue_item_count,
            "tool_queue_failed_count": tool_queue_failed_count,
            "tool_queue_cancelled_count": tool_queue_cancelled_count,
            "tool_queue_incomplete_count": tool_queue_incomplete_count,
            "tool_queue_blocked_count": tool_queue_blocked_count,
            "asset_incomplete_count": asset_incomplete_count,
            "asset_failed_count": asset_failed_count,
            "asset_transferring_count": asset_transferring_count,
            "asset_overall_progress": max(0, min(100, asset_overall_progress)),
        }

    @staticmethod
    def _infer_engine_write_runtime_state_only_channels(
        engine_write_state: Mapping[str, Any] | None,
    ) -> list[str]:
        state = dict(engine_write_state or {})
        status_counts = AgentRuntime._safe_status_count_map(
            state.get("engine_write_boundary_status_counts")
            or state.get("status_counts")
        )
        if int(status_counts.get("runtime_state_only") or 0) <= 0:
            return []
        inferred: list[str] = []
        for key, channel in (
            ("import_boundary_attempt_count", "actor-import"),
            ("environment_import_boundary_attempt_count", "environment-import"),
            ("transform_boundary_attempt_count", "layout-transform"),
            ("delete_boundary_attempt_count", "actor-delete"),
        ):
            if int(state.get(key) or 0) > 0 and channel not in inferred:
                inferred.append(channel)
        if not inferred:
            inferred.append("engine-write")
        return inferred[:8]

    @staticmethod
    def _batch_ids_for_plan(room: Mapping[str, Any], plan_id: str) -> set[str]:
        active_plan_id = str(plan_id or "")
        if not active_plan_id:
            return set()
        return {
            str(batch.get("batch_id") or "")
            for batch in dict(room.get("batch_plans") or {}).values()
            if isinstance(batch, Mapping) and str(batch.get("plan_id") or "") == active_plan_id
        }

    @staticmethod
    def _batch_plan_for_batch_id(room: Mapping[str, Any], batch_id: str) -> dict[str, Any]:
        active_batch_id = str(batch_id or "")
        if not active_batch_id:
            return {}
        batch_plans = dict(room.get("batch_plans") or {})
        direct = batch_plans.get(active_batch_id)
        if isinstance(direct, Mapping):
            return dict(direct)
        for batch in batch_plans.values():
            if not isinstance(batch, Mapping):
                continue
            if str(batch.get("batch_id") or "") == active_batch_id:
                return dict(batch)
        return {}

    @staticmethod
    def _event_belongs_to_plan(
        event: Mapping[str, Any],
        plan_id: str,
        batch_ids: set[str] | None = None,
    ) -> bool:
        active_plan_id = str(plan_id or "")
        if not active_plan_id:
            return True
        event_plan_id = str(event.get("plan_id") or "")
        if event_plan_id == active_plan_id:
            return True
        if event_plan_id:
            return False
        event_batch_id = str(event.get("batch_id") or "")
        return bool(event_batch_id and event_batch_id in (batch_ids or set()))

    def _operation_log_entries_for_runtime_scope(
        self,
        *,
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        tool_call_id: str = "",
        event: str = "",
        limit: int | None = None,
    ) -> list[OperationLogEntry]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        if not active_plan_id:
            return self.operation_log.query(
                event=str(event or ""),
                room_id=str(room_id or ""),
                plan_id="",
                batch_id=active_batch_id,
                tool_call_id=str(tool_call_id or ""),
                limit=limit,
            )
        room = self.state.room(str(room_id or ""))
        active_batch_ids = self._batch_ids_for_plan(room, active_plan_id)
        entries = self.operation_log.query(
            event=str(event or ""),
            room_id=str(room_id or ""),
            plan_id="",
            batch_id=active_batch_id,
            tool_call_id=str(tool_call_id or ""),
            limit=None,
        )
        scoped = [
            entry
            for entry in entries
            if entry.plan_id == active_plan_id
            or bool((not entry.plan_id) and entry.batch_id and entry.batch_id in active_batch_ids)
        ]
        if limit is None:
            return scoped
        safe_limit = max(0, int(limit))
        if safe_limit == 0:
            return []
        return scoped[-safe_limit:]

    @staticmethod
    def _operation_log_snapshot_from_entries(
        entries: list[OperationLogEntry],
        *,
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        event: str = "",
        limit: int | None = None,
    ) -> dict[str, Any]:
        event_counts: dict[str, int] = {}
        for entry in entries:
            event_counts[entry.event] = event_counts.get(entry.event, 0) + 1
        return {
            "filters": {
                "event": str(event or ""),
                "room_id": str(room_id or ""),
                "plan_id": str(plan_id or ""),
                "batch_id": str(batch_id or ""),
                "limit": limit,
            },
            "entry_count": len(entries),
            "event_counts": dict(sorted(event_counts.items())),
            "entries": [OperationLog._safe_entry(entry) for entry in entries],
        }

    @staticmethod
    def _actor_facts_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, dict[str, Any]]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        actors = dict(room.get("actors") or {})
        if active_batch_id:
            batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id) if active_plan_id else set()
            scoped: dict[str, dict[str, Any]] = {}
            for actor_id, actor in actors.items():
                if not isinstance(actor, Mapping):
                    continue
                actor_plan_id = str(actor.get("plan_id") or "")
                actor_batch_id = str(actor.get("batch_id") or "")
                if actor_batch_id != active_batch_id:
                    continue
                if active_plan_id and actor_plan_id and actor_plan_id != active_plan_id:
                    continue
                if active_plan_id and not actor_plan_id and actor_batch_id not in batch_ids:
                    continue
                scoped[str(actor_id)] = dict(actor)
            return scoped
        if not active_plan_id:
            return {
                str(actor_id): dict(actor)
                for actor_id, actor in actors.items()
                if isinstance(actor, Mapping)
            }
        batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id)
        scoped: dict[str, dict[str, Any]] = {}
        for actor_id, actor in actors.items():
            if not isinstance(actor, Mapping):
                continue
            actor_plan_id = str(actor.get("plan_id") or "")
            actor_batch_id = str(actor.get("batch_id") or "")
            if actor_plan_id == active_plan_id or (actor_batch_id and actor_batch_id in batch_ids):
                scoped[str(actor_id)] = dict(actor)
        return scoped

    @staticmethod
    def _observed_actor_facts_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, dict[str, Any]]:
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        observed = dict(room.get("observed_actors") or {})
        if active_batch_id:
            runtime_actors = dict(room.get("actors") or {})
            batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id) if active_plan_id else set()
            scoped: dict[str, dict[str, Any]] = {}
            for actor_id, actor in observed.items():
                if not isinstance(actor, Mapping):
                    continue
                actor_key = str(actor_id)
                actor_plan_id = str(actor.get("plan_id") or "")
                actor_batch_id = str(actor.get("batch_id") or "")
                runtime_actor = runtime_actors.get(actor_key)
                if isinstance(runtime_actor, Mapping):
                    actor_plan_id = actor_plan_id or str(runtime_actor.get("plan_id") or "")
                    actor_batch_id = actor_batch_id or str(runtime_actor.get("batch_id") or "")
                if actor_batch_id != active_batch_id:
                    continue
                if active_plan_id and actor_plan_id and actor_plan_id != active_plan_id:
                    continue
                if active_plan_id and not actor_plan_id and actor_batch_id not in batch_ids:
                    continue
                scoped[actor_key] = dict(actor)
            return scoped
        if not active_plan_id:
            return {
                str(actor_id): dict(actor)
                for actor_id, actor in observed.items()
                if isinstance(actor, Mapping)
            }
        batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id)
        runtime_actors = dict(room.get("actors") or {})
        scoped: dict[str, dict[str, Any]] = {}
        for actor_id, actor in observed.items():
            if not isinstance(actor, Mapping):
                continue
            actor_key = str(actor_id)
            actor_plan_id = str(actor.get("plan_id") or "")
            actor_batch_id = str(actor.get("batch_id") or "")
            runtime_actor = runtime_actors.get(actor_key)
            if isinstance(runtime_actor, Mapping):
                actor_plan_id = actor_plan_id or str(runtime_actor.get("plan_id") or "")
                actor_batch_id = actor_batch_id or str(runtime_actor.get("batch_id") or "")
            if actor_plan_id == active_plan_id or (actor_batch_id and actor_batch_id in batch_ids):
                scoped[actor_key] = dict(actor)
        return scoped

    @staticmethod
    def _scene_entity_registry_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        """Return a game-facing entity registry derived from RuntimeState facts."""

        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        actors = AgentRuntime._actor_facts_for_plan(room, active_plan_id, batch_id=active_batch_id)
        observed = AgentRuntime._observed_actor_facts_for_plan(room, active_plan_id, batch_id=active_batch_id)
        classification = AgentRuntime._classification_summary_for_plan(room, active_plan_id, batch_id=active_batch_id)
        assets = dict(room.get("assets") or {})
        environment_components = dict(room.get("environment_components") or {})
        batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id) if active_plan_id else set()
        if active_batch_id:
            candidate_batch_ids = [active_batch_id]
        elif batch_ids:
            candidate_batch_ids = sorted(batch_ids)
        elif active_plan_id:
            candidate_batch_ids = []
        else:
            candidate_batch_ids = sorted(str(key) for key in environment_components)

        def vector3(value: Any) -> list[float]:
            if isinstance(value, Mapping):
                raw = [value.get("x"), value.get("y"), value.get("z")]
            elif isinstance(value, (list, tuple)):
                raw = list(value[:3])
            else:
                return []
            if len(raw) < 3:
                return []
            try:
                return [round(float(raw[0] or 0.0), 4), round(float(raw[1] or 0.0), 4), round(float(raw[2] or 0.0), 4)]
            except (TypeError, ValueError):
                return []

        def transform_from(row: Mapping[str, Any]) -> dict[str, Any]:
            position = vector3(row.get("position") or row.get("location") or row.get("translation"))
            rotation = vector3(row.get("rotation") or row.get("euler") or row.get("rotator"))
            scale = vector3(row.get("scale"))
            transform: dict[str, Any] = {}
            if position:
                transform["position"] = position
            if rotation:
                transform["rotation"] = rotation
            if scale:
                transform["scale"] = scale
            return transform

        def bounds_from(row: Mapping[str, Any]) -> dict[str, Any]:
            for key in ("aabb", "bounds", "scene_aabb", "world_aabb", "world_bounds"):
                value = row.get(key)
                if isinstance(value, Mapping):
                    return dict(value)
                if isinstance(value, (list, tuple)) and len(value) >= 6:
                    try:
                        numbers = [round(float(item or 0.0), 4) for item in list(value[:6])]
                    except (TypeError, ValueError):
                        continue
                    return {
                        "min": numbers[:3],
                        "max": numbers[3:6],
                    }
            return {}

        def safe_model_filename(row: Mapping[str, Any]) -> str:
            for key in ("model_ref", "model_path", "local_path", "path"):
                value = str(row.get(key) or "").strip()
                if not value:
                    continue
                if key == "model_ref" and "://" not in value and ":\\" not in value and "/" not in value and "\\" not in value:
                    return value[:160]
                filename = re.split(r"[\\/]", value)[-1].strip()
                if filename and "://" not in filename and ":\\" not in filename:
                    return filename[:160]
            return ""

        def actor_asset_id(row: Mapping[str, Any]) -> str:
            for key in ("asset_id", "model_asset_id", "resource_id", "model_id"):
                value = str(row.get(key) or "").strip()
                if value:
                    return value
            model_identity = str(row.get("model_ref") or "").strip() or safe_model_filename(row)
            if model_identity:
                digest = uuid.uuid5(uuid.NAMESPACE_URL, f"corona-runtime-asset:{model_identity}").hex[:24]
                return f"asset-{digest}"
            return ""

        def actor_model_ref(row: Mapping[str, Any], asset_id: str) -> str:
            for key in ("model_ref", "model_id", "resource_id"):
                value = str(row.get(key) or "").strip()
                if value:
                    if "://" not in value and ":\\" not in value and "/" not in value and "\\" not in value:
                        return value
            filename = safe_model_filename(row)
            if filename:
                return filename
            asset = assets.get(asset_id)
            if isinstance(asset, Mapping):
                for key in ("model_ref", "model_id", "resource_id"):
                    value = str(asset.get(key) or "").strip()
                    if value:
                        if "://" not in value and ":\\" not in value and "/" not in value and "\\" not in value:
                            return value
                filename = safe_model_filename(asset)
                if filename:
                    return filename
            return ""

        def list_field(row: Mapping[str, Any], key: str) -> list[Any]:
            value = row.get(key)
            if isinstance(value, list):
                return list(value)
            if isinstance(value, tuple):
                return list(value)
            if isinstance(value, str) and value.strip():
                return [value.strip()]
            return []

        def mapping_field(row: Mapping[str, Any], key: str) -> dict[str, Any]:
            value = row.get(key)
            return dict(value) if isinstance(value, Mapping) else {}

        def actor_interaction_capability(row: Mapping[str, Any]) -> list[Any]:
            return list_field(row, "interaction_capability")

        def actor_gameplay_tags(row: Mapping[str, Any]) -> list[Any]:
            return list_field(row, "gameplay_tags")

        def actor_physics_profile(row: Mapping[str, Any]) -> dict[str, Any]:
            return mapping_field(row, "physics_profile")

        def actor_script_bindings(row: Mapping[str, Any]) -> list[Any]:
            return list_field(row, "script_bindings")

        def stable_entity_id(*parts: Any) -> str:
            identity = "|".join(str(part or "").strip() for part in parts)
            return f"entity-{uuid.uuid5(uuid.NAMESPACE_URL, 'corona-runtime:' + identity).hex}"

        scene_plan = dict((room.get("scene_plans") or {}).get(active_plan_id) or {})
        peer_mirror_versions = dict(room.get("peer_mirror_scene_versions") or {})
        try:
            scene_version = max(
                1,
                int(
                    scene_plan.get("version")
                    or peer_mirror_versions.get(active_plan_id)
                    or 1
                ),
            )
        except (TypeError, ValueError):
            scene_version = 1

        def entity_version(row: Mapping[str, Any]) -> tuple[int, str]:
            for key, source in (
                ("entity_version", "entity_actual"),
                ("actor_version", "engine_actual"),
                ("version", "source_actual"),
            ):
                try:
                    value = int(row.get(key) or 0)
                except (TypeError, ValueError):
                    continue
                if value > 0:
                    return value, source
            return scene_version, "scene_version"

        def stable_request_identity(row: Mapping[str, Any]) -> str:
            for key in (
                "entity_request_id",
                "actor_request_id",
                "model_request_id",
                "asset_request_id",
                "request_id",
                "instance_id",
            ):
                value = str(row.get(key) or "").strip()
                if value:
                    return value
            return ""

        def stable_environment_asset_id(row: Mapping[str, Any], component_type: str) -> str:
            existing = str(row.get("asset_id") or "").strip()
            if existing:
                return existing
            model_identity = str(
                row.get("model_ref")
                or row.get("handler")
                or component_type
                or "environment"
            ).strip()
            digest = uuid.uuid5(
                uuid.NAMESPACE_URL,
                f"corona-runtime-environment-asset:{model_identity}",
            ).hex[:24]
            return f"asset-{digest}"

        def environment_profile_from(row: Mapping[str, Any]) -> dict[str, Any]:
            profile = mapping_field(row, "environment_profile")
            for key in ("terrain_profile", "surface", "sky_mode", "boundary_style"):
                value = str(row.get(key) or "").strip()
                if value:
                    profile[key] = value
            return profile

        def actor_sync_status(row: Mapping[str, Any], asset_id: str) -> str:
            for key in ("sync_status", "sync_lifecycle_status", "last_sync_event"):
                value = str(row.get(key) or "").strip()
                if value:
                    return value
            asset = assets.get(asset_id)
            if isinstance(asset, Mapping):
                value = str(asset.get("transfer_status") or "").strip()
                if value:
                    return value
            return "runtime_state"

        def sync_lifecycle_status(row: Mapping[str, Any], fallback: str) -> str:
            for key in ("sync_lifecycle_status", "last_sync_event", "sync_status"):
                value = str(row.get(key) or "").strip()
                if value:
                    return value
            return str(fallback or "").strip() or "runtime_state"

        def engine_write_verification_status(row: Mapping[str, Any]) -> str:
            sync_status = str(
                row.get("sync_status")
                or row.get("sync_lifecycle_status")
                or row.get("last_sync_event")
                or ""
            ).strip().lower()
            source = str(row.get("source") or "").strip().lower()
            status = str(row.get("status") or "").strip().lower()
            bounds_ready = bool(row.get("bounds_ready"))
            lifecycle = str(row.get("engine_lifecycle_status") or "").strip().lower()
            render_observed = bool(row.get("render_status_observed"))
            render_ready = bool(row.get("render_ready"))
            # A native "created" sync label is terminal only after the snapshot
            # independently proves actual bounds and render-ready geometry.
            if bounds_ready and render_observed and render_ready and lifecycle in {"bounds_ready", "engine_ready", "ready"} and sync_status in {
                "created",
                "engine_created",
                "engine_imported",
                "engine_transformed",
                "synced",
                "synchronized",
            }:
                return "engine_verified"
            if bounds_ready and render_observed and render_ready and lifecycle in {"bounds_ready", "engine_ready", "ready"} and source.startswith("engine_") and status not in {"runtime_state_only", "planned"}:
                return "engine_verified"
            if lifecycle in {"engine_loading", "engine_accepted", "import_requested"}:
                return "engine_loading"
            if status == "runtime_state_only" or sync_status == "runtime_state_only":
                return "pending_f5"
            if status in {"planned", "pending", "queued"} or sync_status in {"planned", "pending", "queued"}:
                return "planned"
            return "unknown"

        def asset_transfer_status(asset_id: str) -> dict[str, Any]:
            asset = assets.get(asset_id)
            if not isinstance(asset, Mapping):
                return {
                    "available": False,
                    "transfer_status": "",
                    "ready": False,
                    "failed": False,
                    "progress": 0,
                    "chunk_index": 0,
                    "chunk_count": 0,
                    "bytes_transferred": 0,
                    "total_bytes": 0,
                    "last_sync_event": "",
                }
            return {
                "available": True,
                "transfer_status": str(asset.get("transfer_status") or asset.get("status") or ""),
                "ready": bool(asset.get("ready")),
                "failed": bool(asset.get("failed")),
                "progress": max(0, min(100, int(asset.get("progress") or 0))),
                "chunk_index": int(asset.get("chunk_index") or 0),
                "chunk_count": int(asset.get("chunk_count") or 0),
                "bytes_transferred": int(asset.get("bytes_transferred") or 0),
                "total_bytes": int(asset.get("total_bytes") or 0),
                "last_sync_event": str(asset.get("last_sync_event") or ""),
            }

        def actor_grounding_status(row: Mapping[str, Any]) -> str:
            explicit = str(
                row.get("grounding_status") or row.get("grounded_status") or ""
            ).strip().lower()
            if explicit in {
                "grounded",
                "wall_mounted",
                "suspended",
                "ceiling_hung",
                "not_applicable",
                "enclosure",
            }:
                return explicit
            support_type = str(row.get("support_type") or "").strip().lower()
            if not support_type or support_type == "unknown":
                support_type = AgentRuntime._layout_support_type(row)
            bounds = bounds_from(row)
            min_value = bounds.get("min") if isinstance(bounds, Mapping) else None
            if (
                support_type == "floor_supported"
                and str(row.get("bounds_source") or "").strip().lower() == "engine_actual"
                and isinstance(min_value, (list, tuple))
                and len(min_value) >= 2
            ):
                try:
                    return "grounded" if abs(float(min_value[1])) <= 0.05 else "needs_review"
                except (TypeError, ValueError):
                    return "unknown"
            return explicit or "unknown"

        def entity_is_game_ready(entity: Mapping[str, Any]) -> bool:
            grounding = str(entity.get("grounding_status") or "").strip().lower()
            bounds_source = str(entity.get("bounds_source") or "").strip().lower()
            entity_type = str(entity.get("entity_type") or "").strip().lower()
            stable_resource = bool(entity.get("asset_id")) and bool(entity.get("model_ref"))
            sync_status = str(entity.get("sync_status") or "").strip().lower()
            sync_known = sync_status not in {
                "",
                "unknown",
                "partial",
                "failed",
                "needs_attention",
                "timeout",
                "timed_out",
                "abandoned",
                "cancelled",
                "deleted",
            }
            grounding_known = grounding in {
                "grounded",
                "wall_mounted",
                "suspended",
                "ceiling_hung",
                "not_applicable",
                "enclosure",
            }
            if entity_type == "environment" and grounding == "not_applicable":
                grounding_known = True
            return (
                str(entity.get("engine_write_verification_status") or "") == "engine_verified"
                and bool(entity.get("render_status_observed"))
                and bool(entity.get("render_ready"))
                and bool(entity.get("actor_id"))
                and bool(entity.get("transform"))
                and bool(entity.get("aabb"))
                and bounds_source == "engine_actual"
                and stable_resource
                and grounding_known
                and sync_known
            )

        def readiness_missing_fields(entity: Mapping[str, Any]) -> list[str]:
            missing: list[str] = []
            if not str(entity.get("actor_id") or "").strip():
                missing.append("actor_id")
            if not str(entity.get("asset_id") or "").strip():
                missing.append("asset_id")
            if not str(entity.get("model_ref") or "").strip():
                missing.append("model_ref")
            if not isinstance(entity.get("transform"), Mapping) or not entity.get("transform"):
                missing.append("transform")
            if not isinstance(entity.get("world_aabb"), Mapping) or not entity.get("world_aabb"):
                missing.append("world_aabb")
            if str(entity.get("bounds_source") or "").strip().lower() != "engine_actual":
                missing.append("engine_actual_aabb")
            if str(entity.get("engine_write_verification_status") or "") != "engine_verified":
                missing.append("engine_ready")
            if not bool(entity.get("render_status_observed")):
                missing.append("render_readiness_unobserved")
            elif not bool(entity.get("render_ready")):
                missing.append("render_not_ready")
            if str(entity.get("grounding_status") or "").strip().lower() not in {
                "grounded", "wall_mounted", "suspended", "ceiling_hung", "not_applicable", "enclosure"
            }:
                missing.append("grounding_status")
            sync_status = str(entity.get("sync_status") or "").strip().lower()
            if sync_status in {"", "unknown"}:
                missing.append("sync_status")
            elif sync_status in {
                "partial",
                "failed",
                "needs_attention",
                "timeout",
                "timed_out",
                "abandoned",
                "cancelled",
                "deleted",
            }:
                missing.append("sync_status_ready")
            return missing

        def reviewed_ok_targets() -> set[str]:
            targets: set[str] = set()
            active_batch_ids = set(candidate_batch_ids)
            for key, review in {
                **dict(room.get("geometry_reviews") or {}),
                **dict(room.get("custom_vlm_checkpoint_facts") or {}),
            }.items():
                if not isinstance(review, Mapping):
                    continue
                key_text = str(key or "")
                key_parts = key_text.split(":")
                review_plan_id = str(review.get("plan_id") or (key_parts[0] if key_parts else ""))
                review_batch_id = str(review.get("batch_id") or (key_parts[1] if len(key_parts) > 1 else ""))
                if active_plan_id and review_plan_id and review_plan_id != active_plan_id:
                    if not (review_batch_id and review_batch_id in active_batch_ids):
                        continue
                if active_batch_id and review_batch_id != active_batch_id:
                    continue
                status = str(review.get("status") or "").strip().lower()
                if status not in {"ok", "pass", "passed", "completed", "success"}:
                    continue
                issue_count = int(review.get("issue_count") or 0)
                advisory_items = review.get("advisory_items")
                advisory_count = int(
                    review.get("advisory_item_count")
                    or (len(advisory_items) if isinstance(advisory_items, list) else 0)
                )
                if issue_count > 0 or advisory_count > 0:
                    continue
                for target in list(review.get("reviewed_targets") or []):
                    text = str(target or "").strip()
                    if text:
                        targets.add(text)
            return targets

        reviewed_targets_ok = reviewed_ok_targets()

        def review_status_for(row: Mapping[str, Any], fallback_name: str) -> str:
            explicit = str(row.get("review_status") or "").strip()
            candidate_names = {
                str(fallback_name or "").strip(),
                str(row.get("name") or "").strip(),
                str(row.get("semantic_role") or "").strip(),
                str(row.get("actor_id") or "").strip(),
                str(row.get("component_id") or "").strip(),
            }
            if any(name and name in reviewed_targets_ok for name in candidate_names):
                return "reviewed_ok"
            return explicit or "pending_review"

        def add_count(target: dict[str, int], key: str) -> None:
            normalized = str(key or "unknown").strip() or "unknown"
            target[normalized] = target.get(normalized, 0) + 1

        def failed_actor_requests_for_plan() -> list[dict[str, Any]]:
            failures: list[dict[str, Any]] = []
            active_batch_ids = set(candidate_batch_ids)
            for fact_key, fact in sorted(dict(room.get("custom_import_facts") or {}).items()):
                if not str(fact_key or "").endswith(":actor_import_result"):
                    continue
                if not isinstance(fact, Mapping):
                    continue
                fact_batch_id = str(fact.get("batch_id") or str(fact_key).split(":")[0] or "")
                if active_batch_id and fact_batch_id != active_batch_id:
                    continue
                if active_plan_id and active_batch_ids and fact_batch_id and fact_batch_id not in active_batch_ids:
                    continue
                for row in fact.get("import_results") or []:
                    if not isinstance(row, Mapping):
                        continue
                    if str(row.get("status") or "").strip().lower() != "failed":
                        continue
                    actor_name = AgentRuntime._safe_report_text(
                        str(row.get("actor_name") or row.get("requested_name") or "").strip()
                    )
                    failure_code = AgentRuntime._safe_report_text(
                        str(row.get("failure_code") or row.get("error_code") or "actor_import_failed").strip()
                    )
                    reason = AgentRuntime._safe_report_text(
                        str(row.get("reason") or row.get("message") or "").strip()
                    )
                    safe_row = {
                        "batch_id": fact_batch_id,
                        "actor_name": actor_name[:120],
                        "requested_name": actor_name[:120],
                        "status": "failed",
                        "failure_code": failure_code[:120],
                    }
                    if reason:
                        safe_row["reason"] = reason[:200]
                    failures.append(safe_row)
            return failures

        def failed_environment_requests_for_plan() -> list[dict[str, Any]]:
            failures: list[dict[str, Any]] = []
            active_batch_ids = set(candidate_batch_ids)
            for fact_key, fact in sorted(dict(room.get("custom_import_facts") or {}).items()):
                if not str(fact_key or "").endswith(":environment_import_result"):
                    continue
                if not isinstance(fact, Mapping):
                    continue
                fact_batch_id = str(fact.get("batch_id") or str(fact_key).split(":")[0] or "")
                if active_batch_id and fact_batch_id != active_batch_id:
                    continue
                if active_plan_id and active_batch_ids and fact_batch_id and fact_batch_id not in active_batch_ids:
                    continue
                for row in fact.get("environment_import_results") or []:
                    if not isinstance(row, Mapping):
                        continue
                    if str(row.get("status") or "").strip().lower() != "failed":
                        continue
                    component_id = AgentRuntime._safe_report_text(
                        str(row.get("component_id") or "").strip()
                    )
                    name = AgentRuntime._safe_report_text(
                        str(row.get("name") or component_id or "").strip()
                    )
                    component_type = AgentRuntime._safe_report_text(
                        str(row.get("component_type") or "environment").strip()
                    )
                    failure_code = AgentRuntime._safe_report_text(
                        str(
                            row.get("failure_code")
                            or row.get("error_code")
                            or "environment_import_failed"
                        ).strip()
                    )
                    reason = AgentRuntime._safe_report_text(
                        str(row.get("reason") or row.get("message") or "").strip()
                    )
                    safe_row = {
                        "batch_id": fact_batch_id,
                        "component_id": component_id[:120],
                        "name": name[:120],
                        "component_type": component_type[:80],
                        "status": "failed",
                        "failure_code": failure_code[:120],
                    }
                    if reason:
                        safe_row["reason"] = reason[:200]
                    failures.append(safe_row)
            return failures

        def merge_engine_observation(
            base_row: Mapping[str, Any],
            observed_row: Any,
        ) -> dict[str, Any]:
            merged = dict(base_row)
            if isinstance(observed_row, Mapping):
                observed_values = dict(observed_row)
                observed_actual_bounds = (
                    bool(observed_values.get("bounds_ready"))
                    and str(observed_values.get("bounds_source") or "").strip().lower()
                    == "engine_actual"
                    and bool(bounds_from(observed_values))
                )
                observed_render_status = bool(
                    observed_values.get("render_status_observed")
                )
                authoritative_keys: set[str] = set()
                if observed_actual_bounds:
                    authoritative_keys.update({
                        "position", "location", "translation",
                        "rotation", "euler", "rotator", "scale",
                        "aabb", "bounds", "scene_aabb", "world_aabb", "world_bounds",
                        "bounds_ready", "bounds_source",
                        "engine_lifecycle_status", "actor_version", "entity_version", "version",
                    })
                if observed_render_status:
                    authoritative_keys.update({
                        "render_status_observed", "render_ready", "render_failed",
                        "gpu_build_state", "mesh_count", "renderable_mesh_count",
                        "invalid_mesh_count", "engine_lifecycle_status",
                    })
                for key, value in observed_values.items():
                    if key in authoritative_keys and value not in (None, "", [], {}):
                        merged[key] = value
                        continue
                    if key not in merged or merged.get(key) in (None, "", [], {}):
                        merged[key] = value
            return merged

        entities: list[dict[str, Any]] = []
        seen_entity_ids: set[str] = set()
        seen_semantic_roles: set[str] = set()

        for actor_id, actor_row in sorted(actors.items()):
            if not isinstance(actor_row, Mapping):
                continue
            observed_row = observed.get(actor_id, {})
            merged = merge_engine_observation(actor_row, observed_row)
            asset_id = actor_asset_id(merged)
            actor_sync = actor_sync_status(merged, asset_id)
            bounds = bounds_from(merged)
            actor_source = str(merged.get("source") or "").strip()
            raw_bounds_source = str(merged.get("bounds_source") or "").strip()
            geometry_source = (
                "runtime_estimated_bounds"
                if raw_bounds_source == "estimated"
                or actor_source == "engine_import_runtime_estimated_bounds"
                else raw_bounds_source or "runtime_state"
            )
            explicit_entity_id = str(merged.get("entity_id") or "").strip()
            request_identity = stable_request_identity(merged)
            if explicit_entity_id:
                entity_id = explicit_entity_id
                entity_id_source = "runtime_explicit"
            elif request_identity:
                entity_id = stable_entity_id(active_plan_id, merged.get("batch_id"), request_identity)
                entity_id_source = "request_identity"
            else:
                entity_id = stable_entity_id(
                    active_plan_id,
                    merged.get("batch_id"),
                    asset_id,
                    merged.get("requested_name"),
                    actor_id,
                )
                entity_id_source = "native_fallback"
            current_entity_version, entity_version_source = entity_version(merged)
            entity = {
                "entity_id": entity_id,
                "entity_id_source": entity_id_source,
                "version": current_entity_version,
                "version_source": entity_version_source,
                "actor_id": str(actor_id),
                "name": str(merged.get("name") or actor_id),
                "display_name": str(merged.get("display_name") or merged.get("name") or actor_id),
                "native_name": str(merged.get("native_name") or merged.get("name") or actor_id),
                "requested_name": str(merged.get("requested_name") or ""),
                "aliases": list_field(merged, "aliases"),
                "asset_id": asset_id,
                "model_ref": actor_model_ref(merged, asset_id),
                "semantic_role": str(
                    merged.get("semantic_role")
                    or merged.get("role")
                    or merged.get("requested_name")
                    or merged.get("name")
                    or ""
                ),
                "entity_type": str(merged.get("entity_type") or "actor"),
                "transform": transform_from(merged),
                "bounds": bounds,
                "aabb": dict(bounds),
                "world_aabb": dict(bounds),
                "bounds_ready": bool(merged.get("bounds_ready")) if "bounds_ready" in merged else bool(bounds),
                "bounds_source": raw_bounds_source or "runtime_state",
                "render_status_observed": bool(merged.get("render_status_observed")),
                "render_ready": bool(merged.get("render_ready")),
                "render_failed": bool(merged.get("render_failed")),
                "gpu_build_state": str(merged.get("gpu_build_state") or ""),
                "mesh_count": int(merged.get("mesh_count") or 0),
                "renderable_mesh_count": int(merged.get("renderable_mesh_count") or 0),
                "invalid_mesh_count": int(merged.get("invalid_mesh_count") or 0),
                "size": vector3(merged.get("size")),
                "geometry_source": geometry_source,
                "grounding_status": actor_grounding_status(merged),
                "interaction_capability": actor_interaction_capability(merged),
                "gameplay_tags": actor_gameplay_tags(merged),
                "physics_profile": actor_physics_profile(merged),
                "audio_profile": mapping_field(merged, "audio_profile"),
                "lighting_profile": mapping_field(merged, "lighting_profile"),
                "script_bindings": actor_script_bindings(merged),
                "sync_status": actor_sync,
                "sync_lifecycle_status": sync_lifecycle_status(merged, actor_sync),
                "engine_write_verification_status": engine_write_verification_status(merged),
                "asset_transfer_status": asset_transfer_status(asset_id),
                "review_status": review_status_for(merged, str(merged.get("name") or actor_id)),
                "plan_id": str(merged.get("plan_id") or active_plan_id),
                "batch_id": str(merged.get("batch_id") or ""),
                "source_plan_id": str(merged.get("plan_id") or active_plan_id),
                "source_batch_id": str(merged.get("batch_id") or ""),
            }
            game_ready = entity_is_game_ready(entity)
            entity["readiness_missing_fields"] = readiness_missing_fields(entity)
            entity["materialization_status"] = (
                "engine_ready"
                if game_ready
                else "engine_ready_needs_review"
                if entity["engine_write_verification_status"] == "engine_verified"
                else "engine_loading"
                if entity["engine_write_verification_status"] == "engine_loading"
                else "planned"
                if entity["engine_write_verification_status"] == "planned"
                else "runtime_ready_pending_f5"
                if bool(entity["actor_id"]) and bool(entity["transform"]) and bool(entity["aabb"])
                else "runtime_only"
            )
            entity["game_ready"] = game_ready
            seen_entity_ids.add(entity["entity_id"])
            if entity["semantic_role"]:
                seen_semantic_roles.add(entity["semantic_role"])
            entities.append(entity)

        for current_batch_id in candidate_batch_ids:
            components = environment_components.get(current_batch_id, {})
            if not isinstance(components, Mapping):
                continue
            for component_id, component in sorted(components.items()):
                if not isinstance(component, Mapping):
                    continue
                component_actor_id = str(component.get("actor_id") or "").strip()
                merged_component = dict(component)
                runtime_actor = actors.get(component_actor_id, {})
                if isinstance(runtime_actor, Mapping):
                    merged_component = merge_engine_observation(
                        merged_component,
                        runtime_actor,
                    )
                merged_component = merge_engine_observation(
                    merged_component,
                    observed.get(component_actor_id, {}),
                )
                component = merged_component
                component_type = str(component.get("component_type") or "environment").strip() or "environment"
                component_type_key = component_type.lower()
                # Environment is the stable entity domain.  Terrain, skybox,
                # room shells, floors, and transitions remain queryable through
                # component_type instead of fragmenting the Game-ready schema.
                component_entity_type = "environment"
                component_asset_id = stable_environment_asset_id(component, component_type)
                component_semantic_role = str(component.get("semantic_role") or "").strip()
                if not component_semantic_role:
                    if component_type_key in {"room_box", "room_shell", "indoor_enclosure"}:
                        component_semantic_role = "indoor_enclosure"
                    elif component_type_key in {"room_floor", "walkable_floor"}:
                        component_semantic_role = "walkable_floor"
                    else:
                        component_semantic_role = str(component.get("name") or component_id or component_type)
                entity_id = str(component.get("entity_id") or "").strip() or stable_entity_id(
                    active_plan_id,
                    "environment",
                    component.get("component_id") or component_id,
                )
                if entity_id in seen_entity_ids:
                    continue
                bounds = bounds_from(component)
                component_actor_id = str(component.get("actor_id") or "").strip()
                component_sync = actor_sync_status(component, str(component.get("asset_id") or ""))
                current_entity_version, entity_version_source = entity_version(component)
                explicit_component_grounding = str(
                    component.get("grounding_status") or component.get("grounded_status") or ""
                ).strip()
                # Component semantics are authoritative for environment support.
                # A room shell can touch y=0 and still be an enclosure rather than
                # a floor-supported prop, so generic AABB grounding must not
                # overwrite these domain facts.
                if component_type_key in {
                    "room_floor",
                    "terrain",
                    "ground",
                    "walkable_floor",
                    "transition_zone",
                }:
                    component_grounding = "grounded"
                elif component_type_key in {"room_box", "room_shell", "indoor_enclosure"}:
                    component_grounding = "enclosure"
                elif component_type_key in {"sky", "skybox"}:
                    component_grounding = "not_applicable"
                elif explicit_component_grounding:
                    component_grounding = explicit_component_grounding
                elif component.get("requires_engine_write") is False:
                    component_grounding = "not_applicable"
                else:
                    component_grounding = "not_applicable"
                entity = {
                    "entity_id": entity_id,
                    "entity_id_source": (
                        "runtime_explicit"
                        if str(component.get("entity_id") or "").strip()
                        else "component_identity"
                    ),
                    "version": current_entity_version,
                    "version_source": entity_version_source,
                    "actor_id": component_actor_id,
                    "component_id": str(component.get("component_id") or component_id),
                    "name": str(component.get("name") or component_id),
                    "display_name": str(component.get("display_name") or component.get("name") or component_id),
                    "native_name": str(component.get("native_name") or component.get("name") or component_id),
                    "requested_name": str(component.get("requested_name") or ""),
                    "aliases": list_field(component, "aliases"),
                    "asset_id": component_asset_id,
                    "model_ref": str(component.get("model_ref") or component.get("handler") or component_type),
                    "semantic_role": component_semantic_role,
                    "entity_type": component_entity_type,
                    "component_type": component_type,
                    "environment_component_type": component_type,
                    "transform": transform_from(component),
                    "bounds": bounds,
                    "aabb": dict(bounds),
                    "world_aabb": dict(bounds),
                    "bounds_ready": bool(component.get("bounds_ready")) if "bounds_ready" in component else bool(bounds),
                    "bounds_source": str(component.get("bounds_source") or "runtime_state"),
                    "render_status_observed": bool(component.get("render_status_observed")),
                    "render_ready": bool(component.get("render_ready")),
                    "render_failed": bool(component.get("render_failed")),
                    "gpu_build_state": str(component.get("gpu_build_state") or ""),
                    "mesh_count": int(component.get("mesh_count") or 0),
                    "renderable_mesh_count": int(component.get("renderable_mesh_count") or 0),
                    "invalid_mesh_count": int(component.get("invalid_mesh_count") or 0),
                    "size": vector3(component.get("size")),
                    "grounding_status": component_grounding,
                    "interaction_capability": list_field(component, "interaction_capability"),
                    "gameplay_tags": list_field(component, "gameplay_tags"),
                    "physics_profile": mapping_field(component, "physics_profile"),
                    "audio_profile": mapping_field(component, "audio_profile"),
                    "lighting_profile": mapping_field(component, "lighting_profile"),
                    "environment_profile": environment_profile_from(component),
                    "script_bindings": list_field(component, "script_bindings"),
                    "sync_status": component_sync,
                    "sync_lifecycle_status": sync_lifecycle_status(component, component_sync),
                    "engine_write_verification_status": engine_write_verification_status(component),
                    "asset_transfer_status": asset_transfer_status(component_asset_id),
                    "review_status": review_status_for(component, str(component.get("name") or component_id)),
                    "plan_id": active_plan_id,
                    "batch_id": str(current_batch_id),
                    "source_plan_id": active_plan_id,
                    "source_batch_id": str(current_batch_id),
                }
                game_ready = entity_is_game_ready(entity)
                entity["readiness_missing_fields"] = readiness_missing_fields(entity)
                entity["materialization_status"] = (
                    "engine_ready"
                    if game_ready
                    else "engine_ready_needs_review"
                    if entity["engine_write_verification_status"] == "engine_verified"
                    else "engine_loading"
                    if entity["engine_write_verification_status"] == "engine_loading"
                    else "planned"
                    if entity["engine_write_verification_status"] == "planned"
                    else "runtime_ready_pending_f5"
                    if bool(entity["actor_id"]) and bool(entity["transform"]) and bool(entity["aabb"])
                    else "runtime_only"
                )
                entity["game_ready"] = game_ready
                seen_entity_ids.add(entity_id)
                if entity["semantic_role"]:
                    seen_semantic_roles.add(entity["semantic_role"])
                entities.append(entity)

        for name in list(classification.get("substrate_items") or []):
            text = str(name or "").strip()
            if not text:
                continue
            entity_id = stable_entity_id(active_plan_id, "substrate", text)
            if entity_id in seen_entity_ids or text in seen_semantic_roles:
                continue
            entities.append({
                "entity_id": entity_id,
                "entity_id_source": "substrate_identity",
                "version": scene_version,
                "version_source": "scene_version",
                "actor_id": "",
                "asset_id": "",
                "model_ref": "",
                "semantic_role": text,
                "entity_type": "substrate",
                "transform": {},
                "bounds": {},
                "aabb": {},
                "grounding_status": "not_applicable",
                "interaction_capability": [],
                "gameplay_tags": [],
                "physics_profile": {},
                "audio_profile": {},
                "lighting_profile": {},
                "script_bindings": [],
                "sync_status": "planned",
                "sync_lifecycle_status": "planned",
                "engine_write_verification_status": "planned",
                "materialization_status": "planned",
                "game_ready": False,
                "readiness_missing_fields": [
                    "actor_id", "asset_id", "model_ref", "transform", "world_aabb",
                    "engine_actual_aabb", "engine_ready",
                ],
                "asset_transfer_status": asset_transfer_status(""),
                "review_status": "pending_review",
                "plan_id": active_plan_id,
                "batch_id": active_batch_id,
                "source_plan_id": active_plan_id,
                "source_batch_id": active_batch_id,
            })
            seen_entity_ids.add(entity_id)

        entity_type_counts: dict[str, int] = {}
        grounding_status_counts: dict[str, int] = {}
        sync_status_counts: dict[str, int] = {}
        asset_transfer_status_counts: dict[str, int] = {}
        review_status_counts: dict[str, int] = {}
        geometry_source_counts: dict[str, int] = {}
        engine_write_verification_status_counts: dict[str, int] = {}
        materialization_status_counts: dict[str, int] = {}
        transform_available_count = 0
        aabb_available_count = 0
        actor_transform_available_count = 0
        actor_aabb_available_count = 0
        for entity in entities:
            add_count(entity_type_counts, str(entity.get("entity_type") or "unknown"))
            add_count(grounding_status_counts, str(entity.get("grounding_status") or "unknown"))
            add_count(sync_status_counts, str(entity.get("sync_status") or "unknown"))
            is_actor_entity = bool(entity.get("actor_id")) and not bool(entity.get("component_id"))
            has_transform = isinstance(entity.get("transform"), Mapping) and bool(entity.get("transform"))
            has_aabb = isinstance(entity.get("aabb"), Mapping) and bool(entity.get("aabb"))
            if has_transform:
                transform_available_count += 1
                if is_actor_entity:
                    actor_transform_available_count += 1
            if has_aabb:
                aabb_available_count += 1
                if is_actor_entity:
                    actor_aabb_available_count += 1
            transfer_status = entity.get("asset_transfer_status")
            if isinstance(transfer_status, Mapping):
                if not transfer_status.get("available"):
                    add_count(asset_transfer_status_counts, "unavailable")
                else:
                    add_count(
                        asset_transfer_status_counts,
                        str(transfer_status.get("transfer_status") or "available"),
                    )
            else:
                add_count(asset_transfer_status_counts, "unknown")
            add_count(review_status_counts, str(entity.get("review_status") or "unknown"))
            add_count(
                engine_write_verification_status_counts,
                str(entity.get("engine_write_verification_status") or "unknown"),
            )
            add_count(
                materialization_status_counts,
                str(entity.get("materialization_status") or "unknown"),
            )
            if is_actor_entity:
                add_count(geometry_source_counts, str(entity.get("geometry_source") or "unknown"))
        actor_count = sum(
            1
            for entity in entities
            if bool(entity.get("actor_id")) and not bool(entity.get("component_id"))
        )
        missing_transform_count = max(0, actor_count - actor_transform_available_count)
        missing_aabb_count = max(0, actor_count - actor_aabb_available_count)
        estimated_actor_bounds_count = int(geometry_source_counts.get("runtime_estimated_bounds") or 0)
        engine_write_pending_f5_count = int(engine_write_verification_status_counts.get("pending_f5") or 0)
        engine_write_verified_count = int(engine_write_verification_status_counts.get("engine_verified") or 0)
        game_ready_entity_count = sum(1 for entity in entities if bool(entity.get("game_ready")))
        readiness_missing_field_counts: dict[str, int] = {}
        for entity in entities:
            for field_name in list(entity.get("readiness_missing_fields") or []):
                add_count(readiness_missing_field_counts, str(field_name or "unknown"))
        planned_substrate_count = sum(
            1
            for entity in entities
            if str(entity.get("entity_type") or "") == "substrate"
            and str(entity.get("materialization_status") or "") == "planned"
        )
        failed_actor_requests = failed_actor_requests_for_plan()
        failed_actor_request_count = len(failed_actor_requests)
        failed_environment_requests = failed_environment_requests_for_plan()
        failed_environment_request_count = len(failed_environment_requests)
        if not actor_count and failed_actor_request_count:
            readiness_status = "failed_requests"
        elif not actor_count:
            readiness_status = "no_actors"
        elif missing_transform_count or missing_aabb_count:
            readiness_status = "partial"
        elif failed_actor_request_count:
            readiness_status = "partial"
        else:
            readiness_status = "ready"

        return {
            "available": bool(entities) or bool(failed_actor_requests) or bool(failed_environment_requests),
            "plan_id": active_plan_id,
            "scene_version": scene_version,
            "batch_id": active_batch_id,
            "entity_count": len(entities),
            "actor_count": actor_count,
            "environment_count": sum(
                1 for entity in entities if entity.get("entity_type") == "environment"
            ),
            "game_ready_entity_count": game_ready_entity_count,
            "needs_review_entity_count": max(0, len(entities) - game_ready_entity_count),
            "readiness_missing_field_counts": dict(sorted(readiness_missing_field_counts.items())),
            "planned_substrate_count": planned_substrate_count,
            "readiness_status": readiness_status,
            "transform_available_count": transform_available_count,
            "aabb_available_count": aabb_available_count,
            "actor_transform_available_count": actor_transform_available_count,
            "actor_aabb_available_count": actor_aabb_available_count,
            "missing_transform_count": missing_transform_count,
            "missing_aabb_count": missing_aabb_count,
            "entity_type_counts": dict(sorted(entity_type_counts.items())),
            "grounding_status_counts": dict(sorted(grounding_status_counts.items())),
            "sync_status_counts": dict(sorted(sync_status_counts.items())),
            "asset_transfer_status_counts": dict(sorted(asset_transfer_status_counts.items())),
            "review_status_counts": dict(sorted(review_status_counts.items())),
            "geometry_source_counts": dict(sorted(geometry_source_counts.items())),
            "estimated_actor_bounds_count": estimated_actor_bounds_count,
            "engine_write_verification_status_counts": dict(
                sorted(engine_write_verification_status_counts.items())
            ),
            "engine_write_pending_f5_count": engine_write_pending_f5_count,
            "engine_write_verified_count": engine_write_verified_count,
            "materialization_status_counts": dict(sorted(materialization_status_counts.items())),
            "failed_actor_request_count": failed_actor_request_count,
            "failed_actor_requests": failed_actor_requests[-10:],
            "failed_environment_request_count": failed_environment_request_count,
            "failed_environment_requests": failed_environment_requests[-10:],
            "entities": entities,
        }

    @staticmethod
    def _scene_world_snapshot_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        room_id: str,
        scene_entity_registry: Mapping[str, Any],
        operation_cursor: str,
        snapshot_authority: str = "local_runtime",
        scene_version_override: int | None = None,
    ) -> dict[str, Any]:
        entities = [
            dict(item)
            for item in list(scene_entity_registry.get("entities") or [])
            if isinstance(item, Mapping)
        ]
        environment_entities = [
            item
            for item in entities
            if str(item.get("entity_type") or "") in {"environment", "substrate"}
        ]
        actor_entities = [
            item for item in entities if str(item.get("entity_type") or "") not in {"environment", "substrate"}
        ]
        entity_count = len(entities)
        game_ready_count = int(scene_entity_registry.get("game_ready_entity_count") or 0)
        failed_count = int(scene_entity_registry.get("failed_actor_request_count") or 0) + int(
            scene_entity_registry.get("failed_environment_request_count") or 0
        )
        if entity_count > 0 and game_ready_count == entity_count and failed_count == 0:
            world_readiness = "game_ready"
        elif entity_count > 0:
            world_readiness = "needs_review"
        else:
            world_readiness = "blocked"
        plan = dict(dict(room.get("scene_plans") or {}).get(str(plan_id or "")) or {})
        scene_version = max(1, int(scene_version_override or plan.get("version") or 1))
        registry_plan_id = str(scene_entity_registry.get("plan_id") or "").strip()
        registry_scene_version = int(scene_entity_registry.get("scene_version") or 0)
        if registry_plan_id and registry_plan_id != str(plan_id or ""):
            raise ValueError("scene entity registry plan_id does not match snapshot plan")
        if registry_scene_version and registry_scene_version != scene_version:
            raise ValueError("scene entity registry version does not match snapshot version")
        snapshot = SceneWorldSnapshot(
            room_id=str(room_id or ""),
            plan_id=str(plan_id or ""),
            scene_version=scene_version,
            world_readiness=world_readiness,
            snapshot_authority=str(snapshot_authority or "local_runtime"),
            environment_entities=environment_entities,
            actor_entities=actor_entities,
            readiness_summary={
                "entity_count": entity_count,
                "game_ready_entity_count": game_ready_count,
                "needs_review_entity_count": max(0, entity_count - game_ready_count),
                "failed_request_count": failed_count,
                "missing_field_counts": dict(
                    scene_entity_registry.get("readiness_missing_field_counts") or {}
                ),
            },
            world_fingerprint=scene_world_fingerprint(
                entities,
                plan_id=str(plan_id or ""),
                scene_version=scene_version,
            ),
            operation_cursor=str(operation_cursor or ""),
        )
        result = snapshot.as_dict()
        SceneWorldSnapshotRecordValidator.validate(result)
        return result

    def get_scene_world_snapshot(
        self,
        *,
        room_id: str,
        plan_id: str = "",
        min_version: int | None = None,
    ) -> dict[str, Any]:
        """Return a side-effect-free world snapshot for downstream readers."""

        room_key = str(room_id)
        room = self.state.room(room_key)
        plans = dict(room.get("scene_plans") or {})
        peer_mirror_plan_id = str(room.get("peer_mirror_plan_id") or "").strip()
        peer_mirror_versions = dict(room.get("peer_mirror_scene_versions") or {})
        requested_plan_id = str(plan_id or "").strip()
        if requested_plan_id:
            target_plan_id = (
                requested_plan_id
                if requested_plan_id in plans or requested_plan_id == peer_mirror_plan_id
                else ""
            )
        else:
            target_plan_id = str(
                room.get("active_execution_plan_id")
                or room.get("latest_completed_plan_id")
                or peer_mirror_plan_id
                or ""
            ).strip()
        is_peer_mirror = bool(
            target_plan_id
            and target_plan_id == peer_mirror_plan_id
            and target_plan_id not in plans
        )
        if not target_plan_id or (target_plan_id not in plans and not is_peer_mirror):
            return {
                "handled": True,
                "action": "runtime.scene_world_snapshot.get",
                "recorded": False,
                "found": False,
                "plan_id": requested_plan_id,
                "scene_version": 0,
                "world_readiness": "blocked",
                "world_fingerprint": "",
                "snapshot": {},
                "operation_cursor": f"op:{len(self.operation_log.entries())}",
                "reason": "scene_plan_not_found",
            }

        plan = dict(plans.get(target_plan_id) or {})
        scene_version = max(
            1,
            int(peer_mirror_versions.get(target_plan_id) or 1)
            if is_peer_mirror
            else int(plan.get("version") or 1),
        )
        if min_version is not None and scene_version < max(0, int(min_version)):
            return {
                "handled": True,
                "action": "runtime.scene_world_snapshot.get",
                "recorded": False,
                "found": False,
                "plan_id": target_plan_id,
                "scene_version": scene_version,
                "world_readiness": "blocked",
                "world_fingerprint": "",
                "snapshot": {},
                "operation_cursor": f"op:{len(self.operation_log.entries())}",
                "reason": "minimum_scene_version_not_available",
            }

        persisted_report = {} if is_peer_mirror else self._latest_persisted_report_for_plan(
            room_key,
            target_plan_id,
            terminal_only=True,
        )
        persisted_snapshot = deepcopy(dict(persisted_report.get("scene_world_snapshot") or {}))
        snapshot_key = SceneWorldSnapshotRecordValidator.storage_key(target_plan_id, scene_version)
        frozen_snapshot = deepcopy(
            dict(dict(room.get("scene_world_snapshots") or {}).get(snapshot_key) or {})
        )
        if frozen_snapshot:
            try:
                SceneWorldSnapshotRecordValidator.validate(frozen_snapshot)
                if persisted_snapshot and (
                    SceneWorldSnapshotRecordValidator.immutable_payload(persisted_snapshot)
                    != SceneWorldSnapshotRecordValidator.immutable_payload(frozen_snapshot)
                ):
                    raise ValueError("persisted report snapshot differs from frozen snapshot")
            except ValueError as exc:
                return {
                    "handled": True,
                    "action": "runtime.scene_world_snapshot.get",
                    "recorded": False,
                    "found": False,
                    "plan_id": target_plan_id,
                    "scene_version": scene_version,
                    "world_readiness": "blocked",
                    "world_fingerprint": str(frozen_snapshot.get("world_fingerprint") or ""),
                    "snapshot": {},
                    "operation_cursor": str(frozen_snapshot.get("operation_cursor") or ""),
                    "snapshot_stability": "invalid",
                    "reason": "immutable_snapshot_integrity_failed",
                    "error_type": type(exc).__name__,
                }
            snapshot = constrain_scene_world_snapshot_readiness(
                frozen_snapshot,
                dict(persisted_report.get("scene_world_consistency_audit") or {}),
            )
            snapshot_stability = "immutable"
        elif (
            str(persisted_snapshot.get("plan_id") or "") == target_plan_id
            and int(persisted_snapshot.get("scene_version") or 0) == scene_version
        ):
            try:
                SceneWorldSnapshotRecordValidator.validate(persisted_snapshot)
            except ValueError:
                return {
                    "handled": True,
                    "action": "runtime.scene_world_snapshot.get",
                    "recorded": False,
                    "found": False,
                    "plan_id": target_plan_id,
                    "scene_version": scene_version,
                    "world_readiness": "blocked",
                    "world_fingerprint": str(persisted_snapshot.get("world_fingerprint") or ""),
                    "snapshot": {},
                    "operation_cursor": str(persisted_snapshot.get("operation_cursor") or ""),
                    "snapshot_stability": "legacy_report",
                    "reason": "legacy_snapshot_integrity_failed",
                }
            snapshot = constrain_scene_world_snapshot_readiness(
                persisted_snapshot,
                dict(persisted_report.get("scene_world_consistency_audit") or {}),
            )
            snapshot_stability = "legacy_report"
        else:
            registry = self._scene_entity_registry_for_plan(room, target_plan_id)
            snapshot = self._scene_world_snapshot_for_plan(
                room,
                target_plan_id,
                room_id=room_key,
                scene_entity_registry=registry,
                operation_cursor=f"op:{len(self.operation_log.entries())}",
                snapshot_authority="peer_mirror" if is_peer_mirror else "local_runtime",
                scene_version_override=scene_version,
            )
            engine_snapshot = latest_engine_snapshot(
                dict(room.get("engine_scene_snapshots") or {}),
                plan_id=target_plan_id,
                scene_version=scene_version,
            )
            consistency_audit = build_scene_world_consistency_audit(
                world_snapshot=snapshot,
                engine_snapshot=engine_snapshot,
            )
            snapshot = constrain_scene_world_snapshot_readiness(snapshot, consistency_audit)
            snapshot_stability = "peer_mirror" if is_peer_mirror else "provisional"

        result = {
            "handled": True,
            "action": "runtime.scene_world_snapshot.get",
            "recorded": False,
            "found": True,
            "plan_id": target_plan_id,
            "scene_version": int(snapshot.get("scene_version") or scene_version),
            "world_readiness": str(snapshot.get("world_readiness") or "blocked"),
            "snapshot_authority": str(snapshot.get("snapshot_authority") or "local_runtime"),
            "world_fingerprint": str(snapshot.get("world_fingerprint") or ""),
            "snapshot": snapshot,
            "operation_cursor": str(snapshot.get("operation_cursor") or ""),
            "snapshot_stability": snapshot_stability,
        }
        return result

    @staticmethod
    def _r3_multiplayer_evidence(
        room: Mapping[str, Any],
        plan_id: str,
        scene_entity_registry: Mapping[str, Any],
    ) -> dict[str, Any]:
        entities = [
            dict(item)
            for item in list(scene_entity_registry.get("entities") or [])
            if isinstance(item, Mapping)
        ]
        sync_events = [
            dict(item)
            for item in list(room.get("sync_events") or [])
            if isinstance(item, Mapping)
            and (not plan_id or str(item.get("plan_id") or "") in {"", plan_id})
        ]
        sync_state = dict(room.get("sync_state") or {})
        peer_events = dict(sync_state.get("peer_events") or {})
        expected_scene_version = max(0, int(scene_entity_registry.get("scene_version") or 0))
        expected_identity_fingerprint = AgentRuntime._scene_identity_fingerprint(
            entities,
            plan_id=plan_id,
            scene_version=expected_scene_version,
        )
        peer_mirror_plan_id = str(room.get("peer_mirror_plan_id") or "").strip()
        is_peer_mirror = peer_mirror_plan_id == str(plan_id or "")
        latest_peer_acks: dict[str, dict[str, Any]] = {}
        for item in sync_events:
            if str(item.get("event_type") or "") != "scene_snapshot_peer_ack":
                continue
            if str(item.get("plan_id") or "").strip() != str(plan_id or "").strip():
                continue
            peer_id = str(item.get("peer_id") or "").strip()
            if not peer_id:
                continue
            latest_peer_acks[peer_id] = item
        applicable = bool(latest_peer_acks or is_peer_mirror)
        actor_entities: dict[str, set[str]] = {}
        for row in [*entities, *sync_events]:
            actor_id = str(row.get("actor_id") or row.get("actor_guid") or "").strip()
            entity_id = str(row.get("entity_id") or "").strip()
            if actor_id and entity_id:
                actor_entities.setdefault(actor_id, set()).add(entity_id)
        identity_drift_count = sum(1 for values in actor_entities.values() if len(values) > 1)
        version_drift_count = sum(
            1
            for row in sync_events
            if str(row.get("status") or row.get("reason") or "").strip().lower()
            in {"identity_drift", "version_drift", "version_conflict"}
        )
        verified_sync_statuses = {
            "synced",
            "peer_confirmed",
            "host_peer_verified",
            "remote_host_ready",
        }
        verified_entity_count = sum(
            1
            for entity in entities
            if str(entity.get("sync_status") or "").strip().lower() in verified_sync_statuses
        )
        partial_entities = [
            entity
            for entity in entities
            if str(entity.get("sync_status") or "").strip().lower() not in verified_sync_statuses
        ]
        acknowledged_peer_count = len(latest_peer_acks)
        inactive_peer_statuses = {"closed", "disconnected", "left", "removed", "stopped"}
        known_peer_ids = {
            str(peer_id or "").strip()
            for peer_id, peer_event in peer_events.items()
            if str(peer_id or "").strip()
            and str(dict(peer_event or {}).get("status") or "").strip().lower()
            not in inactive_peer_statuses
        }
        known_peer_ids.update(latest_peer_acks)
        peer_count = len(known_peer_ids)
        unacknowledged_peer_count = max(0, peer_count - acknowledged_peer_count)
        ack_partial_count = 0
        ack_identity_drift_count = 0
        ack_version_drift_count = 0
        ack_missing_fields_explicit = True
        if latest_peer_acks:
            verified_by_peer: list[int] = []
            partial_by_peer: list[int] = []
            expected_entity_count = len(entities)
            for ack in latest_peer_acks.values():
                host_fingerprint = str(ack.get("host_identity_fingerprint") or "").strip()
                peer_fingerprint = str(ack.get("peer_identity_fingerprint") or "").strip()
                host_entity_count = max(0, int(ack.get("entity_count") or 0))
                applied_entity_count = max(0, int(ack.get("applied_entity_count") or 0))
                identity_drift = max(0, int(ack.get("identity_drift_count") or 0))
                version_drift = max(0, int(ack.get("version_drift_count") or 0))
                explicit_partial = max(0, int(ack.get("partial_entity_count") or 0))
                ack_scene_version = max(0, int(ack.get("scene_version") or 0))
                ack_status = str(ack.get("status") or "").strip().lower()
                if not host_fingerprint or not peer_fingerprint:
                    identity_drift += 1
                elif host_fingerprint != peer_fingerprint:
                    identity_drift += 1
                if host_fingerprint != expected_identity_fingerprint:
                    identity_drift += 1
                if host_entity_count != expected_entity_count:
                    identity_drift += 1
                if applied_entity_count > expected_entity_count:
                    identity_drift += 1
                if expected_scene_version <= 0 or ack_scene_version != expected_scene_version:
                    version_drift += 1
                peer_verified = min(expected_entity_count, applied_entity_count)
                if ack_status not in {"peer_confirmed", "host_peer_verified", "synced"}:
                    peer_verified = 0
                if identity_drift or version_drift:
                    peer_verified = 0
                peer_partial = max(
                    explicit_partial,
                    expected_entity_count - peer_verified,
                )
                verified_by_peer.append(peer_verified)
                partial_by_peer.append(peer_partial)
                ack_identity_drift_count += identity_drift
                ack_version_drift_count += version_drift
                ack_missing_fields_explicit = (
                    ack_missing_fields_explicit
                    and bool(ack.get("missing_fields_explicit"))
                )
            verified_entity_count = min(verified_by_peer) if verified_by_peer else 0
            ack_partial_count = max(partial_by_peer) if partial_by_peer else expected_entity_count
        partial_entity_count = (
            ack_partial_count if latest_peer_acks else len(partial_entities)
        )
        return {
            "applicable": applicable,
            "peer_count": peer_count,
            "acknowledged_peer_count": acknowledged_peer_count,
            "unacknowledged_peer_count": unacknowledged_peer_count,
            "comparison_mode": "peer_snapshot_ack" if latest_peer_acks else "peer_mirror" if is_peer_mirror else "none",
            "scene_version": expected_scene_version,
            "entity_count": len(entities),
            "verified_entity_count": verified_entity_count,
            "partial_entity_count": partial_entity_count,
            "identity_drift_count": identity_drift_count + ack_identity_drift_count,
            "version_drift_count": version_drift_count + ack_version_drift_count,
            "missing_fields_explicit": (
                ack_missing_fields_explicit
                if latest_peer_acks
                else all(
                    bool(list(entity.get("readiness_missing_fields") or []))
                    for entity in partial_entities
                )
            ),
        }

    @staticmethod
    def _scene_identity_fingerprint(
        entities: Iterable[Mapping[str, Any]],
        *,
        plan_id: str,
        scene_version: int,
    ) -> str:
        """Match LANChat's scene-id-v1 fingerprint against Runtime facts."""

        normalized_plan_id = str(plan_id or "").strip()
        normalized_scene_version = max(1, int(scene_version or 1))
        rows: list[dict[str, Any]] = []
        for entity in entities:
            actor_id = str(entity.get("actor_id") or "").strip()
            entity_id = str(entity.get("entity_id") or "").strip()
            if not actor_id or not entity_id:
                continue
            rows.append({
                "actor_guid": actor_id,
                "entity_id": entity_id,
                "asset_id": str(entity.get("asset_id") or "").strip(),
                "actor_version": max(
                    1,
                    int(entity.get("actor_version") or entity.get("version") or 1),
                ),
                "source_plan_id": normalized_plan_id,
                "source_scene_version": normalized_scene_version,
            })
        rows.sort(key=lambda row: (str(row["actor_guid"]), str(row["entity_id"])))
        serialized = json.dumps(
            rows,
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        hash_value = 0
        utf16 = serialized.encode("utf-16-le")
        for offset in range(0, len(utf16), 2):
            code_unit = utf16[offset] | (utf16[offset + 1] << 8)
            hash_value = ((hash_value << 5) - hash_value + code_unit) & 0xFFFFFFFF
        return f"scene-id-v1-{hash_value:x}-{len(utf16) // 2}"

    def evaluate_r3_readiness(
        self,
        *,
        room_id: str,
        plan_id: str = "",
        benchmark_profile: str = "",
        expected_entity_count: int = 0,
        profile: str = "full_r3",
        demo_requirements: Iterable[Mapping[str, Any]] = (),
        project_mode: str = "",
    ) -> dict[str, Any]:
        """Aggregate the R3 gate without mutating Runtime or querying providers."""

        room_key = str(room_id)
        requested_plan_id = str(plan_id or "").strip()
        room = self.state.rooms.get(room_key)
        if not isinstance(room, Mapping):
            report = evaluate_r3_gate(
                room_id=room_key,
                plan_id=requested_plan_id,
                scene_version=0,
                snapshot_result={"found": False, "plan_id": requested_plan_id},
                consistency_audit={},
                scene_entity_registry={},
                required_environment_components=[],
                batch_plans=[],
                tool_graphs=[],
                operation_entries=[],
                runtime_events=[],
                engine_write_summary={},
                multiplayer_evidence={},
                state_version=int(self.state.version),
                profile=profile,
                demo_requirements=list(demo_requirements or []),
                project_mode=project_mode,
            )
            return {
                "handled": True,
                "action": "runtime.r3_readiness.evaluate",
                "recorded": False,
                "found": False,
                "plan_id": requested_plan_id,
                "gate_report": report.as_dict(),
                "reason": "runtime_room_not_found",
            }

        snapshot_result = self.get_scene_world_snapshot(
            room_id=room_key,
            plan_id=requested_plan_id,
        )
        target_plan_id = str(snapshot_result.get("plan_id") or requested_plan_id or "").strip()
        scene_version = max(0, int(snapshot_result.get("scene_version") or 0))
        registry = (
            self._scene_entity_registry_for_plan(room, target_plan_id)
            if target_plan_id
            else {}
        )
        contract = self._scene_design_contract_summary_for_plan(room, target_plan_id)
        required_environment_components = list(
            contract.get("required_environment_components") or []
        )
        batches = [
            dict(item)
            for item in dict(room.get("batch_plans") or {}).values()
            if isinstance(item, Mapping)
            and str(item.get("plan_id") or "") == target_plan_id
        ]
        graphs = [
            dict(item)
            for item in dict(room.get("tool_graphs") or {}).values()
            if isinstance(item, Mapping)
            and str(item.get("plan_id") or "") == target_plan_id
        ]
        operation_entries = [
            entry.as_dict()
            for entry in self.operation_log.query(room_id=room_key, plan_id=target_plan_id)
        ]
        runtime_events = [
            dict(item)
            for item in list(room.get("runtime_events") or [])
            if isinstance(item, Mapping)
            and str(item.get("plan_id") or "") == target_plan_id
        ]
        snapshot = dict(snapshot_result.get("snapshot") or {})
        engine_snapshot = latest_engine_snapshot(
            dict(room.get("engine_scene_snapshots") or {}),
            plan_id=target_plan_id,
            scene_version=scene_version,
        )
        consistency_audit = build_scene_world_consistency_audit(
            world_snapshot=snapshot,
            engine_snapshot=engine_snapshot,
        )
        consistency_audit["engine_snapshot_available"] = bool(engine_snapshot)
        plan = dict(dict(room.get("scene_plans") or {}).get(target_plan_id) or {})
        plan_text = " ".join(
            str(plan.get(key) or "")
            for key in ("title", "design_brief", "scene_name")
        ).lower()
        resolved_benchmark = str(benchmark_profile or "").strip().lower()
        if not resolved_benchmark:
            resolved_benchmark = (
                "bedroom_14"
                if "bedroom" in plan_text or "\u5367\u5ba4" in plan_text
                else "generic"
            )
        resolved_expected_count = max(0, int(expected_entity_count or 0))
        if resolved_expected_count <= 0 and resolved_benchmark == "bedroom_14":
            resolved_expected_count = 14
        elif resolved_expected_count <= 0:
            resolved_expected_count = int(registry.get("entity_count") or 0)
        timestamps = [
            float(item.get("timestamp") or 0.0)
            for item in [*operation_entries, *runtime_events]
            if isinstance(item, Mapping)
        ]
        report = evaluate_r3_gate(
            room_id=room_key,
            plan_id=target_plan_id,
            scene_version=scene_version,
            snapshot_result=snapshot_result,
            consistency_audit=consistency_audit,
            scene_entity_registry=registry,
            required_environment_components=required_environment_components,
            batch_plans=batches,
            tool_graphs=graphs,
            operation_entries=operation_entries,
            runtime_events=runtime_events,
            engine_write_summary=self._engine_write_boundary_summary_for_plan(
                room,
                target_plan_id,
            ),
            multiplayer_evidence=self._r3_multiplayer_evidence(
                room,
                target_plan_id,
                registry,
            ),
            state_version=int(self.state.version),
            benchmark_profile=resolved_benchmark,
            expected_entity_count=resolved_expected_count,
            evaluated_at=max(timestamps, default=0.0),
            profile=profile,
            demo_requirements=list(demo_requirements or []),
            project_mode=project_mode,
        )

    @staticmethod
    def _ready_image_resource_count(resources: Mapping[str, Any]) -> int:
        return sum(
            1
            for resource in dict(resources or {}).values()
            if isinstance(resource, Mapping)
            and str(resource.get("status") or "").strip().lower() == "ready"
            and str(resource.get("mode") or "").strip().lower()
            not in {"mock", "mock_reference", "fixture"}
            and bool(str(resource.get("image_url") or resource.get("local_path") or "").strip())
            and str(resource.get("resource_ref") or "").strip()
            and str(resource.get("content_hash") or "").startswith("sha256:")
            and str(resource.get("prompt_hash") or "").startswith("sha256:")
        )
        return {
            "handled": True,
            "action": "runtime.r3_readiness.evaluate",
            "recorded": False,
            "found": bool(snapshot_result.get("found")),
            "plan_id": target_plan_id,
            "scene_version": scene_version,
            "profile": str(profile or "full_r3"),
            "gate_report": report.as_dict(),
        }

    def audit_scene_world_consistency(
        self,
        *,
        room_id: str,
        plan_id: str = "",
    ) -> dict[str, Any]:
        """Compare Runtime world identity with the latest read-only Engine snapshot."""

        room_key = str(room_id)
        world_result = self.get_scene_world_snapshot(
            room_id=room_key,
            plan_id=str(plan_id or "").strip(),
        )
        target_plan_id = str(world_result.get("plan_id") or plan_id or "").strip()
        if not bool(world_result.get("found")):
            return {
                "handled": True,
                "action": "runtime.scene_world_consistency.audit",
                "recorded": False,
                "found": False,
                "plan_id": target_plan_id,
                "audit": {
                    "status": "blocked",
                    "plan_id": target_plan_id,
                    "issue_count": 0,
                    "reason": str(world_result.get("reason") or "scene_world_snapshot_unavailable"),
                },
            }

        room = self.state.room(room_key)
        engine_snapshot = latest_engine_snapshot(
            dict(room.get("engine_scene_snapshots") or {}),
            plan_id=target_plan_id,
            scene_version=int(world_result.get("scene_version") or 0),
        )
        audit = build_scene_world_consistency_audit(
            world_snapshot=dict(world_result.get("snapshot") or {}),
            engine_snapshot=engine_snapshot,
        )
        if not engine_snapshot:
            audit["reason"] = "engine_scene_snapshot_unavailable"
        self.operation_log.append(
            "runtime_scene_world_consistency_audited",
            room_id=room_key,
            plan_id=target_plan_id,
            payload={
                "status": str(audit.get("status") or "blocked"),
                "scene_version": int(audit.get("scene_version") or 0),
                "expected_entity_count": int(audit.get("expected_entity_count") or 0),
                "materialized_entity_count": int(audit.get("materialized_entity_count") or 0),
                "non_materialized_entity_count": int(
                    audit.get("non_materialized_entity_count") or 0
                ),
                "engine_actor_count": int(audit.get("engine_actor_count") or 0),
                "matched_entity_count": int(audit.get("matched_entity_count") or 0),
                "issue_count": int(audit.get("issue_count") or 0),
            },
        )
        return {
            "handled": True,
            "action": "runtime.scene_world_consistency.audit",
            "recorded": False,
            "found": True,
            "plan_id": target_plan_id,
            "scene_version": int(audit.get("scene_version") or 0),
            "snapshot_stability": str(world_result.get("snapshot_stability") or "provisional"),
            "audit": audit,
        }

    @staticmethod
    def _sync_readiness_summary(
        *,
        scene_entity_registry: Mapping[str, Any],
        sync_summary: Mapping[str, Any],
        asset_transfer_summary: Mapping[str, Any],
    ) -> dict[str, Any]:
        entities = [
            dict(entity)
            for entity in (scene_entity_registry.get("entities") or [])
            if isinstance(entity, Mapping)
        ]
        actor_entities = [
            entity
            for entity in entities
            if str(entity.get("entity_type") or "") == "actor"
        ]
        environment_entities = [
            entity
            for entity in entities
            if str(entity.get("entity_type") or "") not in {"actor", "substrate"}
        ]
        actor_count = len(actor_entities)
        actor_ready_for_sync_count = 0
        runtime_state_actor_count = 0
        missing_actor_identity_count = 0
        missing_actor_geometry_count = 0
        runtime_ready_statuses = {
            "runtime_state",
            "planned",
            "ready",
            "active",
            "created",
            "engine_created",
            "imported",
            "engine_imported",
            "runtime_imported",
            "synced",
            "synchronized",
        }
        for entity in actor_entities:
            if str(entity.get("sync_status") or "").strip().lower() in runtime_ready_statuses:
                runtime_state_actor_count += 1
            has_identity = bool(str(entity.get("actor_id") or "").strip())
            has_transform = bool(entity.get("transform"))
            has_bounds = bool(entity.get("aabb") or entity.get("bounds"))
            if not has_identity:
                missing_actor_identity_count += 1
            if not has_transform or not has_bounds:
                missing_actor_geometry_count += 1
            if has_identity and has_transform and has_bounds:
                actor_ready_for_sync_count += 1
        environment_count = len(environment_entities)
        environment_ready_for_sync_count = 0
        runtime_state_environment_count = 0
        missing_environment_identity_count = 0
        missing_environment_geometry_count = 0
        for entity in environment_entities:
            if str(entity.get("sync_status") or "").strip().lower() in runtime_ready_statuses:
                runtime_state_environment_count += 1
            has_identity = bool(
                str(
                    entity.get("actor_id")
                    or entity.get("component_id")
                    or entity.get("asset_id")
                    or ""
                ).strip()
            )
            has_transform = bool(entity.get("transform"))
            has_bounds = bool(entity.get("aabb") or entity.get("bounds"))
            if not has_identity:
                missing_environment_identity_count += 1
            if not has_transform or not has_bounds:
                missing_environment_geometry_count += 1
            if has_identity and has_transform and has_bounds:
                environment_ready_for_sync_count += 1
        real_sync_event_count = int(sync_summary.get("event_count") or 0)
        real_actor_sync_event_count = int(sync_summary.get("actor_event_count") or 0)
        asset_count = int(asset_transfer_summary.get("asset_count") or 0)
        asset_ready_count = int(asset_transfer_summary.get("ready_count") or 0)
        asset_completed_count = int(asset_transfer_summary.get("completed_count") or 0)
        asset_failed_count = int(asset_transfer_summary.get("failed_count") or 0)
        asset_transferring_count = int(asset_transfer_summary.get("transferring_count") or 0)
        asset_overall_progress = int(asset_transfer_summary.get("overall_progress") or 0)
        status = "no_actors"
        if actor_count:
            if real_sync_event_count > 0:
                status = "sync_events_recorded"
            elif actor_ready_for_sync_count == actor_count:
                status = "runtime_state_ready_pending_f5"
            else:
                status = "incomplete_runtime_actor_state"
        return {
            "status": status,
            "actor_count": actor_count,
            "actor_ready_for_sync_count": actor_ready_for_sync_count,
            "runtime_state_actor_count": runtime_state_actor_count,
            "missing_actor_identity_count": missing_actor_identity_count,
            "missing_actor_geometry_count": missing_actor_geometry_count,
            "environment_count": environment_count,
            "environment_ready_for_sync_count": environment_ready_for_sync_count,
            "runtime_state_environment_count": runtime_state_environment_count,
            "missing_environment_identity_count": missing_environment_identity_count,
            "missing_environment_geometry_count": missing_environment_geometry_count,
            "real_sync_event_count": real_sync_event_count,
            "real_actor_sync_event_count": real_actor_sync_event_count,
            "real_sync_verified": real_sync_event_count > 0,
            "native_sync_verification": "pending_f5",
            "asset_count": asset_count,
            "asset_ready_count": asset_ready_count,
            "asset_completed_count": asset_completed_count,
            "asset_failed_count": asset_failed_count,
            "asset_transferring_count": asset_transferring_count,
            "asset_overall_progress": max(0, min(100, asset_overall_progress)),
            "asset_transfer_native_verification": "pending_f5",
            "asset_transfer_status_counts": dict(
                asset_transfer_summary.get("status_counts")
                or scene_entity_registry.get("asset_transfer_status_counts")
                or {}
            ),
        }

    @staticmethod
    def _runtime_scene_flow_summary(
        *,
        plan_summary: Mapping[str, Any],
        classification_summary: Mapping[str, Any],
        environment_component_summary: Mapping[str, Any],
        resource_summary: Mapping[str, Any],
        import_summary: Mapping[str, Any],
        review_summary: Mapping[str, Any],
        scene_entity_registry: Mapping[str, Any],
        operation_replay_summary: Mapping[str, Any],
        report_generated: bool = False,
    ) -> dict[str, Any]:
        """Compact F5-facing replay of plan -> terrain -> asset -> actor -> review -> report."""

        concrete_items = list(plan_summary.get("concrete_object_items") or [])
        model_items = list(classification_summary.get("model_items") or [])
        substrate_items = list(classification_summary.get("substrate_items") or [])
        environment_type_counts = dict(environment_component_summary.get("type_counts") or {})
        resource_by_phase = dict(resource_summary.get("by_phase") or {})
        image_phase = dict(resource_by_phase.get("image") or {})
        model_phase = dict(resource_by_phase.get("model") or {})
        entity_type_counts = dict(scene_entity_registry.get("entity_type_counts") or {})
        actor_readiness_status = str(scene_entity_registry.get("readiness_status") or "").strip()
        actor_missing_transform_count = int(scene_entity_registry.get("missing_transform_count") or 0)
        actor_missing_aabb_count = int(scene_entity_registry.get("missing_aabb_count") or 0)
        failed_actor_request_count = int(scene_entity_registry.get("failed_actor_request_count") or 0)
        failed_environment_request_count = int(
            scene_entity_registry.get("failed_environment_request_count") or 0
        )
        imported_count = int(import_summary.get("imported_count") or 0)
        actor_step_status = "missing"
        if imported_count > 0:
            actor_step_status = (
                "ok"
                if actor_readiness_status in {"", "ready"} and failed_actor_request_count <= 0
                else "partial"
            )
        elif failed_actor_request_count > 0:
            actor_step_status = "failed"
        flow_steps = [
            {
                "step": "plan",
                "status": "ok" if concrete_items or model_items else "missing",
                "item_count": len(concrete_items or model_items),
            },
            {
                "step": "terrain",
                "status": "ok" if environment_type_counts else "missing",
                "substrate_count": len(substrate_items),
                "component_type_counts": dict(sorted(environment_type_counts.items())),
            },
            {
                "step": "asset",
                "status": "ok"
                if int(image_phase.get("failed_count") or 0) == 0
                and int(model_phase.get("failed_count") or 0) == 0
                and int(model_phase.get("requested_count") or 0) > 0
                else "missing",
                "image_requested_count": int(image_phase.get("requested_count") or 0),
                "model_requested_count": int(model_phase.get("requested_count") or 0),
            },
            {
                "step": "actor",
                "status": actor_step_status,
                "readiness_status": actor_readiness_status,
                "actor_count": int(scene_entity_registry.get("actor_count") or entity_type_counts.get("actor") or 0),
                "imported_count": imported_count,
                "failed_request_count": failed_actor_request_count,
                "missing_transform_count": actor_missing_transform_count,
                "missing_aabb_count": actor_missing_aabb_count,
            },
            {
                "step": "review",
                "status": "ok" if int(review_summary.get("review_count") or 0) > 0 else "missing",
                "review_count": int(review_summary.get("review_count") or 0),
                "issue_count": int(review_summary.get("issue_count") or 0),
            },
            {
                "step": "report",
                "status": "ok" if report_generated else "pending",
                "operation_entry_count": int(operation_replay_summary.get("entry_count") or 0),
            },
        ]
        return {
            "status": "ok" if all(step["status"] in {"ok", "pending"} for step in flow_steps) else "incomplete",
            "actor_readiness_status": actor_readiness_status,
            "actor_missing_transform_count": actor_missing_transform_count,
            "actor_missing_aabb_count": actor_missing_aabb_count,
            "failed_actor_request_count": failed_actor_request_count,
            "failed_environment_request_count": failed_environment_request_count,
            "steps": flow_steps,
            "model_items": model_items,
            "substrate_items": substrate_items,
            "entity_type_counts": dict(sorted(entity_type_counts.items())),
        }

    def _operation_replay_summary_via_tool_graph(
        self,
        *,
        room_id: str,
        plan_id: str = "",
        batch_id: str = "",
    ) -> dict[str, Any]:
        room = str(room_id or "default")
        safe_plan_id = str(plan_id or "").strip()
        safe_batch_id = str(batch_id or "").strip()
        summary_key = f"{safe_plan_id or 'room'}:{safe_batch_id or 'all'}:operation_replay_summary"
        graph = ToolCallGraph(
            graph_id=_id("graph-report-operation-replay"),
            plan_id=safe_plan_id or "room-report",
            batch_id=safe_batch_id,
        )
        graph.add(
            ToolCall(
                tool_call_id=_id("tool-report-operation-replay"),
                tool_name="runtime.report.operation_replay_summary",
                args={
                    "room_id": room,
                    "plan_id": safe_plan_id,
                    "batch_id": safe_batch_id,
                    "summary_key": summary_key,
                },
                risk_level=RiskLevel.LOW,
                requires_write=True,
                confirmed=True,
            )
        )
        executor = ToolCallGraphExecutor(
            registry=self.registry,
            guard=self.guard,
            state=self.state,
            operation_log=self.operation_log,
        )
        executor.execute(graph, room_id=room)
        summary_call = next(iter(graph.nodes.values()))
        fact = dict(
            dict(self.state.room(room).get("custom_report_facts") or {}).get(summary_key) or {}
        )
        summary = fact.get("operation_replay_summary")
        if (
            graph.status == "completed"
            and summary_call.status == ToolCallStatus.SUCCEEDED
            and isinstance(summary, Mapping)
        ):
            self.operation_log.append(
                "runtime_report_operation_replay_summary_recorded",
                room_id=room,
                plan_id=safe_plan_id,
                batch_id=safe_batch_id,
                payload=self._operation_replay_snapshot_summary_payload(summary),
            )
            return dict(summary)
        reason = summary_call.error or graph.status or "unknown"
        self.operation_log.append(
            "runtime_report_operation_replay_summary_failed",
            room_id=room,
            plan_id=safe_plan_id,
            batch_id=safe_batch_id,
            payload=self._snapshot_failure_audit_payload(
                summary_type="runtime_report_operation_replay_summary",
                reason=reason,
            ),
        )
        raise RuntimeError(f"failed to record operation replay summary: {reason}")

