    def operation_replay(
        self,
        *,
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        tool_call_id: str = "",
        event: str = "",
        limit: int | None = None,
    ) -> dict[str, Any]:
        """Export a filtered OperationLog replay slice for audit and diagnosis."""

        self.operation_log.append(
            "runtime_operation_replay_requested",
            room_id=str(room_id or ""),
            plan_id=str(plan_id or ""),
            batch_id=str(batch_id or ""),
            tool_call_id=str(tool_call_id or ""),
            payload={
                "event": str(event or ""),
                "limit": limit,
            },
        )
        replay = self._operation_replay_snapshot_via_tool_graph(
            room_id=room_id,
            plan_id=plan_id,
            batch_id=batch_id,
            tool_call_id=tool_call_id,
            event=event,
            limit=limit,
        )
        self.operation_log.append(
            "runtime_operation_replay_queried",
            room_id=str(room_id or ""),
            plan_id=str(plan_id or ""),
            batch_id=str(batch_id or ""),
            tool_call_id=str(tool_call_id or ""),
            payload=self._operation_replay_snapshot_audit_payload(replay),
        )
        return replay

    def _compose_operation_replay(
        self,
        *,
        room_id: str = "",
        plan_id: str = "",
        batch_id: str = "",
        tool_call_id: str = "",
        event: str = "",
        limit: int | None = None,
    ) -> dict[str, Any]:
        raw_entries = self._operation_log_entries_for_runtime_scope(
            room_id=str(room_id or ""),
            plan_id=str(plan_id or ""),
            batch_id=str(batch_id or ""),
            tool_call_id=str(tool_call_id or ""),
            event=str(event or ""),
            limit=limit,
        )
        replay = self._operation_log_snapshot_from_entries(
            raw_entries,
            room_id=str(room_id or ""),
            plan_id=str(plan_id or ""),
            batch_id=str(batch_id or ""),
            event=str(event or ""),
            limit=limit,
        )
        replay["vlm_checkpoint_summary"] = self._vlm_checkpoint_replay_summary(raw_entries)
        replay["review_advisory_summary"] = self._review_advisory_replay_summary(replay.get("entries", []))
        replay["final_adjustment_confirmation_replay_summary"] = (
            self._final_adjustment_confirmation_replay_summary(replay.get("entries", []))
        )
        replay["environment_component_summary"] = self._environment_component_replay_summary(replay.get("entries", []))
        replay["layout_adjustment_summary"] = self._layout_adjustment_replay_summary(replay.get("entries", []))
        replay["engine_write_summary"] = self._engine_write_replay_summary(raw_entries)
        log_sync_summary = self._sync_replay_summary(replay.get("entries", []))
        state_sync_entries = self._state_sync_replay_entries(
            room_id=str(room_id or ""),
            plan_id=str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        if state_sync_entries:
            replay["sync_summary"] = self._merge_sync_replay_summaries(
                log_sync_summary,
                self._sync_replay_summary(state_sync_entries),
            )
        else:
            replay["sync_summary"] = log_sync_summary
        replay_entries_with_state = list(replay.get("entries", []) or []) + state_sync_entries
        replay["asset_transfer_replay_summary"] = self._asset_transfer_replay_summary(replay_entries_with_state)
        replay["peer_sync_replay_summary"] = self._peer_sync_replay_summary(replay_entries_with_state)
        replay["message_delivery_summary"] = self._message_delivery_replay_summary(replay.get("entries", []))
        replay["planning_context_summary"] = self._planning_context_replay_summary(replay.get("entries", []))
        replay["runtime_command_summary"] = self._runtime_command_replay_summary(replay.get("entries", []))
        replay["batch_execution_summary"] = self._batch_execution_replay_summary(replay.get("entries", []))
        replay["batch_resource_lifecycle_summary"] = self._batch_resource_lifecycle_replay_summary(raw_entries)
        room_state = self.state.snapshot(str(room_id or ""))["room"] if str(room_id or "").strip() else {}
        replay["resource_summary"] = self._resource_summary_for_plan(
            room_state,
            str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        replay["asset_transfer_summary"] = self._asset_transfer_summary_for_plan(
            room_state,
            str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        replay["batch_resource_flow_summary"] = self._batch_resource_flow_summary_for_plan(
            room_state,
            str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        replay_import_summary = self._import_summary_for_plan(
            room_state,
            str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        replay["import_summary"] = replay_import_summary
        replay["engine_write_boundary_summary"] = self._engine_write_boundary_summary_for_plan(
            room_state,
            str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        replay["tool_queue_health_summary"] = self._tool_queue_health_summary_for_plan(
            room_state,
            str(plan_id or ""),
            batch_id=str(batch_id or ""),
        )
        replay["worker_drain_replay_summary"] = self._worker_drain_replay_summary(replay.get("entries", []))
        replay["report_health_summary"] = self._report_health_summary(
            batch_resource_flow_summary=dict(replay.get("batch_resource_flow_summary") or {}),
            import_summary=replay_import_summary,
            sync_health_digest=self._sync_health_digest_for_report(
                sync_summary=dict(replay.get("sync_summary") or {}),
                asset_transfer_summary=dict(replay.get("asset_transfer_summary") or {}),
                sync_replay_summary=dict(replay.get("sync_summary") or {}),
                message_delivery_summary=dict(replay.get("message_delivery_summary") or {}),
            ),
            resource_summary=dict(replay.get("resource_summary") or {}),
            environment_component_summary=self._environment_component_summary_for_plan(
                room_state,
                str(plan_id or ""),
                batch_id=str(batch_id or ""),
            ),
            engine_write_summary=dict(replay.get("engine_write_summary") or {}),
            scene_entity_registry=self._scene_entity_registry_for_plan(
                room_state,
                str(plan_id or ""),
                batch_id=str(batch_id or ""),
            ),
            worker_drain_replay_summary=dict(replay.get("worker_drain_replay_summary") or {}),
            tool_queue_health_summary=dict(replay.get("tool_queue_health_summary") or {}),
        )
        replay["tool_execution_summary"] = self._tool_execution_replay_summary(replay.get("entries", []))
        replay["tool_graph_queue_summary"] = self._tool_graph_queue_replay_summary(replay.get("entries", []))
        replay["resource_readiness_replay_summary"] = self._resource_readiness_replay_summary(raw_entries)
        replay["state_patch_summary"] = self._state_patch_replay_summary(raw_entries)
        replay["intervention_batch_replay_summary"] = self._intervention_batch_replay_summary(raw_entries)
        replay["scene_plan_lifecycle_summary"] = self._scene_plan_lifecycle_replay_summary(raw_entries)
        replay["runtime_event_replay_summary"] = self._runtime_event_replay_summary(raw_entries)
        replay["runtime_guard_replay_summary"] = self._runtime_guard_replay_summary(raw_entries)
        replay["runtime_fact_injection_replay_summary"] = self._runtime_fact_injection_replay_summary(raw_entries)
        replay["gm_summary_replay_summary"] = self._gm_summary_replay_summary(raw_entries)
        replay["geometry_fact_replay_summary"] = self._geometry_fact_replay_summary(raw_entries)
        replay["tool_failure_strategy_summary"] = self._tool_failure_strategy_replay_summary(raw_entries)
        return replay

    @staticmethod
    def _geometry_fact_replay_summary(entries: Any) -> dict[str, Any]:
        default = {
            "patch_event_count": 0,
            "fact_count": 0,
            "aabb_actor_count": 0,
            "aabb_skipped_count": 0,
            "overlap_issue_count": 0,
            "status_counts": {},
            "fact_type_counts": {},
            "latest_geometry_event": {},
        }
        if not isinstance(entries, list):
            return default
        patch_event_count = 0
        fact_count = 0
        aabb_actor_count = 0
        aabb_skipped_count = 0
        overlap_issue_count = 0
        status_counts: dict[str, int] = {}
        fact_type_counts: dict[str, int] = {}
        latest_geometry_event: dict[str, Any] = {}
        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                batch_id = str(entry.batch_id or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                batch_id = str(entry.get("batch_id") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            else:
                continue
            if event not in {"runtime_state_patch_applied", "runtime_state_patch_conflict"}:
                continue
            summary = payload.get("geometry_fact_patch_summary")
            if not isinstance(summary, Mapping):
                continue
            patch_event_count += 1
            fact_count += int(summary.get("fact_count") or 0)
            aabb_from_summary = int(summary.get("aabb_actor_count") or 0)
            if not aabb_from_summary:
                latest_fact = summary.get("latest_fact") if isinstance(summary.get("latest_fact"), Mapping) else {}
                if str(latest_fact.get("fact_type") or "") == "runtime_geometry_ground_snap":
                    aabb_from_summary = int(latest_fact.get("actor_count") or 0)
            aabb_actor_count += aabb_from_summary
            aabb_skipped_count += int(summary.get("aabb_skipped_count") or 0)
            overlap_issue_count += int(summary.get("overlap_issue_count") or 0)
            for status, count in dict(summary.get("status_counts") or {}).items():
                status_key = str(status or "unknown").strip() or "unknown"
                status_counts[status_key] = status_counts.get(status_key, 0) + int(count or 0)
            for fact_type, count in dict(summary.get("fact_type_counts") or {}).items():
                fact_type_key = str(fact_type or "geometry_fact").strip() or "geometry_fact"
                fact_type_counts[fact_type_key] = fact_type_counts.get(fact_type_key, 0) + int(count or 0)
            latest_fact = summary.get("latest_fact") if isinstance(summary.get("latest_fact"), Mapping) else {}
            latest_geometry_event = {
                "event": event,
                "batch_id": batch_id,
                "fact_type": AgentRuntime._safe_report_text(latest_fact.get("fact_type"))[:120],
                "status": AgentRuntime._safe_report_text(latest_fact.get("status"))[:120],
                "actor_count": int(latest_fact.get("actor_count") or 0),
                "issue_count": int(latest_fact.get("issue_count") or 0),
                "skipped_count": int(latest_fact.get("skipped_count") or 0),
            }
        return {
            **default,
            "patch_event_count": patch_event_count,
            "fact_count": fact_count,
            "aabb_actor_count": aabb_actor_count,
            "aabb_skipped_count": aabb_skipped_count,
            "overlap_issue_count": overlap_issue_count,
            "status_counts": dict(sorted(status_counts.items())),
            "fact_type_counts": dict(sorted(fact_type_counts.items())),
            "latest_geometry_event": latest_geometry_event,
        }

    @staticmethod
    def _tool_failure_strategy_replay_summary(entries: Any) -> dict[str, Any]:
        default = {
            "retry_scheduled_count": 0,
            "dependency_skipped_count": 0,
            "abandoned_late_result_count": 0,
            "handler_failed_count": 0,
            "invalid_result_count": 0,
            "runtime_facts_missing_count": 0,
            "runtime_facts_rejected_count": 0,
            "invalid_state_patch_count": 0,
            "state_patch_conflict_count": 0,
            "stopped_by_runtime_command_count": 0,
            "strategy_counts": {},
            "latest_strategy_event": {},
        }
        if not isinstance(entries, list):
            return default
        event_to_strategy = {
            "tool_call_retry_scheduled": "retry_scheduled",
            "tool_call_skipped": "dependency_skipped",
            "tool_call_abandoned_late_result": "abandoned_late_result",
            "tool_call_handler_failed": "handler_failed",
            "tool_call_invalid_result": "invalid_result",
            "tool_call_runtime_facts_missing": "runtime_facts_missing",
            "tool_call_runtime_facts_rejected": "runtime_facts_rejected",
            "tool_call_invalid_state_patch": "invalid_state_patch",
            "runtime_state_patch_conflict": "state_patch_conflict",
            "tool_graph_stopped_by_runtime_command": "stopped_by_runtime_command",
        }
        strategy_counts: dict[str, int] = {}
        latest_strategy_event: dict[str, Any] = {}
        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                batch_id = str(entry.batch_id or "")
                message = str(entry.message or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                batch_id = str(entry.get("batch_id") or "")
                message = str(entry.get("message") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            else:
                continue
            strategy = event_to_strategy.get(event)
            if not strategy:
                continue
            strategy_counts[strategy] = strategy_counts.get(strategy, 0) + 1
            latest_strategy_event = {
                "event": event,
                "strategy": strategy,
                "batch_id": batch_id,
                "error_code": AgentRuntime._safe_report_text(payload.get("error_code"))[:80],
                "status": AgentRuntime._safe_report_text(payload.get("status"))[:80],
                "message": AgentRuntime._safe_report_text(message)[:160],
            }
        return {
            **default,
            "retry_scheduled_count": strategy_counts.get("retry_scheduled", 0),
            "dependency_skipped_count": strategy_counts.get("dependency_skipped", 0),
            "abandoned_late_result_count": strategy_counts.get("abandoned_late_result", 0),
            "handler_failed_count": strategy_counts.get("handler_failed", 0),
            "invalid_result_count": strategy_counts.get("invalid_result", 0),
            "runtime_facts_missing_count": strategy_counts.get("runtime_facts_missing", 0),
            "runtime_facts_rejected_count": strategy_counts.get("runtime_facts_rejected", 0),
            "invalid_state_patch_count": strategy_counts.get("invalid_state_patch", 0),
            "state_patch_conflict_count": strategy_counts.get("state_patch_conflict", 0),
            "stopped_by_runtime_command_count": strategy_counts.get("stopped_by_runtime_command", 0),
            "strategy_counts": dict(sorted(strategy_counts.items())),
            "latest_strategy_event": latest_strategy_event,
        }

    @staticmethod
    def _tool_execution_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "started_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "blocked_count": 0,
                "retry_scheduled_count": 0,
                "skipped_count": 0,
                "tool_event_counts": {},
                "latest_tool_event": {},
            }
        tool_event_counts: dict[str, int] = {}
        latest_tool_event: dict[str, Any] = {}
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if not (
                event.startswith("tool_call_")
                or event in {"tool_graph_completed", "tool_graph_started"}
            ):
                continue
            tool_event_counts[event] = tool_event_counts.get(event, 0) + 1
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            latest_tool_event = {
                "event": event,
                "batch_id": str(entry.get("batch_id") or ""),
                "status": str(payload.get("status") or ""),
                "error_code": str(payload.get("error_code") or ""),
            }
        return {
            "started_count": tool_event_counts.get("tool_call_started", 0),
            "succeeded_count": tool_event_counts.get("tool_call_succeeded", 0),
            "failed_count": tool_event_counts.get("tool_call_failed", 0)
            + tool_event_counts.get("tool_call_handler_failed", 0)
            + tool_event_counts.get("tool_call_invalid_result", 0)
            + tool_event_counts.get("tool_call_invalid_state_patch", 0)
            + tool_event_counts.get("tool_call_runtime_facts_missing", 0)
            + tool_event_counts.get("tool_call_runtime_facts_rejected", 0),
            "blocked_count": tool_event_counts.get("tool_call_blocked", 0),
            "retry_scheduled_count": tool_event_counts.get("tool_call_retry_scheduled", 0),
            "skipped_count": tool_event_counts.get("tool_call_skipped", 0)
            + tool_event_counts.get("tool_call_abandoned_late_result", 0),
            "tool_event_counts": dict(sorted(tool_event_counts.items())),
            "latest_tool_event": latest_tool_event,
        }

    @staticmethod
    def _tool_graph_queue_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "queued_count": 0,
                "dequeued_count": 0,
                "completed_count": 0,
                "rejected_count": 0,
                "empty_count": 0,
                "blocked_count": 0,
                "missing_graph_count": 0,
                "queue_status_counts": {},
                "queue_event_counts": {},
                "latest_queue_event": {},
            }
        tracked = {
            "tool_graph_queued",
            "tool_graph_dequeued",
            "tool_graph_queue_state_persisted",
            "tool_graph_queue_state_persist_failed",
            "tool_graph_queue_update_failed",
            "tool_graph_queue_rejected",
            "tool_graph_queue_empty",
            "tool_graph_queue_missing_graph",
            "tool_graph_drain_blocked_by_runtime_command",
            "tool_graph_stopped_by_runtime_command",
        }
        queue_event_counts: dict[str, int] = {}
        queue_status_counts: dict[str, int] = {}
        latest_queue_event: dict[str, Any] = {}
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if event not in tracked:
                continue
            queue_event_counts[event] = queue_event_counts.get(event, 0) + 1
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            status = str(payload.get("status") or "").strip()
            if status:
                queue_status_counts[status] = queue_status_counts.get(status, 0) + 1
            latest_queue_event = {
                "event": event,
                "batch_id": str(entry.get("batch_id") or ""),
                "status": status,
            }
        return {
            "queued_count": queue_event_counts.get("tool_graph_queued", 0),
            "dequeued_count": queue_event_counts.get("tool_graph_dequeued", 0),
            "completed_count": queue_status_counts.get("completed", 0),
            "rejected_count": queue_event_counts.get("tool_graph_queue_rejected", 0),
            "empty_count": queue_event_counts.get("tool_graph_queue_empty", 0),
            "blocked_count": queue_event_counts.get("tool_graph_drain_blocked_by_runtime_command", 0)
            + queue_event_counts.get("tool_graph_stopped_by_runtime_command", 0),
            "missing_graph_count": queue_event_counts.get("tool_graph_queue_missing_graph", 0),
            "queue_status_counts": dict(sorted(queue_status_counts.items())),
            "queue_event_counts": dict(sorted(queue_event_counts.items())),
            "latest_queue_event": latest_queue_event,
        }

    @staticmethod
    def _worker_drain_replay_summary(entries: Any) -> dict[str, Any]:
        default = {
            "requested_count": 0,
            "message_drained_count": 0,
            "failed_count": 0,
            "exception_count": 0,
            "status_failed_count": 0,
            "plan_resolve_failed_count": 0,
            "drained_graph_total": 0,
            "event_counts": {},
            "latest_drain_event": {},
        }
        if not isinstance(entries, list):
            return default
        tracked = {
            "runtime_worker_drain_requested",
            "runtime_message_drained",
            "runtime_worker_drain_failed",
            "runtime_worker_drain_exception",
            "runtime_worker_drain_status_failed",
            "runtime_worker_drain_plan_resolve_failed",
        }
        event_counts: dict[str, int] = {}
        drained_graph_total = 0
        latest_drain_event: dict[str, Any] = {}
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if event not in tracked:
                continue
            event_counts[event] = event_counts.get(event, 0) + 1
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            drained_graph_total += int(payload.get("drained_count") or 0)
            latest_drain_event = {
                "event": event,
                "plan_id": str(entry.get("plan_id") or ""),
                "batch_id": str(entry.get("batch_id") or ""),
                "drained_count": int(payload.get("drained_count") or 0),
                "reason": str(payload.get("reason") or "")[:160],
            }
        return {
            "requested_count": event_counts.get("runtime_worker_drain_requested", 0),
            "message_drained_count": event_counts.get("runtime_message_drained", 0),
            "failed_count": event_counts.get("runtime_worker_drain_failed", 0),
            "exception_count": event_counts.get("runtime_worker_drain_exception", 0),
            "status_failed_count": event_counts.get("runtime_worker_drain_status_failed", 0),
            "plan_resolve_failed_count": event_counts.get("runtime_worker_drain_plan_resolve_failed", 0),
            "drained_graph_total": drained_graph_total,
            "event_counts": dict(sorted(event_counts.items())),
            "latest_drain_event": latest_drain_event,
        }

    @staticmethod
    def _resource_readiness_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "status_query_count": 0,
                "published_count": 0,
                "publish_failed_count": 0,
                "readiness_event_count": 0,
                "publish_enabled_total": 0,
                "publish_unavailable_total": 0,
                "publish_requested_total": 0,
                "publish_status_counts": {},
                "status_query_enabled_total": 0,
                "status_query_unavailable_total": 0,
                "status_query_requested_total": 0,
                "status_query_status_counts": {},
                "status_counts": {},
                "latest_publish_event": {},
                "latest_provider_status_query": {},
                "latest_readiness_event": {},
            }
        status_query_count = 0
        published_count = 0
        publish_failed_count = 0
        readiness_event_count = 0
        publish_enabled_total = 0
        publish_unavailable_total = 0
        publish_requested_total = 0
        publish_status_counts: dict[str, int] = {}
        status_query_enabled_total = 0
        status_query_unavailable_total = 0
        status_query_requested_total = 0
        status_query_status_counts: dict[str, int] = {}
        status_counts: dict[str, int] = {}
        latest_publish_event: dict[str, Any] = {}
        latest_provider_status_query: dict[str, Any] = {}
        latest_readiness_event: dict[str, Any] = {}
        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                message = str(entry.message or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                message = str(entry.get("message") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            else:
                continue
            if event == "runtime_provider_status_queried":
                status_query_count += 1
                enabled_count = int(payload.get("readiness_enabled_count") or 0)
                unavailable_count = int(payload.get("readiness_unavailable_count") or 0)
                requested_count = int(payload.get("readiness_requested_count") or 0)
                status_query_enabled_total += enabled_count
                status_query_unavailable_total += unavailable_count
                status_query_requested_total += requested_count
                payload_status_counts = (
                    payload.get("readiness_status_counts")
                    if isinstance(payload.get("readiness_status_counts"), Mapping)
                    else {}
                )
                safe_status_counts: dict[str, int] = {}
                for key, value in payload_status_counts.items():
                    status_key = str(key or "").strip().replace("_", "-")[:64]
                    if not status_key:
                        continue
                    count = int(value or 0)
                    if count <= 0:
                        continue
                    status_query_status_counts[status_key] = (
                        status_query_status_counts.get(status_key, 0) + count
                    )
                    safe_status_counts[status_key] = count
                latest_provider_status_query = {
                    "recorded": bool(payload.get("recorded")),
                    "readiness_channel_count": int(payload.get("readiness_channel_count") or 0),
                    "readiness_requested_count": requested_count,
                    "readiness_enabled_count": enabled_count,
                    "readiness_unavailable_count": unavailable_count,
                    "readiness_status_counts": dict(sorted(safe_status_counts.items())),
                }
                continue
            if event in {"runtime_provider_readiness_published", "runtime_provider_readiness_publish_failed"}:
                if event == "runtime_provider_readiness_published":
                    published_count += 1
                else:
                    publish_failed_count += 1
                enabled_count = int(payload.get("readiness_enabled_count") or 0)
                unavailable_count = int(payload.get("readiness_unavailable_count") or 0)
                requested_count = int(payload.get("readiness_requested_count") or 0)
                publish_enabled_total += enabled_count
                publish_unavailable_total += unavailable_count
                publish_requested_total += requested_count
                payload_status_counts = (
                    payload.get("readiness_status_counts")
                    if isinstance(payload.get("readiness_status_counts"), Mapping)
                    else {}
                )
                safe_status_counts: dict[str, int] = {}
                for key, value in payload_status_counts.items():
                    status_key = str(key or "").strip().replace("_", "-")[:64]
                    if not status_key:
                        continue
                    count = int(value or 0)
                    if count <= 0:
                        continue
                    publish_status_counts[status_key] = publish_status_counts.get(status_key, 0) + count
                    safe_status_counts[status_key] = count
                latest_publish_event = {
                    "event": event,
                    "succeeded": event == "runtime_provider_readiness_published",
                    "readiness_channel_count": int(payload.get("readiness_channel_count") or 0),
                    "readiness_requested_count": requested_count,
                    "readiness_enabled_count": enabled_count,
                    "readiness_unavailable_count": unavailable_count,
                    "readiness_status_counts": dict(sorted(safe_status_counts.items())),
                }
                continue
            if event != "runtime_event_emitted":
                continue
            event_type = str(payload.get("event_type") or message or "").strip()
            if event_type != "provider_readiness":
                continue
            readiness_event_count += 1
            event_payload = payload.get("payload") if isinstance(payload.get("payload"), Mapping) else {}
            status = (
                str(payload.get("readiness_status") or "").strip()
                or str(event_payload.get("status") or "").strip()
                or "unknown"
            )
            status_counts[status] = status_counts.get(status, 0) + 1
            latest_readiness_event = {
                "status": status,
                "level": str(payload.get("level") or ""),
            }
        return {
            "status_query_count": status_query_count,
            "published_count": published_count,
            "publish_failed_count": publish_failed_count,
            "readiness_event_count": readiness_event_count,
            "publish_enabled_total": publish_enabled_total,
            "publish_unavailable_total": publish_unavailable_total,
            "publish_requested_total": publish_requested_total,
            "publish_status_counts": dict(sorted(publish_status_counts.items())),
            "status_query_enabled_total": status_query_enabled_total,
            "status_query_unavailable_total": status_query_unavailable_total,
            "status_query_requested_total": status_query_requested_total,
            "status_query_status_counts": dict(sorted(status_query_status_counts.items())),
            "status_counts": dict(sorted(status_counts.items())),
            "latest_publish_event": latest_publish_event,
            "latest_provider_status_query": latest_provider_status_query,
            "latest_readiness_event": latest_readiness_event,
        }

    @staticmethod
    def _batch_execution_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "started_count": 0,
                "completed_count": 0,
                "partial_count": 0,
                "failed_count": 0,
                "cancelled_count": 0,
                "finalized_count": 0,
                "terminal_count": 0,
                "status_counts": {},
                "latest_batch": {},
            }
        status_counts: dict[str, int] = {}
        started_count = 0
        completed_count = 0
        partial_count = 0
        failed_count = 0
        cancelled_count = 0
        terminal_count = 0
        finalized_count = 0
        latest_batch: dict[str, Any] = {}
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if event == "batch_execution_started":
                started_count += 1
            elif event == "batch_execution_completed":
                completed_count += 1
                terminal_count += 1
            elif event == "batch_execution_partial":
                partial_count += 1
                terminal_count += 1
            elif event == "batch_execution_failed":
                failed_count += 1
                terminal_count += 1
            elif event == "batch_execution_cancelled":
                cancelled_count += 1
                terminal_count += 1
            elif event == "batch_plan_finalized_by_tool_graph":
                finalized_count += 1
            else:
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            status = str(
                payload.get("batch_status")
                or payload.get("status")
                or payload.get("graph_status")
                or "unknown"
            ).strip() or "unknown"
            status_counts[status] = status_counts.get(status, 0) + 1
            latest_batch = {
                "event": event,
                "batch_id": str(entry.get("batch_id") or ""),
                "status": status,
                "graph_status": str(payload.get("graph_status") or ""),
            }
        return {
            "started_count": started_count,
            "completed_count": completed_count,
            "partial_count": partial_count,
            "failed_count": failed_count,
            "cancelled_count": cancelled_count,
            "finalized_count": finalized_count,
            "terminal_count": terminal_count,
            "status_counts": dict(sorted(status_counts.items())),
            "latest_batch": latest_batch,
        }

    @staticmethod
    def _batch_resource_lifecycle_replay_summary(entries: Any) -> dict[str, Any]:
        default = {
            "resource_event_count": 0,
            "image_ready_count": 0,
            "image_failed_count": 0,
            "model_ready_count": 0,
            "model_failed_count": 0,
            "import_ready_count": 0,
            "import_failed_count": 0,
            "environment_ready_count": 0,
            "environment_failed_count": 0,
            "emit_failed_count": 0,
            "batch_event_counts": {},
            "latest_resource_event": {},
        }
        if not isinstance(entries, list):
            return default
        tracked = {
            "image_resources_ready": ("image_ready_count", "image"),
            "image_resources_failed": ("image_failed_count", "image"),
            "model_resources_ready": ("model_ready_count", "model"),
            "model_resources_failed": ("model_failed_count", "model"),
            "actors_imported": ("import_ready_count", "import"),
            "actors_import_failed": ("import_failed_count", "import"),
            "environment_components_ready": ("environment_ready_count", "environment"),
            "environment_components_failed": ("environment_failed_count", "environment"),
            "environment_components_imported": ("environment_ready_count", "environment_import"),
            "environment_components_import_failed": ("environment_failed_count", "environment_import"),
        }
        summary = dict(default)
        batch_event_counts: dict[str, int] = {}
        latest_resource_event: dict[str, Any] = {}
        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                batch_id = str(entry.batch_id or "")
                message = str(entry.message or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                batch_id = str(entry.get("batch_id") or "")
                message = str(entry.get("message") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            else:
                continue
            if event not in {"runtime_event_emitted", "runtime_event_emit_failed"}:
                continue
            event_type = str(payload.get("event_type") or message or "").strip()
            if event_type not in tracked:
                continue
            counter_key, stage = tracked[event_type]
            summary["resource_event_count"] = int(summary["resource_event_count"]) + 1
            summary[counter_key] = int(summary[counter_key]) + 1
            if event == "runtime_event_emit_failed":
                summary["emit_failed_count"] = int(summary["emit_failed_count"]) + 1
            batch_key = batch_id or "no_batch"
            batch_event_counts[batch_key] = batch_event_counts.get(batch_key, 0) + 1
            latest_resource_event = {
                "event_type": event_type,
                "stage": stage,
                "batch_id": batch_id,
                "persisted": event == "runtime_event_emitted",
            }
        summary["batch_event_counts"] = dict(sorted(batch_event_counts.items()))
        summary["latest_resource_event"] = latest_resource_event
        return summary

    @staticmethod
    def _runtime_command_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "command_count": 0,
                "command_counts": {},
                "cancelled_batch_total": 0,
                "cancelled_graph_total": 0,
                "resumed_graph_total": 0,
                "retried_graph_total": 0,
                "status_transition_counts": {},
                "latest_command": {},
            }
        command_counts: dict[str, int] = {}
        status_transition_counts: dict[str, int] = {}
        cancelled_batch_total = 0
        cancelled_graph_total = 0
        resumed_graph_total = 0
        retried_graph_total = 0
        latest_command: dict[str, Any] = {}
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if not event.startswith("runtime_") or not event.endswith("_command_applied"):
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            command = str(payload.get("command") or "").strip()
            if not command:
                continue
            command_counts[command] = command_counts.get(command, 0) + 1
            old_status = str(payload.get("old_status") or "")
            new_status = str(payload.get("new_status") or "")
            transition = f"{old_status}->{new_status}" if old_status or new_status else "unknown"
            status_transition_counts[transition] = status_transition_counts.get(transition, 0) + 1
            cancelled_batch_total += int(payload.get("cancelled_batches") or 0)
            cancelled_graph_total += int(payload.get("cancelled_graphs") or 0)
            resumed_graph_total += int(payload.get("resumed_graphs") or 0)
            retried_graph_total += int(payload.get("retried_graphs") or 0)
            latest_command = {
                "command": command,
                "old_status": old_status,
                "new_status": new_status,
                "cancelled_batches": int(payload.get("cancelled_batches") or 0),
                "cancelled_graphs": int(payload.get("cancelled_graphs") or 0),
                "resumed_graphs": int(payload.get("resumed_graphs") or 0),
                "retried_graphs": int(payload.get("retried_graphs") or 0),
            }
        return {
            "command_count": sum(command_counts.values()),
            "command_counts": dict(sorted(command_counts.items())),
            "cancelled_batch_total": cancelled_batch_total,
            "cancelled_graph_total": cancelled_graph_total,
            "resumed_graph_total": resumed_graph_total,
            "retried_graph_total": retried_graph_total,
            "status_transition_counts": dict(sorted(status_transition_counts.items())),
            "latest_command": latest_command,
        }

    @staticmethod
    def _engine_write_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "import_result_count": 0,
                "transform_result_count": 0,
                "delete_result_count": 0,
                "environment_import_result_count": 0,
                "import_boundary_attempt_count": 0,
                "transform_boundary_attempt_count": 0,
                "delete_boundary_attempt_count": 0,
                "environment_import_boundary_attempt_count": 0,
                "runtime_state_only_write_attempt_count": 0,
                "import_status_counts": {},
                "transform_status_counts": {},
                "delete_status_counts": {},
                "environment_import_status_counts": {},
                "latest_import_results": [],
                "latest_transform_results": [],
                "latest_delete_results": [],
                "latest_environment_import_results": [],
                "status_export_count": 0,
                "latest_status_export": {},
            }
        import_status_counts: dict[str, int] = {}
        transform_status_counts: dict[str, int] = {}
        delete_status_counts: dict[str, int] = {}
        environment_import_status_counts: dict[str, int] = {}
        import_rows: list[dict[str, Any]] = []
        transform_rows: list[dict[str, Any]] = []
        delete_rows: list[dict[str, Any]] = []
        environment_import_rows: list[dict[str, Any]] = []
        status_export_count = 0
        latest_status_export: dict[str, Any] = {}
        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            else:
                continue
            if event == "runtime_engine_write_status_exported":
                status_export_count += 1
                latest_status_export = {
                    "recorded": bool(payload.get("recorded")),
                    "reason": AgentRuntime._safe_report_text(payload.get("reason"))[:120],
                    "engine_write_boundary_fact_count": int(
                        payload.get("engine_write_boundary_fact_count") or 0
                    ),
                    "engine_write_import_boundary_count": int(
                        payload.get("engine_write_import_boundary_count") or 0
                    ),
                    "engine_write_environment_import_boundary_count": int(
                        payload.get("engine_write_environment_import_boundary_count") or 0
                    ),
                    "engine_write_transform_boundary_count": int(
                        payload.get("engine_write_transform_boundary_count") or 0
                    ),
                    "engine_write_delete_boundary_count": int(
                        payload.get("engine_write_delete_boundary_count") or 0
                    ),
                    "engine_write_bridge_call_count": int(
                        payload.get("engine_write_bridge_call_count") or 0
                    ),
                    "engine_write_bridge_success_count": int(
                        payload.get("engine_write_bridge_success_count") or 0
                    ),
                    "engine_write_bridge_failed_count": int(
                        payload.get("engine_write_bridge_failed_count") or 0
                    ),
                    "engine_write_bridge_error_code_counts": AgentRuntime._safe_status_count_map(
                        payload.get("engine_write_bridge_error_code_counts")
                    ),
                    "engine_write_readiness_native_enabled_count": int(
                        payload.get("engine_write_readiness_native_enabled_count") or 0
                    ),
                    "engine_write_readiness_runtime_state_only_count": int(
                        payload.get("engine_write_readiness_runtime_state_only_count") or 0
                    ),
                    "engine_write_readiness_fallback_count": int(
                        payload.get("engine_write_readiness_fallback_count") or 0
                    ),
                    "engine_write_readiness_disabled_count": int(
                        payload.get("engine_write_readiness_disabled_count") or 0
                    ),
                    "engine_write_readiness_unavailable_count": int(
                        payload.get("engine_write_readiness_unavailable_count") or 0
                    ),
                    "engine_write_readiness_native_enabled_channels": [
                        AgentRuntime._safe_report_text(item).replace("_", "-")[:48]
                        for item in list(payload.get("engine_write_readiness_native_enabled_channels") or [])[:8]
                        if AgentRuntime._safe_report_text(item).strip()
                    ],
                    "engine_write_readiness_runtime_state_only_channels": [
                        AgentRuntime._safe_report_text(item).replace("_", "-")[:48]
                        for item in list(payload.get("engine_write_readiness_runtime_state_only_channels") or [])[:8]
                        if AgentRuntime._safe_report_text(item).strip()
                    ],
                    "engine_write_readiness_fallback_channels": [
                        AgentRuntime._safe_report_text(item).replace("_", "-")[:48]
                        for item in list(payload.get("engine_write_readiness_fallback_channels") or [])[:8]
                        if AgentRuntime._safe_report_text(item).strip()
                    ],
                    "engine_write_readiness_disabled_channels": [
                        AgentRuntime._safe_report_text(item).replace("_", "-")[:48]
                        for item in list(payload.get("engine_write_readiness_disabled_channels") or [])[:8]
                        if AgentRuntime._safe_report_text(item).strip()
                    ],
                    "engine_write_readiness_unavailable_channels": [
                        AgentRuntime._safe_report_text(item).replace("_", "-")[:48]
                        for item in list(payload.get("engine_write_readiness_unavailable_channels") or [])[:8]
                        if AgentRuntime._safe_report_text(item).strip()
                    ],
                }
            safe_imports = ToolCallGraphExecutor._safe_engine_result_rows(
                payload.get("import_results"),
                id_fields=("actor_id", "actor_name"),
            )
            safe_transforms = ToolCallGraphExecutor._safe_engine_result_rows(
                payload.get("transform_results"),
                id_fields=("actor_id", "actor_name"),
            )
            safe_deletes = ToolCallGraphExecutor._safe_engine_result_rows(
                payload.get("delete_results"),
                id_fields=("actor_id", "actor_name"),
            )
            safe_environment_imports = ToolCallGraphExecutor._safe_engine_result_rows(
                payload.get("environment_import_results"),
                id_fields=("component_id", "component_name", "name", "actor_id"),
            )
            for row in safe_imports:
                status = str(row.get("status") or "unknown").strip() or "unknown"
                import_status_counts[status] = import_status_counts.get(status, 0) + 1
                import_rows.append(row)
            for row in safe_transforms:
                status = str(row.get("status") or "unknown").strip() or "unknown"
                transform_status_counts[status] = transform_status_counts.get(status, 0) + 1
                transform_rows.append(row)
            for row in safe_deletes:
                status = str(row.get("status") or "unknown").strip() or "unknown"
                delete_status_counts[status] = delete_status_counts.get(status, 0) + 1
                delete_rows.append(row)
            for row in safe_environment_imports:
                status = str(row.get("status") or "unknown").strip() or "unknown"
                environment_import_status_counts[status] = environment_import_status_counts.get(status, 0) + 1
                environment_import_rows.append(row)
        native_channels = {
            str(item or "").replace("_", "-").strip()
            for item in list(latest_status_export.get("engine_write_readiness_native_enabled_channels") or [])
            if str(item or "").strip()
        }
        runtime_state_only_statuses = {"runtime_state_only", "noop", "no_op", "skipped"}

        def rows_are_runtime_state_only(rows: list[dict[str, Any]]) -> bool:
            if not rows:
                return False
            for row in rows:
                status = str(row.get("status") or "").strip().lower()
                if status not in runtime_state_only_statuses:
                    return False
            return True

        mismatch_channels: list[str] = []
        for channel, rows in (
            ("actor-import", import_rows),
            ("layout-transform", transform_rows),
            ("actor-delete", delete_rows),
            ("environment-import", environment_import_rows),
        ):
            if rows and channel not in native_channels and not rows_are_runtime_state_only(rows):
                mismatch_channels.append(channel)
        return {
            "import_result_count": len(import_rows),
            "transform_result_count": len(transform_rows),
            "delete_result_count": len(delete_rows),
            "environment_import_result_count": len(environment_import_rows),
            "import_boundary_attempt_count": int(
                latest_status_export.get("engine_write_import_boundary_count") or 0
            ),
            "transform_boundary_attempt_count": int(
                latest_status_export.get("engine_write_transform_boundary_count") or 0
            ),
            "delete_boundary_attempt_count": int(
                latest_status_export.get("engine_write_delete_boundary_count") or 0
            ),
            "environment_import_boundary_attempt_count": int(
                latest_status_export.get("engine_write_environment_import_boundary_count") or 0
            ),
            "runtime_state_only_write_attempt_count": int(
                latest_status_export.get("engine_write_readiness_runtime_state_only_count") or 0
            ) + int(latest_status_export.get("engine_write_readiness_fallback_count") or 0),
            "readiness_mismatch_count": len(mismatch_channels),
            "readiness_mismatch_channels": mismatch_channels,
            "import_status_counts": dict(sorted(import_status_counts.items())),
            "transform_status_counts": dict(sorted(transform_status_counts.items())),
            "delete_status_counts": dict(sorted(delete_status_counts.items())),
            "environment_import_status_counts": dict(sorted(environment_import_status_counts.items())),
            "latest_import_results": import_rows[-5:],
            "latest_transform_results": transform_rows[-5:],
            "latest_delete_results": delete_rows[-5:],
            "latest_environment_import_results": environment_import_rows[-5:],
            "status_export_count": status_export_count,
            "latest_status_export": latest_status_export,
        }

    @staticmethod
    def _merge_engine_write_boundary_attempts(
        engine_write_summary: Mapping[str, Any] | None,
        engine_write_boundary_summary: Mapping[str, Any] | None,
    ) -> dict[str, Any]:
        summary = dict(engine_write_summary or {})
        boundary = dict(engine_write_boundary_summary or {})
        boundary_status_counts = AgentRuntime._safe_status_count_map(boundary.get("status_counts"))

        def set_max(key: str, value: Any) -> None:
            summary[key] = max(int(summary.get(key) or 0), int(value or 0))

        set_max("import_boundary_attempt_count", boundary.get("import_boundary_count"))
        set_max("transform_boundary_attempt_count", boundary.get("transform_boundary_count"))
        set_max("delete_boundary_attempt_count", boundary.get("delete_boundary_count"))
        set_max(
            "environment_import_boundary_attempt_count",
            boundary.get("environment_import_boundary_count"),
        )
        set_max(
            "runtime_state_only_write_attempt_count",
            boundary_status_counts.get("runtime_state_only"),
        )
        set_max("engine_write_bridge_call_count", boundary.get("bridge_call_count"))
        set_max("engine_write_bridge_success_count", boundary.get("bridge_success_count"))
        set_max("engine_write_bridge_failed_count", boundary.get("bridge_failed_count"))
        bridge_error_code_counts = AgentRuntime._safe_status_count_map(
            boundary.get("bridge_error_code_counts")
        )
        if bridge_error_code_counts:
            existing_bridge_errors = AgentRuntime._safe_status_count_map(
                summary.get("engine_write_bridge_error_code_counts")
            )
            for error_code, count in bridge_error_code_counts.items():
                existing_bridge_errors[error_code] = max(
                    int(existing_bridge_errors.get(error_code) or 0),
                    int(count or 0),
                )
            summary["engine_write_bridge_error_code_counts"] = dict(sorted(existing_bridge_errors.items()))
        if boundary_status_counts:
            existing = AgentRuntime._safe_status_count_map(
                summary.get("engine_write_boundary_status_counts")
            )
            for status, count in boundary_status_counts.items():
                existing[status] = max(int(existing.get(status) or 0), int(count or 0))
            summary["engine_write_boundary_status_counts"] = dict(sorted(existing.items()))
        return summary

    @staticmethod
    def _engine_write_boundary_summary_for_plan(
        room: Mapping[str, Any],
        plan_id: str,
        *,
        batch_id: str = "",
    ) -> dict[str, Any]:
        if not isinstance(room, Mapping):
            return {
                "boundary_fact_count": 0,
                "import_boundary_count": 0,
                "environment_import_boundary_count": 0,
                "transform_boundary_count": 0,
                "delete_boundary_count": 0,
                "write_source_counts": {},
                "status_counts": {},
                "latest_boundaries": [],
            }
        active_plan_id = str(plan_id or "")
        active_batch_id = str(batch_id or "")
        batch_ids = AgentRuntime._batch_ids_for_plan(room, active_plan_id) if active_plan_id else set()
        rows: list[dict[str, Any]] = []

        import_facts = dict(room.get("custom_import_facts") or {})
        for key, fact in import_facts.items():
            if not isinstance(fact, Mapping):
                continue
            key_text = str(key)
            if key_text.endswith(":actor_import_result"):
                boundary_kind = "actor_import"
            elif key_text.endswith(":environment_import_result"):
                boundary_kind = "environment_import"
            else:
                continue
            fact_batch_id = str(fact.get("batch_id") or "").strip()
            if active_batch_id and fact_batch_id != active_batch_id:
                continue
            if active_plan_id and fact_batch_id and fact_batch_id not in batch_ids:
                continue
            boundary = fact.get("engine_write_boundary")
            if isinstance(boundary, Mapping):
                rows.append(AgentRuntime._safe_engine_write_boundary_row(boundary_kind, boundary))

        layout_proposals = dict(room.get("layout_adjustment_proposals") or {})
        for key, proposal in layout_proposals.items():
            if not isinstance(proposal, Mapping):
                continue
            proposal_plan_id = str(proposal.get("plan_id") or key or "")
            if active_plan_id and proposal_plan_id != active_plan_id and str(key) != active_plan_id:
                continue
            if active_batch_id and str(proposal.get("batch_id") or "") not in {"", active_batch_id}:
                continue
            boundary = proposal.get("engine_transform_boundary")
            if isinstance(boundary, Mapping):
                rows.append(AgentRuntime._safe_engine_write_boundary_row("layout_transform", boundary))

        review_proposals = dict(room.get("review_advisory_proposals") or {})
        for key, proposal in review_proposals.items():
            if not isinstance(proposal, Mapping):
                continue
            proposal_plan_id = str(proposal.get("plan_id") or "")
            if active_plan_id and proposal_plan_id != active_plan_id and not str(key).startswith(f"{active_plan_id}:"):
                continue
            if active_batch_id and str(proposal.get("batch_id") or "") not in {"", active_batch_id}:
                continue
            boundary = proposal.get("engine_delete_boundary")
            if isinstance(boundary, Mapping):
                rows.append(AgentRuntime._safe_engine_write_boundary_row("actor_delete", boundary))

        write_source_counts: dict[str, int] = {}
        status_counts: dict[str, int] = {}
        bridge_method_counts: dict[str, int] = {}
        bridge_error_code_counts: dict[str, int] = {}
        bridge_call_count = 0
        bridge_success_count = 0
        bridge_failed_count = 0
        bridge_skipped_count = 0
        kind_counts = {"actor_import": 0, "environment_import": 0, "layout_transform": 0, "actor_delete": 0}
        for row in rows:
            kind = str(row.get("kind") or "")
            if kind in kind_counts:
                kind_counts[kind] += 1
            source = str(row.get("write_source") or "unknown")
            write_source_counts[source] = write_source_counts.get(source, 0) + 1
            for status, count in dict(row.get("status_counts") or {}).items():
                status_counts[status] = status_counts.get(status, 0) + int(count)
            bridge_call_count += int(row.get("bridge_call_count") or 0)
            bridge_success_count += int(row.get("bridge_success_count") or 0)
            bridge_failed_count += int(row.get("bridge_failed_count") or 0)
            bridge_skipped_count += int(row.get("bridge_skipped_count") or 0)
            for method, count in dict(row.get("bridge_method_counts") or {}).items():
                method_text = str(method or "").strip()
                if method_text:
                    bridge_method_counts[method_text] = bridge_method_counts.get(method_text, 0) + int(count)
            for reason, count in dict(row.get("bridge_skip_reason_counts") or {}).items():
                reason_text = str(reason or "").strip()
                if reason_text:
                    bridge_error_code_counts[reason_text] = bridge_error_code_counts.get(reason_text, 0) + int(count)
            for error_code, count in dict(row.get("bridge_error_code_counts") or {}).items():
                error_text = str(error_code or "").strip()
                if error_text:
                    bridge_error_code_counts[error_text] = bridge_error_code_counts.get(error_text, 0) + int(count)
        return {
            "boundary_fact_count": len(rows),
            "import_boundary_count": kind_counts["actor_import"],
            "environment_import_boundary_count": kind_counts["environment_import"],
            "transform_boundary_count": kind_counts["layout_transform"],
            "delete_boundary_count": kind_counts["actor_delete"],
            "write_source_counts": dict(sorted(write_source_counts.items())),
            "status_counts": dict(sorted(status_counts.items())),
            "bridge_call_count": bridge_call_count,
            "bridge_success_count": bridge_success_count,
            "bridge_failed_count": bridge_failed_count,
            "bridge_skipped_count": bridge_skipped_count,
            "bridge_method_counts": dict(sorted(bridge_method_counts.items())),
            "bridge_error_code_counts": dict(sorted(bridge_error_code_counts.items())),
            "latest_boundaries": rows[-5:],
        }

    @staticmethod
    def _safe_engine_write_boundary_row(kind: str, boundary: Mapping[str, Any]) -> dict[str, Any]:
        safe_kind = str(kind or "").strip().lower()
        if safe_kind not in {"actor_import", "environment_import", "layout_transform", "actor_delete"}:
            safe_kind = "unknown"
        status_counts = AgentRuntime._safe_status_count_map(boundary.get("status_counts"))
        row = {
            "kind": safe_kind,
            "write_source": AgentRuntime._safe_engine_write_source_label(
                boundary.get("provider_source") or ""
            ),
            "requested_count": max(0, int(boundary.get("requested_count") or 0)),
            "status_counts": status_counts,
            **AgentRuntime._safe_engine_bridge_boundary_fields(boundary),
        }
        if safe_kind == "actor_import":
            row["accepted_count"] = max(0, int(boundary.get("identity_result_count") or 0))
            row["observed_count"] = max(0, int(boundary.get("identity_result_count") or 0))
            row["missing_identity_count"] = max(0, int(boundary.get("missing_identity_count") or 0))
        elif safe_kind == "environment_import":
            row["accepted_count"] = max(0, int(boundary.get("identity_result_count") or 0))
            row["observed_count"] = max(0, int(boundary.get("identity_result_count") or 0))
            row["missing_identity_count"] = max(0, int(boundary.get("missing_identity_count") or 0))
        elif safe_kind == "layout_transform":
            row["accepted_count"] = max(0, int(boundary.get("updated_count") or 0))
            row["observed_count"] = max(0, int(boundary.get("observed_position_count") or 0))
        elif safe_kind == "actor_delete":
            row["accepted_count"] = max(0, int(boundary.get("deleted_count") or 0))
            row["observed_count"] = max(0, int(boundary.get("observed_deleted_count") or 0))
        else:
            row["accepted_count"] = 0
            row["observed_count"] = 0
        return row

    @staticmethod
    def _safe_engine_bridge_boundary_fields(boundary: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "bridge_call_count": max(0, int(boundary.get("bridge_call_count") or 0)),
            "bridge_success_count": max(0, int(boundary.get("bridge_success_count") or 0)),
            "bridge_failed_count": max(0, int(boundary.get("bridge_failed_count") or 0)),
            "bridge_skipped_count": max(0, int(boundary.get("bridge_skipped_count") or 0)),
            "bridge_skip_reason_counts": AgentRuntime._safe_status_count_map(
                boundary.get("bridge_skip_reason_counts")
            ),
            "bridge_method_counts": AgentRuntime._safe_status_count_map(
                boundary.get("bridge_method_counts")
            ),
            "bridge_error_code_counts": AgentRuntime._safe_status_count_map(
                boundary.get("bridge_error_code_counts")
            ),
        }

    @staticmethod
    def _fact_source_boundary_summary(
        *,
        plan_summary: Mapping[str, Any] | None = None,
        batch_summary: Mapping[str, Any] | None = None,
        resource_summary: Mapping[str, Any] | None = None,
        import_summary: Mapping[str, Any] | None = None,
        sync_summary: Mapping[str, Any] | None = None,
        engine_write_summary: Mapping[str, Any] | None = None,
        engine_write_boundary_summary: Mapping[str, Any] | None = None,
        scene_snapshot_summary: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        plan_data = dict(plan_summary or {})
        batch_data = dict(batch_summary or {})
        resource_data = dict(resource_summary or {})
        import_data = dict(import_summary or {})
        sync_data = dict(sync_summary or {})
        engine_data = dict(engine_write_summary or {})
        engine_boundary_data = dict(engine_write_boundary_summary or {})
        snapshot_data = dict(scene_snapshot_summary or {})
        batch_count = int(batch_data.get("batch_count") or len(list(batch_data.get("batches") or [])) or 0)
        runtime_plan_fact_count = int(bool(str(plan_data.get("title") or plan_data.get("status") or "").strip()))
        runtime_batch_fact_count = batch_count
        runtime_resource_fact_count = int(resource_data.get("event_count") or 0)
        runtime_resource_phase_fact_count = int(resource_data.get("fact_count") or 0)
        runtime_import_fact_count = int(import_data.get("event_count") or 0)
        sync_event_count = int(sync_data.get("event_count") or 0)
        engine_write_result_count = sum(
            int(engine_data.get(key) or 0)
            for key in (
                "import_result_count",
                "transform_result_count",
                "delete_result_count",
                "environment_import_result_count",
            )
        )
        engine_write_boundary_fact_count = int(engine_boundary_data.get("boundary_fact_count") or 0)
        scene_snapshot_count = int(
            snapshot_data.get("scoped_snapshot_count")
            or snapshot_data.get("snapshot_count")
            or 0
        )
        mirrored_external_fact_count = (
            sync_event_count
            + engine_write_result_count
            + engine_write_boundary_fact_count
            + scene_snapshot_count
        )
        runtime_business_fact_count = (
            runtime_plan_fact_count
            + runtime_batch_fact_count
            + runtime_resource_fact_count
            + runtime_resource_phase_fact_count
            + runtime_import_fact_count
        )
        boundary_notes = [
            "runtime-state-is-business-truth",
            "engine-lanchat-facts-are-mirrored",
        ]
        if mirrored_external_fact_count <= 0:
            boundary_notes.append("external-engine-facts-not-yet-observed")
        return {
            "runtime_state_source": "RuntimeState",
            "external_truth_source": "engine_lanchat_mirrored",
            "runtime_business_fact_count": runtime_business_fact_count,
            "runtime_plan_fact_count": runtime_plan_fact_count,
            "runtime_batch_fact_count": runtime_batch_fact_count,
            "runtime_resource_event_count": runtime_resource_fact_count,
            "runtime_resource_phase_fact_count": runtime_resource_phase_fact_count,
            "runtime_import_event_count": runtime_import_fact_count,
            "sync_event_count": sync_event_count,
            "engine_write_result_count": engine_write_result_count,
            "engine_write_boundary_fact_count": engine_write_boundary_fact_count,
            "scene_snapshot_count": scene_snapshot_count,
            "mirrored_external_fact_count": mirrored_external_fact_count,
            "external_authoritative_available": mirrored_external_fact_count > 0,
            "boundary_notes": boundary_notes,
        }

    @staticmethod
    def _message_delivery_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "requested_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "failure_code_counts": {},
                "message_kind_counts": {},
                "channel_counts": {},
                "latest_failure_code": "",
                "latest_message_kind": "",
                "latest_channel": "",
                "latest_stage": "",
                "latest_progress": 0,
            }
        requested_count = 0
        succeeded_count = 0
        failed_count = 0
        failure_code_counts: dict[str, int] = {}
        message_kind_counts: dict[str, int] = {}
        channel_counts: dict[str, int] = {}
        latest_failure_code = ""
        latest_message_kind = ""
        latest_channel = ""
        latest_stage = ""
        latest_progress = 0
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if not (
                event.endswith("_send_requested")
                or event.endswith("_send_succeeded")
                or event.endswith("_send_failed")
            ):
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            if event.endswith("_send_requested"):
                requested_count += 1
            elif event.endswith("_send_succeeded"):
                succeeded_count += 1
            elif event.endswith("_send_failed"):
                failed_count += 1
                failure_code = RuntimeEventValidator.safe_text(
                    payload.get("failure_code") or payload.get("error_code") or payload.get("reason") or ""
                ).strip()
                if not failure_code:
                    failure_code = "message_send_failed"
                failure_code = failure_code[:64]
                failure_code_counts[failure_code] = failure_code_counts.get(failure_code, 0) + 1
                latest_failure_code = failure_code
            message_kind = str(payload.get("message_kind") or "").strip()
            channel = str(payload.get("channel") or "").strip()
            if message_kind:
                message_kind_counts[message_kind] = message_kind_counts.get(message_kind, 0) + 1
                latest_message_kind = message_kind
            if channel:
                channel_counts[channel] = channel_counts.get(channel, 0) + 1
                latest_channel = channel
            latest_stage = str(payload.get("stage") or latest_stage)
            if isinstance(payload.get("progress"), (int, float)):
                latest_progress = int(payload.get("progress") or 0)
        return {
            "requested_count": requested_count,
            "succeeded_count": succeeded_count,
            "failed_count": failed_count,
            "failure_code_counts": dict(sorted(failure_code_counts.items())),
            "message_kind_counts": dict(sorted(message_kind_counts.items())),
            "channel_counts": dict(sorted(channel_counts.items())),
            "latest_failure_code": latest_failure_code,
            "latest_message_kind": latest_message_kind,
            "latest_channel": latest_channel,
            "latest_stage": latest_stage,
            "latest_progress": latest_progress,
        }

    @staticmethod
    def _planning_context_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "context_count": 0,
                "context_type_counts": {},
                "speaker_type_counts": {},
                "latest_context": [],
            }
        tracked = {
            "external_plan_context_synced",
            "agent_context_message_recorded",
            "room_agent_reply_recorded",
            "user_context_message_recorded",
            "room_chat_message_recorded",
        }
        context_type_counts: dict[str, int] = {}
        speaker_type_counts: dict[str, int] = {}
        latest_context: list[dict[str, Any]] = []
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if event not in tracked:
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            context_type = str(payload.get("context_type") or "").strip()
            speaker_type = str(payload.get("speaker_type") or "").strip()
            if not context_type:
                if event == "external_plan_context_synced":
                    context_type = "plan_context"
                elif event == "agent_context_message_recorded":
                    context_type = "agent_reply"
                elif event == "room_agent_reply_recorded":
                    context_type = "room_agent_reply"
                elif event == "user_context_message_recorded":
                    context_type = "user_discussion"
                elif event == "room_chat_message_recorded":
                    context_type = "room_chat"
                else:
                    context_type = "unknown"
            if not speaker_type:
                if event in {"agent_context_message_recorded", "room_agent_reply_recorded"}:
                    speaker_type = "agent"
                elif event in {"user_context_message_recorded", "room_chat_message_recorded"}:
                    speaker_type = "user"
                else:
                    speaker_type = "system"
            context_type_counts[context_type] = context_type_counts.get(context_type, 0) + 1
            speaker_type_counts[speaker_type] = speaker_type_counts.get(speaker_type, 0) + 1
            latest_context.append({
                "event": event,
                "context_type": context_type,
                "speaker_type": speaker_type,
                "agent_name": str(payload.get("agent_name") or ""),
                "message": str(entry.get("message") or "")[:160],
            })
        return {
            "context_count": len(latest_context),
            "context_type_counts": dict(sorted(context_type_counts.items())),
            "speaker_type_counts": dict(sorted(speaker_type_counts.items())),
            "latest_context": latest_context[-5:],
        }

    @staticmethod
    def _environment_component_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "ready_event_count": 0,
                "failed_event_count": 0,
                "import_event_count": 0,
                "import_failed_event_count": 0,
                "event_type_counts": {},
                "latest_event_type": "",
            }
        ready_event_count = 0
        failed_event_count = 0
        import_event_count = 0
        import_failed_event_count = 0
        event_type_counts: dict[str, int] = {}
        latest_event_type = ""
        tracked = {
            "environment_components_ready",
            "environment_components_failed",
            "environment_components_imported",
            "environment_components_import_failed",
        }
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            if str(entry.get("event") or "") != "runtime_event_emitted":
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            event_type = str(payload.get("event_type") or entry.get("message") or "").strip()
            if event_type not in tracked:
                continue
            event_type_counts[event_type] = event_type_counts.get(event_type, 0) + 1
            latest_event_type = event_type
            if event_type == "environment_components_ready":
                ready_event_count += 1
            elif event_type == "environment_components_failed":
                failed_event_count += 1
            elif event_type == "environment_components_imported":
                import_event_count += 1
            elif event_type == "environment_components_import_failed":
                import_failed_event_count += 1
        return {
            "ready_event_count": ready_event_count,
            "failed_event_count": failed_event_count,
            "import_event_count": import_event_count,
            "import_failed_event_count": import_failed_event_count,
            "event_type_counts": dict(sorted(event_type_counts.items())),
            "latest_event_type": latest_event_type,
        }

    def _state_sync_replay_entries(self, *, room_id: str, plan_id: str = "", batch_id: str = "") -> list[dict[str, Any]]:
        if not str(room_id or "").strip():
            return []
        room = self.state.room(str(room_id))
        active_plan_id = str(plan_id or "")
        active_batch_ids = self._batch_ids_for_plan(room, active_plan_id) if active_plan_id else set()
        entries: list[dict[str, Any]] = []
        for event in list(room.get("sync_events") or []):
            if not isinstance(event, Mapping):
                continue
            event_plan_id = str(event.get("plan_id") or "")
            event_batch_id = str(event.get("batch_id") or "")
            # LAN sync events are room-authoritative facts.  Older bridge events
            # may not carry Runtime plan ids, so plan-scoped operation replay can
            # still use batch-attributable entries as a supplement when the log
            # window is too small.  Unscoped room-level events are intentionally
            # excluded from plan replay because they cannot be proven to belong
            # to the requested plan.
            if active_plan_id:
                if event_plan_id:
                    if event_plan_id != active_plan_id:
                        continue
                elif event_batch_id:
                    if event_batch_id not in active_batch_ids:
                        continue
                else:
                    continue
            if batch_id and event_batch_id != str(batch_id):
                continue
            event_type = str(event.get("event_type") or "unknown")
            entries.append({
                "event": "sync_event_recorded",
                "message": event_type,
                "payload": dict(event),
            })
        return entries

    @staticmethod
    def _merge_sync_replay_summaries(primary: Mapping[str, Any], persisted: Mapping[str, Any]) -> dict[str, Any]:
        merged = dict(primary or {})
        count_keys = {
            "recorded_count",
            "failed_count",
            "actor_event_count",
            "actor_transform_count",
            "actor_delete_count",
            "asset_event_count",
            "peer_join_count",
            "peer_leave_count",
            "room_close_count",
            "transfer_failed_count",
            "transfer_progress_count",
        }
        for key in count_keys:
            merged[key] = max(int(merged.get(key) or 0), int(persisted.get(key) or 0))
        event_type_counts = dict(persisted.get("event_type_counts") or {})
        for key, value in dict(merged.get("event_type_counts") or {}).items():
            event_type_counts[str(key)] = max(int(event_type_counts.get(str(key)) or 0), int(value or 0))
        merged["event_type_counts"] = dict(sorted(event_type_counts.items()))
        failure_code_counts = dict(persisted.get("failure_code_counts") or {})
        for key, value in dict(merged.get("failure_code_counts") or {}).items():
            failure_code_counts[str(key)] = max(
                int(failure_code_counts.get(str(key)) or 0),
                int(value or 0),
            )
        merged["failure_code_counts"] = dict(sorted(failure_code_counts.items()))
        for key in (
            "latest_event_type",
            "latest_actor_event_type",
            "latest_peer_event_type",
            "latest_peer_id",
            "latest_room_status",
            "latest_failure_code",
        ):
            if not str(merged.get(key) or "").strip() and str(persisted.get(key) or "").strip():
                merged[key] = str(persisted.get(key) or "")
        for key in (
            "latest_transfer_progress",
            "latest_chunk_index",
            "latest_chunk_count",
            "latest_bytes_transferred",
            "latest_total_bytes",
        ):
            if not int(merged.get(key) or 0) and int(persisted.get(key) or 0):
                merged[key] = int(persisted.get(key) or 0)
        return merged

    @staticmethod
    def _sync_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "recorded_count": 0,
                "failed_count": 0,
                "actor_event_count": 0,
                "actor_transform_count": 0,
                "actor_delete_count": 0,
                "asset_event_count": 0,
                "peer_join_count": 0,
                "peer_leave_count": 0,
                "room_close_count": 0,
                "transfer_failed_count": 0,
                "transfer_progress_count": 0,
                "event_type_counts": {},
                "failure_code_counts": {},
                "latest_event_type": "",
                "latest_failure_code": "",
                "latest_actor_event_type": "",
                "latest_peer_event_type": "",
                "latest_peer_id": "",
                "latest_room_status": "",
                "latest_transfer_progress": 0,
                "latest_chunk_index": 0,
                "latest_chunk_count": 0,
                "latest_bytes_transferred": 0,
                "latest_total_bytes": 0,
            }
        recorded_count = 0
        failed_count = 0
        actor_event_count = 0
        actor_transform_count = 0
        actor_delete_count = 0
        asset_event_count = 0
        peer_join_count = 0
        peer_leave_count = 0
        room_close_count = 0
        transfer_failed_count = 0
        transfer_progress_count = 0
        event_type_counts: dict[str, int] = {}
        failure_code_counts: dict[str, int] = {}
        latest_event_type = ""
        latest_failure_code = ""
        latest_actor_event_type = ""
        latest_peer_event_type = ""
        latest_peer_id = ""
        latest_room_status = ""
        latest_transfer_progress = 0
        latest_chunk_index = 0
        latest_chunk_count = 0
        latest_bytes_transferred = 0
        latest_total_bytes = 0
        close_events = {"room_closed", "stop_room", "stopped", "closed"}
        peer_join_events = {"room_joined", "join_room", "joined"}
        peer_leave_events = {"leave_room", "left"}
        actor_transform_events = {
            "actor_transform",
            "actor_updated",
            "actor_moved",
            "actor_position",
            "actor_scaled",
            "actor_rotated",
        }
        actor_delete_events = {"actor_removed", "actor_deleted", "actor_destroyed", "actor_delete"}
        progress_events = {
            "asset_transfer_progress",
            "file_transfer_progress",
            "file_chunk",
            "file_chunk_received",
            "file_chunk_sent",
        }
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if event not in {"sync_event_recorded", "sync_event_record_failed"}:
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            event_type = str(payload.get("event_type") or entry.get("message") or "unknown").strip() or "unknown"
            event_type_counts[event_type] = event_type_counts.get(event_type, 0) + 1
            latest_event_type = event_type
            latest_room_status = str(payload.get("room_status") or latest_room_status)
            if event == "sync_event_recorded":
                recorded_count += 1
            else:
                failed_count += 1
                failure_code = RuntimeEventValidator.safe_text(
                    payload.get("failure_code")
                    or payload.get("error_code")
                    or payload.get("reason")
                    or ""
                ).strip()
                if not failure_code or failure_code == "[redacted]":
                    failure_code = "sync_event_record_failed"
                failure_code = failure_code[:64]
                failure_code_counts[failure_code] = failure_code_counts.get(failure_code, 0) + 1
                latest_failure_code = failure_code
            if str(payload.get("actor_id") or ""):
                actor_event_count += 1
                latest_actor_event_type = event_type
                if event_type in actor_transform_events:
                    actor_transform_count += 1
                if event_type in actor_delete_events:
                    actor_delete_count += 1
            if str(payload.get("asset_id") or ""):
                asset_event_count += 1
            if event_type in close_events:
                room_close_count += 1
            if event_type in peer_join_events:
                peer_join_count += 1
                latest_peer_event_type = event_type
                latest_peer_id = str(payload.get("peer_id") or latest_peer_id)
            if event_type in peer_leave_events:
                peer_leave_count += 1
                latest_peer_event_type = event_type
                latest_peer_id = str(payload.get("peer_id") or latest_peer_id)
            if str(payload.get("transfer_status") or "").lower() == "failed" or event_type in {
                "asset_transfer_failed",
                "file_transfer_failed",
            }:
                transfer_failed_count += 1
            if str(payload.get("transfer_status") or "").lower() == "transferring" or event_type in progress_events:
                transfer_progress_count += 1
                latest_transfer_progress = int(payload.get("progress") or latest_transfer_progress or 0)
                latest_chunk_index = int(payload.get("chunk_index") or latest_chunk_index or 0)
                latest_chunk_count = int(payload.get("chunk_count") or latest_chunk_count or 0)
                latest_bytes_transferred = int(payload.get("bytes_transferred") or latest_bytes_transferred or 0)
                latest_total_bytes = int(payload.get("total_bytes") or latest_total_bytes or 0)
        return {
            "recorded_count": recorded_count,
            "failed_count": failed_count,
            "actor_event_count": actor_event_count,
            "actor_transform_count": actor_transform_count,
            "actor_delete_count": actor_delete_count,
            "asset_event_count": asset_event_count,
            "peer_join_count": peer_join_count,
            "peer_leave_count": peer_leave_count,
            "room_close_count": room_close_count,
            "transfer_failed_count": transfer_failed_count,
            "transfer_progress_count": transfer_progress_count,
            "event_type_counts": dict(sorted(event_type_counts.items())),
            "failure_code_counts": dict(sorted(failure_code_counts.items())),
            "latest_event_type": latest_event_type,
            "latest_failure_code": latest_failure_code,
            "latest_actor_event_type": latest_actor_event_type,
            "latest_peer_event_type": latest_peer_event_type,
            "latest_peer_id": latest_peer_id,
            "latest_room_status": latest_room_status,
            "latest_transfer_progress": latest_transfer_progress,
            "latest_chunk_index": latest_chunk_index,
            "latest_chunk_count": latest_chunk_count,
            "latest_bytes_transferred": latest_bytes_transferred,
            "latest_total_bytes": latest_total_bytes,
        }

    @staticmethod
    def _asset_transfer_replay_summary(entries: Any) -> dict[str, Any]:
        default = {
            "asset_event_count": 0,
            "asset_transfer_started_count": 0,
            "asset_transfer_progress_count": 0,
            "asset_transfer_completed_count": 0,
            "asset_transfer_failed_count": 0,
            "peer_asset_ready_count": 0,
            "transfer_status_counts": {},
            "event_type_counts": {},
            "latest_asset_id": "",
            "latest_peer_id": "",
            "latest_transfer_status": "",
            "latest_transfer_progress": 0,
            "latest_chunk_index": 0,
            "latest_chunk_count": 0,
            "latest_bytes_transferred": 0,
            "latest_total_bytes": 0,
            "latest_transfer_event": {},
        }
        if not isinstance(entries, list):
            return default

        started_events = {
            "asset_transfer_started",
            "asset_requested",
            "file_request",
            "file_transfer_started",
        }
        progress_events = {
            "asset_transfer_progress",
            "file_transfer_progress",
            "file_chunk",
            "file_chunk_received",
            "file_chunk_sent",
        }
        completed_events = {
            "asset_transfer_completed",
            "asset_received",
            "file_transfer_completed",
        }
        failed_events = {"asset_transfer_failed", "file_transfer_failed"}
        peer_ready_events = {
            "peer_asset_ready",
            "asset_peer_ready",
            "asset_ready_for_peer",
            "peer_asset_received",
        }

        asset_event_count = 0
        started_count = 0
        progress_count = 0
        completed_count = 0
        failed_count = 0
        peer_ready_count = 0
        transfer_status_counts: dict[str, int] = {}
        event_type_counts: dict[str, int] = {}
        latest_asset_id = ""
        latest_peer_id = ""
        latest_transfer_status = ""
        latest_transfer_progress = 0
        latest_chunk_index = 0
        latest_chunk_count = 0
        latest_bytes_transferred = 0
        latest_total_bytes = 0
        latest_transfer_event: dict[str, Any] = {}
        seen_events: set[tuple[str, str, str, str, str, str]] = set()

        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            if event not in {"sync_event_recorded", "sync_event_record_failed"}:
                continue
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            event_type = str(payload.get("event_type") or entry.get("message") or "unknown").strip() or "unknown"
            asset_id = str(payload.get("asset_id") or "")
            peer_id = str(payload.get("peer_id") or "")
            if not asset_id and event_type not in peer_ready_events:
                continue

            dedupe_key = (
                event,
                event_type,
                asset_id,
                peer_id,
                str(payload.get("batch_id") or entry.get("batch_id") or ""),
                f"{int(payload.get('progress') or 0)}:{int(payload.get('chunk_index') or 0)}",
            )
            if dedupe_key in seen_events:
                continue
            seen_events.add(dedupe_key)

            asset_event_count += 1
            event_type_counts[event_type] = event_type_counts.get(event_type, 0) + 1
            transfer_status = str(payload.get("transfer_status") or payload.get("status") or "").strip()
            if not transfer_status:
                if event_type in completed_events or event_type in peer_ready_events:
                    transfer_status = "completed"
                elif event_type in failed_events or event == "sync_event_record_failed":
                    transfer_status = "failed"
                elif event_type in started_events or event_type in progress_events:
                    transfer_status = "transferring"
            if transfer_status:
                transfer_status_counts[transfer_status] = transfer_status_counts.get(transfer_status, 0) + 1

            if event_type in started_events:
                started_count += 1
            if event_type in progress_events:
                progress_count += 1
            if transfer_status == "completed" or event_type in completed_events:
                completed_count += 1
            if transfer_status == "failed" or event_type in failed_events or event == "sync_event_record_failed":
                failed_count += 1
            if event_type in peer_ready_events:
                peer_ready_count += 1

            latest_asset_id = asset_id or latest_asset_id
            latest_peer_id = peer_id or latest_peer_id
            latest_transfer_status = transfer_status or latest_transfer_status
            latest_transfer_progress = int(payload.get("progress") or latest_transfer_progress or 0)
            latest_chunk_index = int(payload.get("chunk_index") or latest_chunk_index or 0)
            latest_chunk_count = int(payload.get("chunk_count") or latest_chunk_count or 0)
            latest_bytes_transferred = int(payload.get("bytes_transferred") or latest_bytes_transferred or 0)
            latest_total_bytes = int(payload.get("total_bytes") or latest_total_bytes or 0)
            latest_transfer_event = {
                "event_type": event_type,
                "asset_id": latest_asset_id,
                "peer_id": latest_peer_id,
                "transfer_status": latest_transfer_status,
                "progress": latest_transfer_progress,
                "chunk_index": latest_chunk_index,
                "chunk_count": latest_chunk_count,
            }

        return {
            "asset_event_count": asset_event_count,
            "asset_transfer_started_count": started_count,
            "asset_transfer_progress_count": progress_count,
            "asset_transfer_completed_count": completed_count,
            "asset_transfer_failed_count": failed_count,
            "peer_asset_ready_count": peer_ready_count,
            "transfer_status_counts": dict(sorted(transfer_status_counts.items())),
            "event_type_counts": dict(sorted(event_type_counts.items())),
            "latest_asset_id": latest_asset_id,
            "latest_peer_id": latest_peer_id,
            "latest_transfer_status": latest_transfer_status,
            "latest_transfer_progress": latest_transfer_progress,
            "latest_chunk_index": latest_chunk_index,
            "latest_chunk_count": latest_chunk_count,
            "latest_bytes_transferred": latest_bytes_transferred,
            "latest_total_bytes": latest_total_bytes,
            "latest_transfer_event": latest_transfer_event,
        }

    @staticmethod
    def _peer_sync_replay_summary(entries: Any) -> dict[str, Any]:
        default = {
            "peer_event_count": 0,
            "peer_join_count": 0,
            "peer_leave_count": 0,
            "room_close_count": 0,
            "sync_reconcile_count": 0,
            "sync_reconcile_failed_count": 0,
            "state_reconcile_count": 0,
            "state_reconcile_failed_count": 0,
            "event_type_counts": {},
            "latest_peer_id": "",
            "latest_peer_event_type": "",
            "latest_room_status": "",
            "latest_reconcile_event": {},
        }
        if not isinstance(entries, list):
            return default

        peer_join_events = {"room_created", "room_joined", "join_room", "joined", "started"}
        peer_leave_events = {"leave_room", "left"}
        room_close_events = {"room_closed", "stop_room", "stopped", "closed"}
        sync_reconcile_events = {
            "sync_reconcile",
            "sync_reconcile_started",
            "sync_reconcile_completed",
            "sync_state_reconciled",
            "peer_state_reconciled",
            "remote_state_reconciled",
        }
        sync_reconcile_failed_events = {
            "sync_reconcile_failed",
            "sync_state_reconcile_failed",
            "peer_state_reconcile_failed",
            "remote_state_reconcile_failed",
        }
        state_reconcile_events = {"state_patch_conflict_reconciled"}
        state_reconcile_failed_events = {
            "state_patch_conflict_reconcile_rejected",
            "state_patch_conflict_reconcile_missing",
            "state_patch_conflict_reconcile_failed",
        }

        peer_event_count = 0
        peer_join_count = 0
        peer_leave_count = 0
        room_close_count = 0
        sync_reconcile_count = 0
        sync_reconcile_failed_count = 0
        state_reconcile_count = 0
        state_reconcile_failed_count = 0
        event_type_counts: dict[str, int] = {}
        latest_peer_id = ""
        latest_peer_event_type = ""
        latest_room_status = ""
        latest_reconcile_event: dict[str, Any] = {}
        seen_events: set[tuple[str, str, str, str, str]] = set()

        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
                message = str(entry.message or "")
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
                message = str(entry.get("message") or "")
            else:
                continue

            event_type = str(payload.get("event_type") or message or event or "unknown").strip() or "unknown"
            peer_id = str(payload.get("peer_id") or payload.get("sender_id") or "")
            room_status = str(payload.get("room_status") or "")
            dedupe_key = (
                event,
                event_type,
                peer_id,
                str(payload.get("batch_id") or ""),
                str(payload.get("status") or payload.get("decision") or ""),
            )
            if dedupe_key in seen_events:
                continue
            seen_events.add(dedupe_key)

            is_sync_event = event in {"sync_event_recorded", "sync_event_record_failed"}
            is_peer_event = event_type in peer_join_events or event_type in peer_leave_events or bool(peer_id)
            is_room_event = event_type in room_close_events
            is_sync_reconcile = event_type in sync_reconcile_events
            is_sync_reconcile_failed = event_type in sync_reconcile_failed_events
            is_state_reconcile = event in state_reconcile_events
            is_state_reconcile_failed = event in state_reconcile_failed_events
            if not (
                is_sync_event
                and (is_peer_event or is_room_event or is_sync_reconcile or is_sync_reconcile_failed)
                or is_state_reconcile
                or is_state_reconcile_failed
            ):
                continue

            event_type_counts[event_type] = event_type_counts.get(event_type, 0) + 1
            if room_status:
                latest_room_status = room_status
            if event_type in peer_join_events:
                peer_join_count += 1
                peer_event_count += 1
                latest_peer_event_type = event_type
                latest_peer_id = peer_id or latest_peer_id
            elif event_type in peer_leave_events:
                peer_leave_count += 1
                peer_event_count += 1
                latest_peer_event_type = event_type
                latest_peer_id = peer_id or latest_peer_id
            elif peer_id and is_sync_event:
                peer_event_count += 1
                latest_peer_event_type = event_type
                latest_peer_id = peer_id
            if event_type in room_close_events:
                room_close_count += 1
                latest_room_status = room_status or "closed"
            if is_sync_reconcile:
                sync_reconcile_count += 1
                latest_reconcile_event = {
                    "event": event,
                    "event_type": event_type,
                    "status": str(payload.get("status") or payload.get("decision") or ""),
                    "recorded": bool(payload.get("recorded") if "recorded" in payload else event == "sync_event_recorded"),
                }
            if is_sync_reconcile_failed or event == "sync_event_record_failed" and is_sync_reconcile:
                sync_reconcile_failed_count += 1
                latest_reconcile_event = {
                    "event": event,
                    "event_type": event_type,
                    "status": "failed",
                    "recorded": False,
                }
            if is_state_reconcile:
                state_reconcile_count += 1
                latest_reconcile_event = {
                    "event": event,
                    "event_type": event_type,
                    "status": str(payload.get("decision") or payload.get("status") or "reconciled"),
                    "recorded": bool(payload.get("recorded")),
                }
            if is_state_reconcile_failed:
                state_reconcile_failed_count += 1
                latest_reconcile_event = {
                    "event": event,
                    "event_type": event_type,
                    "status": str(payload.get("decision") or payload.get("status") or "failed"),
                    "recorded": bool(payload.get("recorded")),
                }

        return {
            "peer_event_count": peer_event_count,
            "peer_join_count": peer_join_count,
            "peer_leave_count": peer_leave_count,
            "room_close_count": room_close_count,
            "sync_reconcile_count": sync_reconcile_count,
            "sync_reconcile_failed_count": sync_reconcile_failed_count,
            "state_reconcile_count": state_reconcile_count,
            "state_reconcile_failed_count": state_reconcile_failed_count,
            "event_type_counts": dict(sorted(event_type_counts.items())),
            "latest_peer_id": latest_peer_id,
            "latest_peer_event_type": latest_peer_event_type,
            "latest_room_status": latest_room_status,
            "latest_reconcile_event": latest_reconcile_event,
        }

    @staticmethod
    def _layout_adjustment_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "request_count": 0,
                "request_failed_count": 0,
                "confirmation_count": 0,
                "confirmation_failed_count": 0,
                "applied_count": 0,
                "skipped_count": 0,
                "transform_result_count": 0,
                "transform_success_count": 0,
                "transform_failed_count": 0,
                "ground_snapped_count": 0,
                "overlap_resolved_count": 0,
                "layout_transform_failure_code_counts": {},
                "proposal_status_counts": {},
                "pending_proposal_count": 0,
                "confirmed_proposal_count": 0,
                "failed_proposal_count": 0,
                "delta_count": 0,
                "latest_proposal_id": "",
                "latest_graph_status": "",
            }
        request_count = 0
        request_failed_count = 0
        confirmation_count = 0
        confirmation_failed_count = 0
        applied_count = 0
        skipped_count = 0
        transform_result_count = 0
        transform_success_count = 0
        transform_failed_count = 0
        ground_snapped_count = 0
        overlap_resolved_count = 0
        transform_failure_code_counts: dict[str, int] = {}
        delta_count = 0
        proposal_status_by_id: dict[str, str] = {}
        latest_proposal_id = ""
        latest_graph_status = ""
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            if event == "layout_adjustment_requested":
                request_count += 1
                latest_proposal_id = str(payload.get("proposal_id") or latest_proposal_id)
                if latest_proposal_id:
                    proposal_status_by_id[latest_proposal_id] = "proposed"
                delta_count += int(payload.get("delta_count") or 0)
            elif event == "layout_adjustment_request_failed":
                request_failed_count += 1
            elif event == "layout_adjustment_confirmed":
                confirmation_count += 1
                latest_proposal_id = str(payload.get("proposal_id") or latest_proposal_id)
                latest_graph_status = str(payload.get("graph_status") or latest_graph_status)
                if latest_proposal_id:
                    proposal_status_by_id[latest_proposal_id] = "confirmed"
                applied_count += int(payload.get("applied_count") or 0)
                skipped_count += int(payload.get("skipped_count") or 0)
                transform_result_count += int(payload.get("transform_result_count") or 0)
                transform_success_count += int(payload.get("transform_success_count") or 0)
                transform_failed_count += int(payload.get("transform_failed_count") or 0)
                ground_snapped_count += int(payload.get("ground_snapped_count") or 0)
                overlap_resolved_count += int(payload.get("overlap_resolved_count") or 0)
                for key, value in dict(
                    payload.get("layout_transform_failure_code_counts") or {}
                ).items():
                    code = str(key or "").strip()
                    if not code:
                        continue
                    transform_failure_code_counts[code] = (
                        transform_failure_code_counts.get(code, 0) + int(value or 0)
                    )
            elif event == "layout_adjustment_confirm_failed":
                confirmation_failed_count += 1
                latest_proposal_id = str(payload.get("proposal_id") or latest_proposal_id)
                latest_graph_status = str(payload.get("graph_status") or latest_graph_status)
                if latest_proposal_id:
                    proposal_status_by_id[latest_proposal_id] = "failed"
        proposal_status_counts: dict[str, int] = {}
        for status in proposal_status_by_id.values():
            proposal_status_counts[status] = proposal_status_counts.get(status, 0) + 1
        return {
            "request_count": request_count,
            "request_failed_count": request_failed_count,
            "confirmation_count": confirmation_count,
            "confirmation_failed_count": confirmation_failed_count,
            "applied_count": applied_count,
            "skipped_count": skipped_count,
            "transform_result_count": transform_result_count,
            "transform_success_count": transform_success_count,
            "transform_failed_count": transform_failed_count,
            "ground_snapped_count": ground_snapped_count,
            "overlap_resolved_count": overlap_resolved_count,
            "layout_transform_failure_code_counts": dict(
                sorted(transform_failure_code_counts.items())
            ),
            "proposal_status_counts": dict(sorted(proposal_status_counts.items())),
            "pending_proposal_count": int(proposal_status_counts.get("proposed") or 0),
            "confirmed_proposal_count": int(proposal_status_counts.get("confirmed") or 0),
            "failed_proposal_count": int(proposal_status_counts.get("failed") or 0),
            "delta_count": delta_count,
            "latest_proposal_id": latest_proposal_id,
            "latest_graph_status": latest_graph_status,
        }

    @staticmethod
    def _vlm_checkpoint_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "checkpoint_count": 0,
                "advisory_count": 0,
                "status_counts": {},
                "checkpoint_counts": {},
                "latest_checkpoints": [],
            }
        status_counts: dict[str, int] = {}
        checkpoint_counts: dict[str, int] = {}
        latest_checkpoints: list[dict[str, Any]] = []
        advisory_count = 0
        for entry in entries:
            if isinstance(entry, OperationLogEntry):
                event = str(entry.event or "")
                payload = entry.payload if isinstance(entry.payload, Mapping) else {}
                entry_batch_id = str(entry.batch_id or "")
            elif isinstance(entry, Mapping):
                event = str(entry.get("event") or "")
                payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
                entry_batch_id = str(entry.get("batch_id") or "")
            else:
                continue
            if event != "tool_call_succeeded" or str(payload.get("source") or "") != "runtime_vlm_checkpoint":
                continue
            status = str(payload.get("status") or "unknown").strip() or "unknown"
            checkpoint_type = str(payload.get("checkpoint_type") or "vlm_checkpoint").strip() or "vlm_checkpoint"
            reviewed_targets = [
                str(item or "").strip()
                for item in (payload.get("reviewed_targets") or [])
                if str(item or "").strip()
            ][:6]
            item_count = int(payload.get("advisory_item_count") or 0)
            status_counts[status] = status_counts.get(status, 0) + 1
            checkpoint_counts[checkpoint_type] = checkpoint_counts.get(checkpoint_type, 0) + 1
            advisory_count += item_count
            latest_checkpoints.append(
                {
                    "batch_id": entry_batch_id,
                    "checkpoint_type": checkpoint_type,
                    "status": status,
                    "overall": str(payload.get("overall") or ""),
                    "advisory_count": item_count,
                    "reviewed_targets": reviewed_targets,
                }
            )
        return {
            "checkpoint_count": len(latest_checkpoints),
            "advisory_count": advisory_count,
            "status_counts": dict(sorted(status_counts.items())),
            "checkpoint_counts": dict(sorted(checkpoint_counts.items())),
            "latest_checkpoints": latest_checkpoints[-5:],
        }

    @staticmethod
    def _review_advisory_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "proposal_created_count": 0,
                "confirmation_count": 0,
                "decision_counts": {},
                "proposal_status_counts": {},
                "pending_proposal_count": 0,
                "confirmed_proposal_count": 0,
                "rejected_proposal_count": 0,
                "advisory_item_count": 0,
                "latest_decision": "",
                "latest_proposal_id": "",
            }
        proposal_created_count = 0
        confirmation_count = 0
        advisory_item_count = 0
        decision_counts: dict[str, int] = {}
        proposal_status_by_id: dict[str, str] = {}
        latest_decision = ""
        latest_proposal_id = ""
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            if event == "review_advisory_proposal_created":
                proposal_created_count += 1
                latest_proposal_id = str(payload.get("proposal_id") or latest_proposal_id)
                if latest_proposal_id:
                    proposal_status_by_id[latest_proposal_id] = "proposed"
                advisory_item_count += int(payload.get("item_count") or 0)
            elif event == "review_advisory_confirmation_recorded":
                confirmation_count += 1
                decision = str(payload.get("decision") or entry.get("message") or "unknown").strip() or "unknown"
                decision_counts[decision] = decision_counts.get(decision, 0) + 1
                latest_decision = decision
                latest_proposal_id = str(payload.get("proposal_id") or latest_proposal_id)
                if latest_proposal_id:
                    proposal_status_by_id[latest_proposal_id] = decision
        proposal_status_counts: dict[str, int] = {}
        for status in proposal_status_by_id.values():
            proposal_status_counts[status] = proposal_status_counts.get(status, 0) + 1
        return {
            "proposal_created_count": proposal_created_count,
            "confirmation_count": confirmation_count,
            "decision_counts": dict(sorted(decision_counts.items())),
            "proposal_status_counts": dict(sorted(proposal_status_counts.items())),
            "pending_proposal_count": int(proposal_status_counts.get("proposed") or 0),
            "confirmed_proposal_count": int(proposal_status_counts.get("confirmed") or 0),
            "rejected_proposal_count": int(proposal_status_counts.get("rejected") or 0),
            "advisory_item_count": advisory_item_count,
            "latest_decision": latest_decision,
            "latest_proposal_id": latest_proposal_id,
        }

    @staticmethod
    def _final_adjustment_confirmation_replay_summary(entries: Any) -> dict[str, Any]:
        if not isinstance(entries, list):
            return {
                "confirmation_count": 0,
                "confirmation_failed_count": 0,
                "confirmation_skipped_count": 0,
                "decision_counts": {},
                "latest_confirmation": {},
            }
        confirmation_count = 0
        confirmation_failed_count = 0
        confirmation_skipped_count = 0
        decision_counts: dict[str, int] = {}
        latest_confirmation: dict[str, Any] = {}
        for entry in entries:
            if not isinstance(entry, Mapping):
                continue
            event = str(entry.get("event") or "")
            payload = entry.get("payload") if isinstance(entry.get("payload"), Mapping) else {}
            if event == "final_adjustment_confirmation_recorded":
                confirmation_count += 1
                decision = str(payload.get("decision") or entry.get("message") or "unknown").strip() or "unknown"
                decision_counts[decision] = decision_counts.get(decision, 0) + 1
                latest_confirmation = {
                    "proposal_id": str(payload.get("proposal_id") or ""),
                    "batch_id": str(payload.get("batch_id") or entry.get("batch_id") or ""),
                    "decision": decision,
                    "confirmed_by": str(payload.get("confirmed_by") or ""),
                    "target_hint": str(payload.get("target_hint") or ""),
                    "conflict_item_count": int(payload.get("conflict_item_count") or 0),
                }
            elif event == "final_adjustment_confirmation_record_failed":
                confirmation_failed_count += 1
            elif event == "final_adjustment_confirmation_skipped":
                confirmation_skipped_count += 1
        return {
            "confirmation_count": confirmation_count,
            "confirmation_failed_count": confirmation_failed_count,
            "confirmation_skipped_count": confirmation_skipped_count,
            "decision_counts": dict(sorted(decision_counts.items())),
            "latest_confirmation": latest_confirmation,
        }

    def record_sync_event(
        self,
        *,
        room_id: str,
        event: dict[str, Any],
        source: str = "lanchat",
    ) -> dict[str, Any]:
        """Mirror external LANChat / engine sync facts into RuntimeState.

        RuntimeState does not own the C++ network truth.  This method records a
        sanitized business view of that truth so GM/status/reporting can reason
        from one state source without taking over the underlying sync protocol.
        """

        if not isinstance(event, dict):
            normalized = {
                "event_type": "invalid",
                "room_id": str(room_id or ""),
                "source": str(source or ""),
                "timestamp": _now(),
                "reason": "event is not a dict",
            }
        else:
            room = str(room_id or event.get("room_id") or event.get("room") or "default")
            incoming_actor_version = self._sync_non_negative_int_from_event(
                event,
                ("actor_version", "entity_version", "version"),
            )
            incoming_scene_version = self._sync_non_negative_int_from_event(
                event,
                ("scene_version", "plan_version", "source_scene_version"),
            )
            event_type = self._canonical_sync_event_type(
                str(event.get("event") or event.get("event_type") or event.get("type") or "").strip().lower()
                or "unknown"
            )
            actor_id = str(
                event.get("actor_id")
                or event.get("actor_guid")
                or event.get("actor")
                or event.get("guid")
                or ""
            )
            asset_id = str(event.get("asset_id") or event.get("asset") or event.get("file_id") or "")
            actor_asset_id = str(
                event.get("actor_asset_id")
                or event.get("model_asset_id")
                or event.get("model_resource_id")
                or ""
            )
            normalized = {
                "event_type": event_type,
                "room_id": room,
                "source": str(source or event.get("source") or "lanchat"),
                "timestamp": event.get("timestamp") or event.get("time") or _now(),
                "message_id": str(event.get("message_id") or event.get("id") or ""),
                "correlation_id": str(event.get("correlation_id") or ""),
                "sender_id": str(event.get("sender_id") or event.get("from") or ""),
                "sender_name": str(event.get("sender_name") or ""),
                "peer_id": str(event.get("peer_id") or event.get("peer") or ""),
                "plan_id": str(event.get("plan_id") or event.get("runtime_plan_id") or ""),
                "external_plan_id": str(event.get("external_plan_id") or event.get("seed_plan_id") or ""),
                "batch_id": str(event.get("batch_id") or event.get("runtime_batch_id") or ""),
                "actor_id": actor_id,
                "actor_name": str(event.get("actor_name") or event.get("name") or ""),
                "entity_id": str(event.get("entity_id") or event.get("runtime_entity_id") or ""),
                "entity_type": str(event.get("entity_type") or ""),
                "semantic_role": str(event.get("semantic_role") or ""),
                "grounding_status": str(event.get("grounding_status") or ""),
                "model_ref": str(event.get("model_ref") or event.get("model") or event.get("path") or ""),
                "actor_version": max(
                    1,
                    incoming_actor_version or 1,
                ),
                "actor_version_explicit": incoming_actor_version is not None,
                "scene_version": max(
                    1,
                    incoming_scene_version or 1,
                ),
                "scene_version_explicit": incoming_scene_version is not None,
                "authority": str(event.get("authority") or ""),
                "snapshot_kind": str(event.get("snapshot_kind") or ""),
                "identity_fingerprint": str(event.get("identity_fingerprint") or ""),
                "host_identity_fingerprint": str(event.get("host_identity_fingerprint") or ""),
                "peer_identity_fingerprint": str(event.get("peer_identity_fingerprint") or ""),
                "missing_fields_explicit": bool(event.get("missing_fields_explicit", False)),
                "asset_id": asset_id,
                "actor_asset_id": actor_asset_id,
                "asset_path": str(event.get("asset_path") or event.get("model_path") or event.get("path") or ""),
                "status": str(event.get("status") or ""),
                "scene_name": str(event.get("scene_name") or event.get("scene") or event.get("scene_path") or ""),
            }
            position = self._sync_vector3(
                event.get("position")
                or event.get("pos")
                or event.get("location")
                or event.get("translation")
            )
            if position is None and any(key in event for key in ("x", "y", "z")):
                position = self._sync_vector3({"x": event.get("x"), "y": event.get("y"), "z": event.get("z")})
            rotation = self._sync_vector3(event.get("rotation") or event.get("rot") or event.get("euler"))
            scale = self._sync_vector3(event.get("scale") or event.get("size"))
            if position is not None:
                normalized["position"] = position
            if rotation is not None:
                normalized["rotation"] = rotation
            if scale is not None:
                normalized["scale"] = scale
            event_bounds = ActorFactValidator._safe_aabb_bounds(
                event.get("aabb")
                or event.get("bounds")
                or event.get("scene_aabb")
                or event.get("world_aabb")
                or event.get("world_bounds")
            )
            for target_key, candidates in {
                "entity_count": ("entity_count", "host_entity_count"),
                "applied_entity_count": ("applied_entity_count", "peer_entity_count"),
                "partial_entity_count": ("partial_entity_count", "missing_entity_count"),
                "identity_drift_count": ("identity_drift_count",),
                "version_drift_count": ("version_drift_count",),
                "chunk_index": ("chunk_index", "chunk", "chunk_id", "chunk_no", "chunk_number"),
                "chunk_count": ("chunk_count", "total_chunks", "chunk_total"),
                "bytes_transferred": ("bytes_transferred", "transferred_bytes", "bytes_sent", "received_bytes"),
                "total_bytes": ("total_bytes", "file_size", "size_bytes"),
                "progress": ("progress", "percent", "percentage"),
            }.items():
                numeric_value = self._sync_non_negative_int_from_event(event, candidates)
                if numeric_value is not None:
                    normalized[target_key] = numeric_value
            room_id = room
        if not isinstance(event, dict):
            event_bounds = None

        room_key = str(room_id or normalized.get("room_id") or "default")
        room_state = self.state.room(room_key)
        active_plan_id = str(
            room_state.get("active_execution_plan_id")
            or room_state.get("latest_completed_plan_id")
            or room_state.get("peer_mirror_plan_id")
            or room_state.get("active_discussion_plan_id")
            or room_state.get("active_plan_id")
            or ""
        )
        explicit_batch_id = str(normalized.get("batch_id") or "")
        explicit_plan_id = str(normalized.get("plan_id") or "")
        explicit_external_plan_id = str(normalized.pop("external_plan_id", "") or "")

        def skip_sync_event(reason_text: str) -> dict[str, Any]:
            stored_event = SyncEventValidator.safe_storage_event(normalized)
            self.operation_log.append(
                "sync_event_record_skipped",
                room_id=room_key,
                message=str(stored_event.get("event_type") or ""),
                payload={
                    "applied": False,
                    "reason": reason_text,
                    "event_type": str(stored_event.get("event_type") or ""),
                    "source": str(stored_event.get("source") or ""),
                    "actor_id": str(stored_event.get("actor_id") or ""),
                    "asset_id": str(stored_event.get("asset_id") or ""),
                    "batch_id": str(stored_event.get("batch_id") or ""),
                    "status": str(stored_event.get("status") or ""),
                },
            )
            return {
                "recorded": False,
                "reason": reason_text,
                "event": self._safe_sync_event_summary(normalized),
                "sync_state": self._safe_sync_state_summary(
                    dict(self.state.room(room_key).get("sync_state") or {})
                ),
            }

        peer_mirror_event = False
        if explicit_plan_id:
            requested_sync_plan_id = explicit_plan_id
            explicit_plan_id = self._resolve_runtime_plan_id_from_state(
                room_key,
                plan_id=explicit_plan_id,
                allow_active=False,
            )
            if not explicit_plan_id:
                is_remote_host_fact = str(normalized.get("authority") or "").strip().lower() == "remote_host"
                is_scene_fact = bool(
                    normalized.get("actor_id")
                    or normalized.get("asset_id")
                    or normalized.get("event_type") == "scene_snapshot_received"
                )
                if is_remote_host_fact and is_scene_fact:
                    explicit_plan_id = requested_sync_plan_id
                    current_peer_plan_id = str(room_state.get("peer_mirror_plan_id") or "").strip()
                    peer_mirror_event = (
                        normalized.get("event_type") == "scene_snapshot_received"
                        or not current_peer_plan_id
                        or current_peer_plan_id == requested_sync_plan_id
                    )
                else:
                    return skip_sync_event("no runtime plan")
        if not explicit_plan_id and explicit_external_plan_id:
            explicit_plan_id = self._resolve_runtime_plan_id_from_state(
                room_key,
                external_plan_id=explicit_external_plan_id,
                allow_active=False,
            )
            if not explicit_plan_id:
                return skip_sync_event("no runtime plan")
        if not explicit_plan_id and explicit_batch_id:
            batch_plan = self._batch_plan_for_batch_id(room_state, explicit_batch_id)
            explicit_plan_id = str(batch_plan.get("plan_id") or "")
            if not explicit_plan_id:
                return skip_sync_event("no runtime batch")
        scene_name = str(normalized.get("scene_name") or "")
        effective_plan_id = explicit_plan_id or active_plan_id
        if effective_plan_id:
            normalized["plan_id"] = effective_plan_id
        if not scene_name:
            plan_data = dict((room_state.get("scene_plans") or {}).get(effective_plan_id) or {})
            scene_name = str(plan_data.get("scene_name") or "")
        if scene_name:
            normalized["scene_name"] = scene_name
        current_peer_plan_id = str(room_state.get("peer_mirror_plan_id") or "").strip()
        if (
            bool(normalized.get("scene_version_explicit"))
            and str(normalized.get("authority") or "").strip().lower() == "remote_host"
            and effective_plan_id
            and effective_plan_id == current_peer_plan_id
        ):
            mirror_versions = dict(room_state.get("peer_mirror_scene_versions") or {})
            current_scene_version = int(mirror_versions.get(effective_plan_id) or 0)
            incoming_version = int(normalized.get("scene_version") or 1)
            if current_scene_version > 0 and incoming_version < current_scene_version:
                return skip_sync_event("stale scene version")
        actor_id_for_version_check = str(normalized.get("actor_id") or "")
        if actor_id_for_version_check and bool(normalized.get("actor_version_explicit")):
            current_actor_fact = dict(
                dict(room_state.get("actors") or {}).get(actor_id_for_version_check) or {}
            )
            try:
                current_actor_version = int(
                    current_actor_fact.get("actor_version")
                    or current_actor_fact.get("version")
                    or 0
                )
            except (TypeError, ValueError):
                current_actor_version = 0
            incoming_version = int(normalized.get("actor_version") or 1)
            if current_actor_version > 0 and incoming_version < current_actor_version:
                return skip_sync_event("stale actor version")
        stored_event = SyncEventValidator.safe_storage_event(normalized)
        existing_sync_state = dict(room_state.get("sync_state") or {})
        existing_events = list(room_state.get("sync_events") or [])
        sync_state = {
            "event_count": int(existing_sync_state.get("event_count") or len(existing_events)) + 1,
            "room_status": str(existing_sync_state.get("room_status") or "active"),
            "last_event": dict(stored_event),
            "peer_events": dict(existing_sync_state.get("peer_events") or {}),
            "actor_events": dict(existing_sync_state.get("actor_events") or {}),
            "asset_events": dict(existing_sync_state.get("asset_events") or {}),
        }
        event_type = str(normalized.get("event_type") or "")
        close_events = {"room_closed", "stop_room", "stopped", "closed"}
        join_events = {"room_created", "room_joined", "join_room", "joined", "started"}
        if event_type in close_events:
            sync_state["room_status"] = "closed"
            sync_state["closed_at"] = normalized.get("timestamp")
        elif event_type in join_events:
            sync_state["room_status"] = "active"
        peer_id = str(normalized.get("peer_id") or normalized.get("sender_id") or "")
        if peer_id:
            sync_state["peer_events"][peer_id] = dict(stored_event)
        actor_id = str(normalized.get("actor_id") or "")
        affected_batch_id = explicit_batch_id
        if actor_id:
            sync_state["actor_events"][actor_id] = dict(stored_event)
            actors = dict(room_state.get("actors") or {})
            actor_fact = dict(actors.get(actor_id) or {})
            actor_fact.update({
                "actor_id": actor_id,
                "name": str(normalized.get("actor_name") or actor_fact.get("name") or actor_id),
                "plan_id": str(normalized.get("plan_id") or actor_fact.get("plan_id") or ""),
                "batch_id": str(normalized.get("batch_id") or actor_fact.get("batch_id") or ""),
                "last_sync_event": event_type,
                "last_sync_status": str(normalized.get("status") or actor_fact.get("last_sync_status") or ""),
                "last_sync_timestamp": normalized.get("timestamp"),
            })
            for fact_key in (
                "entity_id",
                "entity_type",
                "semantic_role",
                "grounding_status",
                "model_ref",
            ):
                fact_value = normalized.get(fact_key)
                if fact_value not in (None, ""):
                    actor_fact[fact_key] = fact_value
            try:
                current_actor_version = int(actor_fact.get("actor_version") or actor_fact.get("version") or 1)
            except (TypeError, ValueError):
                current_actor_version = 1
            actor_fact["actor_version"] = max(current_actor_version, int(normalized.get("actor_version") or 1))
            actor_fact["version"] = actor_fact["actor_version"]
            actor_asset_id = str(normalized.get("actor_asset_id") or asset_id or "")
            if actor_asset_id:
                actor_fact["asset_id"] = actor_asset_id
            if scene_name:
                actor_fact["scene_name"] = scene_name
            sync_authority = str(normalized.get("authority") or "").strip().lower()
            remote_bounds_source = (
                "remote_host_actual"
                if sync_authority == "remote_host"
                else "remote_peer_actual"
                if sync_authority == "remote_peer"
                else ""
            )
            if event_bounds is not None:
                actor_fact["aabb"] = event_bounds
                if remote_bounds_source:
                    # A host/peer AABB is authoritative for the shared world, but
                    # it does not prove that this process has materialized the
                    # actor in its own GeometrySystem.  Only a local scene
                    # snapshot may promote this fact to engine_actual.
                    actor_fact["bounds_ready"] = False
                    actor_fact["bounds_source"] = remote_bounds_source
                    actor_fact["status"] = "sync_received"
                else:
                    actor_fact["bounds_ready"] = True
                    actor_fact["bounds_source"] = "engine_actual"
                    actor_fact["engine_lifecycle_status"] = "bounds_ready"
                    actor_fact["status"] = "ready"
                if sync_authority == "remote_host":
                    actor_fact["sync_status"] = "synced"
            affected_batch_id = str(actor_fact.get("batch_id") or affected_batch_id)
            transform_events = {
                "actor_transform",
                "actor_updated",
                "actor_moved",
                "actor_position",
                "actor_scaled",
                "actor_rotated",
            }
            create_events = {
                "actor_created",
                "actor_added",
                "actor_imported",
            }
            if event_type in transform_events or any(key in normalized for key in ("position", "rotation", "scale")):
                if isinstance(normalized.get("position"), list):
                    actor_fact["position"] = list(normalized["position"])
                if isinstance(normalized.get("rotation"), list):
                    actor_fact["rotation"] = list(normalized["rotation"])
                if isinstance(normalized.get("scale"), list):
                    actor_fact["scale"] = list(normalized["scale"])
                actor_fact["sync_lifecycle_status"] = "active"
            elif event_type in create_events:
                actor_fact["sync_lifecycle_status"] = "active"
                if event_type == "actor_imported":
                    # register_actor_identity proves local import, not local
                    # geometry/AABB readiness.  A later engine snapshot performs
                    # the bounds_ready promotion.
                    actor_fact["engine_lifecycle_status"] = "engine_imported"
                    actor_fact["sync_status"] = "engine_imported"
            elif event_type == "actor_create_received":
                actor_fact["sync_lifecycle_status"] = "received"
            if event_type in {"actor_removed", "actor_deleted", "actor_destroyed", "actor_delete"}:
                actor_fact["sync_lifecycle_status"] = "deleted"
                actor_fact["deleted"] = True
                actor_fact["deleted_at"] = normalized.get("timestamp")
            actors[actor_id] = actor_fact
        else:
            actors = dict(room_state.get("actors") or {})
        asset_id = str(normalized.get("asset_id") or "")
        if asset_id:
            sync_state["asset_events"][asset_id] = dict(stored_event)
            assets = dict(room_state.get("assets") or {})
            asset_fact = dict(assets.get(asset_id) or {})
            asset_fact.update({
                "asset_id": asset_id,
                "path": str(normalized.get("asset_path") or asset_fact.get("path") or ""),
                "plan_id": str(normalized.get("plan_id") or asset_fact.get("plan_id") or ""),
                "batch_id": str(normalized.get("batch_id") or asset_fact.get("batch_id") or ""),
                "last_sync_event": event_type,
                "last_sync_status": str(normalized.get("status") or asset_fact.get("last_sync_status") or ""),
                "last_sync_timestamp": normalized.get("timestamp"),
            })
            if scene_name:
                asset_fact["scene_name"] = scene_name
            completed_asset_events = {
                "asset_transfer_completed",
                "asset_received",
                "file_transfer_completed",
                "peer_asset_ready",
                "asset_peer_ready",
                "asset_ready_for_peer",
                "peer_asset_received",
            }
            failed_asset_events = {"asset_transfer_failed", "file_transfer_failed"}
            started_asset_events = {"asset_transfer_started", "asset_requested", "file_request", "file_transfer_started"}
            progress_asset_events = {
                "asset_transfer_progress",
                "file_transfer_progress",
                "file_chunk",
                "file_chunk_received",
                "file_chunk_sent",
            }
            if event_type in completed_asset_events:
                asset_fact["transfer_status"] = "completed"
                asset_fact["ready"] = True
                asset_fact["failed"] = False
                asset_fact["completed_at"] = normalized.get("timestamp")
            elif event_type in failed_asset_events:
                asset_fact["transfer_status"] = "failed"
                asset_fact["ready"] = False
                asset_fact["failed"] = True
                asset_fact["failed_at"] = normalized.get("timestamp")
            elif event_type in started_asset_events:
                asset_fact["transfer_status"] = "transferring"
                asset_fact["ready"] = False
                asset_fact["failed"] = False
            elif event_type in progress_asset_events:
                asset_fact["transfer_status"] = "transferring"
                asset_fact["ready"] = False
                asset_fact["failed"] = False
            for numeric_key in ("chunk_index", "chunk_count", "bytes_transferred", "total_bytes", "progress"):
                if numeric_key in normalized:
                    asset_fact[numeric_key] = int(normalized.get(numeric_key) or 0)
            assets[asset_id] = asset_fact
        else:
            assets = dict(room_state.get("assets") or {})
        assets = AssetFactValidator.safe_asset_map(assets)

        environment_components = {
            str(batch_key): {
                str(component_id): dict(component)
                for component_id, component in dict(components or {}).items()
                if isinstance(component, Mapping)
            }
            for batch_key, components in dict(room_state.get("environment_components") or {}).items()
            if isinstance(components, Mapping)
        }
        if actor_id and event_bounds is not None:
            for batch_key, components in environment_components.items():
                for component in components.values():
                    if str(component.get("actor_id") or "") != actor_id:
                        continue
                    component["aabb"] = dict(event_bounds)
                    if remote_bounds_source:
                        component["bounds_ready"] = False
                        component["bounds_source"] = remote_bounds_source
                        component["status"] = "sync_received"
                    else:
                        component["bounds_ready"] = True
                        component["bounds_source"] = "engine_actual"
                        component["engine_lifecycle_status"] = "bounds_ready"
                        component["status"] = "ready"
                    affected_batch_id = affected_batch_id or batch_key

        custom_import_facts = {
            str(key): dict(value)
            for key, value in dict(room_state.get("custom_import_facts") or {}).items()
            if isinstance(value, Mapping)
        }
        if affected_batch_id:
            for actor_fact_suffix in ("actor_import_plan", "actor_import_result"):
                actor_result_key = f"{affected_batch_id}:{actor_fact_suffix}"
                actor_result = dict(custom_import_facts.get(actor_result_key) or {})
                if not actor_result:
                    continue
                imported_count = int(
                    actor_result.get("imported_count")
                    or actor_result.get("actor_count")
                    or actor_result.get("requested_count")
                    or 0
                )
                ready_count = sum(
                    1
                    for actor in actors.values()
                    if str(actor.get("batch_id") or "") == affected_batch_id
                    and bool(actor.get("bounds_ready"))
                    and str(actor.get("engine_lifecycle_status") or "") == "bounds_ready"
                )
                actor_result["ready_count"] = min(imported_count, ready_count)
                if imported_count > 0 and ready_count >= imported_count:
                    actor_result["status"] = "imported"
                custom_import_facts[actor_result_key] = actor_result

            environment_result_key = f"{affected_batch_id}:environment_import_result"
            environment_result = dict(custom_import_facts.get(environment_result_key) or {})
            if environment_result:
                components = environment_components.get(affected_batch_id, {})
                imported_count = int(environment_result.get("imported_count") or 0)
                ready_count = sum(
                    1
                    for component in components.values()
                    if bool(component.get("bounds_ready"))
                    and str(component.get("engine_lifecycle_status") or "") == "bounds_ready"
                )
                environment_result["ready_count"] = min(imported_count, ready_count)
                if imported_count > 0 and ready_count >= imported_count:
                    environment_result["status"] = "imported"
                custom_import_facts[environment_result_key] = environment_result

        changes = {
            "sync_events": [dict(stored_event)],
            "sync_state": sync_state,
            "actors": actors,
            "assets": assets,
        }
        if peer_mirror_event:
            mirror_versions = dict(room_state.get("peer_mirror_scene_versions") or {})
            mirror_versions[effective_plan_id] = max(
                int(mirror_versions.get(effective_plan_id) or 1),
                int(normalized.get("scene_version") or normalized.get("actor_version") or 1),
            )
            changes["peer_mirror_plan_id"] = effective_plan_id
            changes["peer_mirror_scene_versions"] = mirror_versions
        if actor_id and event_bounds is not None:
            changes["environment_components"] = environment_components
            changes["custom_import_facts"] = custom_import_facts
        patch_ref = _id("sync-event-patch")
        self._pending_sync_event_patches[patch_ref] = changes
        graph = ToolCallGraph(
            graph_id=_id("graph-sync-event-record"),
            plan_id=effective_plan_id or "__sync__",
            batch_id=str(stored_event.get("batch_id") or ""),
        )
        graph.add(
            ToolCall(
                tool_call_id=_id("tool-sync-event-record"),
                tool_name="runtime.sync_event.record",
                args={
                    "room_id": room_key,
                    "event_type": event_type,
                    "patch_ref": patch_ref,
                },
                risk_level=RiskLevel.LOW,
                requires_write=True,
                confirmed=True,
            )
        )
        executor = ToolCallGraphExecutor(
            registry=self.registry,
            guard=self.guard,
            state=self.state,
            operation_log=self.operation_log,
        )
        try:
            executor.execute(graph, room_id=room_key)
        finally:
            self._pending_sync_event_patches.pop(patch_ref, None)
        sync_call = next(iter(graph.nodes.values()))
        applied = graph.status == "completed" and sync_call.status == ToolCallStatus.SUCCEEDED
        reason = sync_call.error or graph.status or "completed"
        self.operation_log.append(
            "sync_event_recorded" if applied else "sync_event_record_failed",
            room_id=room_key,
            plan_id=effective_plan_id,
            message=event_type,
            payload={
                "applied": applied,
                "reason": reason,
                "failure_code": "" if applied else "sync_event_record_failed",
                "event_type": event_type,
                "source": str(stored_event.get("source") or ""),
                "actor_id": str(stored_event.get("actor_id") or ""),
                "asset_id": str(stored_event.get("asset_id") or ""),
                "peer_id": str(stored_event.get("peer_id") or ""),
                "batch_id": str(stored_event.get("batch_id") or ""),
                "status": str(stored_event.get("status") or ""),
                "room_status": str(sync_state.get("room_status") or ""),
                "transfer_status": str(dict(assets.get(asset_id) or {}).get("transfer_status") or "") if asset_id else "",
                "progress": int(stored_event.get("progress") or 0),
                "chunk_index": int(stored_event.get("chunk_index") or 0),
                "chunk_count": int(stored_event.get("chunk_count") or 0),
                "bytes_transferred": int(stored_event.get("bytes_transferred") or 0),
                "total_bytes": int(stored_event.get("total_bytes") or 0),
                "actor_event_count": len(sync_state.get("actor_events") or {}),
                "asset_event_count": len(sync_state.get("asset_events") or {}),
            },
        )
        if applied:
            title, message, level = self._runtime_event_for_sync_fact(normalized, sync_state)
            self.emit_runtime_event(
                room_id=room_key,
                plan_id=effective_plan_id,
                event_type="sync_event",
                phase="sync",
                title=title,
                message=message,
                level=level,
                payload={
                    "status": str(normalized.get("status") or ""),
                    "actor_count": len(actors),
                    "progress": int(normalized.get("progress") or 0),
                    "chunk_index": int(normalized.get("chunk_index") or 0),
                    "chunk_count": int(normalized.get("chunk_count") or 0),
                    "bytes_transferred": int(normalized.get("bytes_transferred") or 0),
                    "total_bytes": int(normalized.get("total_bytes") or 0),
                },
            )
        readiness_recovery: dict[str, Any] = {}
        if applied and affected_batch_id and effective_plan_id:
            batch = self.batch_plans.get(affected_batch_id)
            if batch is not None and batch.status == BatchPlanStatus.PARTIAL:
                recovery_graph = ToolCallGraph(
                    graph_id=_id("graph-engine-ready-recovery"),
                    plan_id=effective_plan_id,
                    batch_id=affected_batch_id,
                )
                recovery_graph.status = "completed"
                self._finalize_batch_after_drained_graph(recovery_graph, room_id=room_key)
                readiness_recovery = self._finalize_plan_after_queue_drain(
                    room_id=room_key,
                    plan_id=effective_plan_id,
                )
                self.operation_log.append(
                    "engine_readiness_reconciled_from_sync",
                    room_id=room_key,
                    plan_id=effective_plan_id,
                    batch_id=affected_batch_id,
                    payload={
                        "actor_id": actor_id,
                        "batch_status": self.batch_plans[affected_batch_id].status.value,
                        "plan_status": str(readiness_recovery.get("status") or ""),
                    },
                )
        return {
            "recorded": applied,
            "reason": reason,
            "event": self._safe_sync_event_summary(normalized),
            "readiness_recovery": readiness_recovery,
            "sync_state": self._safe_sync_state_summary(
                sync_state if applied else dict(self.state.room(room_key).get("sync_state") or {})
            ),
        }

    @staticmethod
    def _safe_sync_event_summary(event: Mapping[str, Any]) -> dict[str, Any]:
        return SyncEventValidator.safe_event_summary(event)

    @staticmethod
    def _safe_sync_state_summary(sync_state: Mapping[str, Any]) -> dict[str, Any]:
        return SyncEventValidator.safe_state_summary(sync_state)

    @staticmethod
    def _sync_vector3(value: Any) -> list[float] | None:
        if isinstance(value, Mapping):
            raw = [value.get("x"), value.get("y"), value.get("z")]
        elif isinstance(value, (list, tuple)):
            raw = list(value[:3])
        else:
            return None
        if len(raw) < 3 or any(item is None for item in raw[:3]):
            return None
        try:
            return [round(float(item), 4) for item in raw[:3]]
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _sync_non_negative_int_from_event(event: Mapping[str, Any], candidates: Iterable[str]) -> int | None:
        for key in candidates:
            if key not in event:
                continue
            try:
                return max(0, int(float(event.get(key) or 0)))
            except (TypeError, ValueError):
                continue
        return None

