    def _tool_consumes(self, tool_name: str, *target_args: str) -> dict[str, dict[str, Any]]:
        definition = self.registry.definition(tool_name)
        if definition is None:
            raise ValueError(f"tool not registered: {tool_name}")
        declared = dict(definition.consumes_state or {})
        targets = [str(target or "").strip() for target in target_args if str(target or "").strip()]
        if not targets:
            targets = list(declared)
        missing = [target for target in targets if target not in declared]
        if missing:
            raise ValueError(f"tool {tool_name} does not declare consumes target: {', '.join(missing)}")
        return {target: dict(declared[target]) for target in targets}

    def _mark_review_advisory_skipped_tool(self, call: ToolCall) -> ToolResult:
        room_id = str(call.args.get("room_id") or "")
        plan_id = str(call.args.get("plan_id") or "")
        proposal_key = str(call.args.get("proposal_key") or plan_id)
        proposal = dict(call.args.get("proposal") or {})
        skipped: list[dict[str, str]] = [
            {
                "target_hint": str(item.get("target_hint") or item.get("actor_name") or item.get("actor_id") or ""),
                "reason": str(item.get("reason") or "no eligible actor target"),
            }
            for item in (call.args.get("skipped_targets") or [])
            if isinstance(item, Mapping)
        ]
        execution_reason = str(call.args.get("execution_reason") or "no eligible actor targets")
        updated_proposal = {
            **proposal,
            "execution_status": "skipped",
            "execution_reason": execution_reason,
            "skipped_targets": skipped,
        }
        return ToolResult(
            True,
            execution_reason,
            state_patch=StatePatch(
                room_id=room_id,
                changes={"review_advisory_proposals": {proposal_key or plan_id: updated_proposal}},
                expected_version=self.state.version,
                source_tool_call_id=call.tool_call_id,
            ),
            payload={
                "proposal_id": str(updated_proposal.get("proposal_id") or ""),
                "skipped": skipped,
            },
        )

    def _mark_actor_deleted_tool(self, call: ToolCall) -> ToolResult:
        room_id = str(call.args.get("room_id") or "")
        plan_id = str(call.args.get("plan_id") or "")
        proposal_key = str(call.args.get("proposal_key") or plan_id)
        proposal = dict(call.args.get("proposal") or {})
        target_actors = [
            dict(item)
            for item in (call.args.get("target_actors") or [])
            if isinstance(item, Mapping)
        ]
        skipped: list[dict[str, str]] = [
            {
                "target_hint": str(item.get("target_hint") or item.get("actor_name") or item.get("actor_id") or ""),
                "reason": str(item.get("reason") or "skipped before execution"),
            }
            for item in (call.args.get("skipped_targets") or [])
            if isinstance(item, Mapping)
        ]
        actors = dict(self.state.room(room_id).get("actors", {}) or {})
        actor_updates: dict[str, dict[str, Any]] = {}
        marked: list[dict[str, str]] = []
        now = _now()
        for target in target_actors:
            actor_ref = str(
                target.get("actor_id")
                or target.get("actor_name")
                or target.get("target_hint")
                or ""
            ).strip()
            actor_id, actor = self._find_runtime_actor_for_delta({**actors, **actor_updates}, actor_ref)
            if not actor_id or not actor:
                skipped.append({"target_hint": actor_ref, "reason": "actor not found in RuntimeState"})
                continue
            actor_name = str(actor.get("name") or actor_id)
            if self._is_system_actor_name(actor_name) or RuntimeGuard.is_system_actor_ref(actor_id):
                skipped.append({"target_hint": actor_ref, "reason": "system actor skipped"})
                continue
            updated = dict(actor)
            updated["deleted"] = True
            updated["deleted_at"] = now
            updated["sync_lifecycle_status"] = "deleted"
            updated["last_sync_status"] = "deleted"
            updated["last_sync_event"] = "runtime_mark_deleted"
            updated["last_sync_timestamp"] = now
            actor_updates[actor_id] = updated
            actors[actor_id] = updated
            marked.append({"actor_id": actor_id, "actor_name": actor_name})

        engine_delete_results: list[dict[str, Any]] = []
        if marked and self._actor_delete_provider is not None:
            try:
                provider_result = dict(self._actor_delete_provider({
                    "room_id": room_id,
                    "plan_id": plan_id,
                    "proposal_id": str(proposal.get("proposal_id") or ""),
                    "proposal": proposal,
                    "marked_deleted_actors": marked,
                    "target_actors": target_actors,
                    "actors": actor_updates,
                }) or {})
            except Exception:  # noqa: BLE001
                return ToolResult(
                    False,
                    "actor delete provider failed",
                    retryable=True,
                    error_code="actor_delete_provider_failed",
                    user_visible_message="删除写入引擎失败，系统会稍后重试或等待进一步处理。",
                )
            engine_delete_results = [
                dict(item)
                for item in (provider_result.get("delete_results") or [])
                if isinstance(item, Mapping)
            ]
            successful_ids = {
                str(item.get("actor_id") or "")
                for item in engine_delete_results
                if str(item.get("status") or "").lower() in {"success", "succeeded", "applied", "ok"}
            }
            provider_actor_updates = {
                str(actor_id): dict(actor)
                for actor_id, actor in (provider_result.get("actor_updates") or {}).items()
                if isinstance(actor, Mapping) and str(actor_id) in successful_ids
            }
            actor_updates = {
                actor_id: {
                    **actor_updates.get(actor_id, {}),
                    **provider_actor_updates.get(actor_id, {}),
                    "deleted": True,
                    "sync_lifecycle_status": "deleted",
                }
                for actor_id in successful_ids
                if actor_id in actor_updates or actor_id in provider_actor_updates
            }
            marked = [
                item
                for item in marked
                if str(item.get("actor_id") or "") in actor_updates
            ]
            for item in engine_delete_results:
                if str(item.get("status") or "").lower() in {"success", "succeeded", "applied", "ok"}:
                    continue
                skipped.append({
                    "target_hint": str(item.get("actor_name") or item.get("actor_id") or ""),
                    "reason": str(item.get("reason") or "engine delete failed"),
                })

        updated_proposal = {
            **proposal,
            "execution_status": "executed" if marked else "skipped",
            "execution_reason": (
                "engine actor delete observed" if marked and self._actor_delete_provider is not None
                else "runtime actor facts marked deleted" if marked
                else "no actor targets marked"
            ),
            "marked_deleted_actors": marked,
            "skipped_targets": skipped,
        }
        if engine_delete_results:
            updated_proposal["engine_delete_results"] = engine_delete_results
            updated_proposal["engine_delete_boundary"] = self._safe_engine_delete_boundary(
                provider_result,
                requested_count=len(target_actors),
                deleted_count=len(marked),
            )
        changes: dict[str, Any] = {
            "review_advisory_proposals": {proposal_key or plan_id: updated_proposal},
        }
        if actor_updates:
            changes["actors"] = ActorFactValidator.safe_actor_map(actor_updates)
            sync_events, sync_state = self._actor_delete_sync_patch(
                room_id=room_id,
                plan_id=plan_id,
                actor_updates=actor_updates,
                timestamp=now,
            )
            if sync_events:
                changes["sync_events"] = sync_events
                changes["sync_state"] = sync_state
        return ToolResult(
            True,
            "confirmed delete advisory targets marked in RuntimeState" if marked else "no delete advisory targets marked",
            state_patch=StatePatch(
                room_id=room_id,
                changes=changes,
                expected_version=self.state.version,
                source_tool_call_id=call.tool_call_id,
            ),
            payload={
                "proposal_id": str(updated_proposal.get("proposal_id") or ""),
                "marked": marked,
                "skipped": skipped,
                "delete_results": engine_delete_results,
            },
        )

    def _actor_delete_sync_patch(
        self,
        *,
        room_id: str,
        plan_id: str,
        actor_updates: Mapping[str, Mapping[str, Any]],
        timestamp: float,
    ) -> tuple[list[dict[str, Any]], dict[str, Any]]:
        room_state = self.state.room(room_id)
        existing_events = list(room_state.get("sync_events") or [])
        existing_sync_state = dict(room_state.get("sync_state") or {})
        sync_state = {
            "event_count": int(existing_sync_state.get("event_count") or len(existing_events)),
            "room_status": str(existing_sync_state.get("room_status") or "active"),
            "last_event": dict(existing_sync_state.get("last_event") or {}),
            "peer_events": dict(existing_sync_state.get("peer_events") or {}),
            "actor_events": dict(existing_sync_state.get("actor_events") or {}),
            "asset_events": dict(existing_sync_state.get("asset_events") or {}),
        }
        events: list[dict[str, Any]] = []
        for actor_id, actor in actor_updates.items():
            event = SyncEventValidator.safe_storage_event({
                "room_id": room_id,
                "event_type": "actor_deleted",
                "source": "agent_runtime_delete_advisory",
                "plan_id": plan_id,
                "actor_id": str(actor_id),
                "actor_name": str(actor.get("name") or actor_id),
                "status": "deleted",
                "scene_name": str(actor.get("scene_name") or ""),
                "timestamp": timestamp,
            })
            events.append(event)
            sync_state["event_count"] += 1
            sync_state["last_event"] = dict(event)
            sync_state["actor_events"][str(actor_id)] = dict(event)
        SyncEventValidator.validate_state(sync_state)
        return events, sync_state

    @staticmethod
    def _safe_engine_delete_boundary(
        provider_result: Mapping[str, Any],
        *,
        requested_count: int,
        deleted_count: int,
    ) -> dict[str, Any]:
        raw_engine_result = provider_result.get("engine_write_result") if isinstance(provider_result, Mapping) else None
        engine_result = raw_engine_result if isinstance(raw_engine_result, Mapping) else {}
        delete_results = (
            provider_result.get("delete_results")
            if isinstance(provider_result.get("delete_results"), list)
            else []
        )
        status_counts: dict[str, int] = {}
        observed_deleted_count = 0
        for item in delete_results:
            if not isinstance(item, Mapping):
                continue
            status_key = str(item.get("status") or "unknown").strip().lower() or "unknown"
            status_counts[status_key] = status_counts.get(status_key, 0) + 1
            if item.get("observed_deleted"):
                observed_deleted_count += 1
        return {
            "provider_source": AgentRuntime._safe_engine_write_provider_source(
                provider_result.get("source")
                or engine_result.get("provider_source")
                or "actor_delete_provider"
            ),
            "requested_count": int(engine_result.get("requested_count") or max(requested_count, len(delete_results))),
            "deleted_count": int(engine_result.get("deleted_count") or deleted_count),
            "observed_deleted_count": int(engine_result.get("observed_deleted_count") or observed_deleted_count),
            "status_counts": AgentRuntime._safe_status_count_map(
                engine_result.get("status_counts") or status_counts
            ),
            **AgentRuntime._safe_engine_bridge_boundary_fields(engine_result),
        }

    def _build_batch_execution_graph(self, plan: ScenePlan, batch: BatchPlan, *, scene_name: str = "") -> ToolCallGraph:
        graph = ToolCallGraph(
            graph_id=_id("graph"),
            plan_id=plan.plan_id,
            batch_id=batch.batch_id,
            graph_role="business_batch",
        )
        scene_contract = self._derive_scene_design_contract_fact(plan)
        snapshot_id = _id("tool")
        extract_id = _id("tool")
        classify_id = _id("tool")
        substrate_plan_id = _id("tool")
        substrate_resolve_id = _id("tool")
        environment_components_id = _id("tool")
        environment_import_id = _id("tool")
        asset_plan_id = _id("tool")
        image_prepare_id = _id("tool")
        model_prepare_id = _id("tool")
        placement_id = _id("tool")
        geometry_review_id = _id("tool")
        import_plan_id = _id("tool")
        import_batch_id = _id("tool")
        ground_snap_id = _id("tool")
        vlm_checkpoint_id = _id("tool")
        review_summary_id = _id("tool")
        review_adjustment_id = _id("tool")
        graph.add(
            ToolCall(
                tool_call_id=snapshot_id,
                tool_name="runtime.scene.snapshot",
                args={
                    "room_id": plan.room_id,
                    "plan_id": plan.plan_id,
                    "batch_id": batch.batch_id,
                    "scene_version": max(1, int(plan.version or 1)),
                    "scene_name": str(scene_name or ""),
                },
                risk_level=RiskLevel.LOW,
            )
        )
        graph.add(
            ToolCall(
                tool_call_id=extract_id,
                tool_name="scene.extract_objects",
                args={
                    "room_id": plan.room_id,
                    "text": plan.design_brief,
                    "plan_id": plan.plan_id,
                    "batch_id": batch.batch_id,
                },
                risk_level=RiskLevel.LOW,
                depends_on=[snapshot_id],
            )
        )
        graph.add(
            ToolCall(
                tool_call_id=classify_id,
                tool_name="runtime.elements.classify",
                args={
                    "room_id": plan.room_id,
                    "text": plan.design_brief,
                    "items": list(batch.requested_items),
                    "plan_id": plan.plan_id,
                    "classification_id": batch.batch_id,
                },
                risk_level=RiskLevel.LOW,
                depends_on=[extract_id],
            )
        )
        graph.add(
            ToolCall(
                tool_call_id=asset_plan_id,
                tool_name="runtime.asset.plan",
                args={
                    "room_id": plan.room_id,
                    "batch_id": batch.batch_id,
                    "plan_id": plan.plan_id,
                },
                risk_level=RiskLevel.LOW,
                depends_on=[classify_id],
                consumes=self._tool_consumes("runtime.asset.plan", "model_items"),
            )
        )
        graph.add(
            ToolCall(
                tool_call_id=substrate_plan_id,
                tool_name="runtime.substrate.plan",
                args={
                    "room_id": plan.room_id,
                    "batch_id": batch.batch_id,
                    "plan_id": plan.plan_id,
                },
                risk_level=RiskLevel.LOW,
                depends_on=[classify_id],
                consumes=self._tool_consumes("runtime.substrate.plan", "routes"),
            )
        )
        graph.add(
            ToolCall(
                tool_call_id=substrate_resolve_id,
                tool_name="runtime.substrate.resolve",
                args={
                    "room_id": plan.room_id,
                    "batch_id": batch.batch_id,
                    "plan_id": plan.plan_id,
                },
                risk_level=RiskLevel.LOW,
                depends_on=[substrate_plan_id],
                consumes=self._tool_consumes("runtime.substrate.resolve", "substrate_plan"),
            )
        )
