    @staticmethod
    def _review_checkpoint_for_batch(batch: BatchPlan) -> tuple[str, list[str]]:
        items = [str(item or "").strip() for item in batch.requested_items if str(item or "").strip()]
        if batch.batch_index <= 1:
            return "structure_review", items[:4]
        if batch.batch_index >= max(1, batch.total_batches):
            return "final_consistency_review", items[:6]
        high_risk_terms = (
            "雕像", "大型", "动物", "小狗", "狗", "猫", "入口", "拱门", "边界",
            "栅栏", "围栏", "桥", "灯光", "灯笼", "吊灯", "悬挂",
            "statue", "animal", "dog", "cat", "entrance", "gate", "boundary",
            "fence", "bridge", "lantern", "light",
        )
        high_risk = [item for item in items if any(term in item for term in high_risk_terms)]
        return "high_risk_object_review", high_risk[:4]

    def _deterministic_placements_for_graph(self, items: list[str], layout_items: list[str]) -> dict[str, dict[str, Any]]:
        from .tools import build_placement_proposals

        return build_placement_proposals(items, layout_items)

    def _apply_layout_delta_tool(self, call: ToolCall) -> ToolResult:
        room_id = str(call.args.get("room_id") or "")
        plan_id = str(call.args.get("plan_id") or "")
        scene_name = str(call.args.get("scene_name") or "")
        proposal = dict(call.args.get("proposal") or {})
        AdjustmentProposalValidator.validate(proposal)
        deltas = [dict(delta) for delta in (proposal.get("deltas") or []) if isinstance(delta, dict)]
        actors = dict(self.state.room(room_id).get("actors", {}) or {})
        actor_updates: dict[str, dict[str, Any]] = {}
        applied: list[dict[str, Any]] = []
        skipped: list[dict[str, Any]] = [
            dict(delta)
            for delta in (proposal.get("skipped_deltas") or [])
            if isinstance(delta, dict)
        ]
        for delta in deltas:
            if str(delta.get("risk_level") or "low").lower() != "low":
                skipped.append({**delta, "reason": "only low-risk deltas are applied in Runtime"})
                continue
            if str(delta.get("op") or "") != "move":
                skipped.append({**delta, "reason": "unsupported delta operation"})
                continue
            actor_name = str(delta.get("actor_name") or "")
            actor_id, actor = self._find_runtime_actor_for_delta({**actors, **actor_updates}, actor_name)
            if not actor_id or not actor:
                skipped.append({**delta, "reason": "actor not found in RuntimeState"})
                continue
            if self._is_system_actor_name(str(actor.get("name") or actor_id)):
                skipped.append({**delta, "reason": "system actor skipped"})
                continue
            current_position = list(actor.get("position") or [0.0, 0.0, 0.0])
            while len(current_position) < 3:
                current_position.append(0.0)
            next_position = [float(value) for value in current_position[:3]]
            if isinstance(delta.get("position"), list) and len(delta.get("position") or []) >= 3:
                next_position = [float(value) for value in (delta.get("position") or [])[:3]]
            patch = delta.get("position_patch")
            if isinstance(patch, dict):
                if "x" in patch:
                    next_position[0] = float(patch["x"])
                if "y" in patch:
                    next_position[1] = float(patch["y"])
                if "z" in patch:
                    next_position[2] = float(patch["z"])
            support_type = self._layout_support_type(actor)
            updated = dict(actor)
            aabb_shift = [
                float(next_position[0]) - float(current_position[0]),
                float(next_position[1]) - float(current_position[1]),
                float(next_position[2]) - float(current_position[2]),
            ]
            shifted_aabb = self._shift_actor_aabb(updated.get("aabb"), aabb_shift)
            if shifted_aabb:
                updated["aabb"] = shifted_aabb
            updated["position"] = [round(float(value), 3) for value in next_position[:3]]
            ground_snap = self._snap_actor_bottom_to_ground_if_supported(
                actor=updated,
                support_type=support_type,
            )
            if ground_snap.get("snapped"):
                next_position[1] = float(ground_snap["position_y"])
                updated["aabb"] = ground_snap["aabb"]
            updated["support_type"] = support_type
            if support_type == "floor_supported":
                updated["grounding_status"] = (
                    "grounded"
                    if ground_snap.get("snapped") or ground_snap.get("reason") == "already grounded"
                    else "needs_review"
                )
            elif support_type in {"wall_mounted", "ceiling_hung", "system"}:
                updated["grounding_status"] = "not_applicable"
            else:
                updated["grounding_status"] = "unknown"
            updated["position"] = [round(float(value), 3) for value in next_position[:3]]
            if scene_name:
                updated["scene_name"] = scene_name
            actor_updates[actor_id] = updated
            actors[actor_id] = updated
            applied_delta = {
                **delta,
                "actor_id": actor_id,
                "position": list(updated["position"]),
                "support_type": support_type,
            }
            if ground_snap.get("snapped"):
                applied_delta["ground_snapped"] = True
                applied_delta["ground_snap_reason"] = ground_snap.get("reason", "")
            elif ground_snap.get("reason"):
                applied_delta["ground_snapped"] = False
                applied_delta["ground_snap_reason"] = ground_snap.get("reason", "")
            applied.append(applied_delta)
        updated_proposal = {
            **proposal,
            "status": "applied" if applied else "skipped",
            "applied_deltas": applied,
            "skipped_deltas": skipped,
        }
        if applied and self._layout_transform_provider is not None:
            try:
                provider_result = dict(self._layout_transform_provider({
                    "room_id": room_id,
                    "plan_id": plan_id,
                    "proposal": proposal,
                    "applied_deltas": applied,
                    "actors": actor_updates,
                    "scene_name": scene_name,
                }) or {})
            except Exception as exc:  # noqa: BLE001
                return ToolResult(
                    False,
                    "layout transform provider failed",
                    retryable=True,
                    error_code="layout_transform_provider_failed",
                    user_visible_message="布局调整写入引擎失败，系统会稍后重试或等待进一步处理。",
                )
            provider_actor_updates = provider_result.get("actor_updates")
            provider_authoritative_updates: dict[str, dict[str, Any]] = {}
            if isinstance(provider_actor_updates, dict):
                for actor_id, actor in provider_actor_updates.items():
                    if isinstance(actor, dict) and str(actor_id) in actor_updates:
                        provider_authoritative_updates[str(actor_id)] = {
                            **actor_updates[str(actor_id)],
                            **actor,
                        }
            actor_updates = provider_authoritative_updates
            updated_proposal["engine_transform_results"] = self._safe_engine_transform_results(
                provider_result.get("transform_results") or []
            )
            updated_proposal["engine_transform_boundary"] = self._safe_engine_transform_boundary(
                provider_result,
                requested_count=len(applied),
                updated_count=len(actor_updates),
            )
            updated_proposal["status"] = "applied" if actor_updates else "skipped"
        if actor_updates:
            actor_updates = ActorFactValidator.safe_actor_map(actor_updates)
        sync_changes = self._layout_transform_sync_changes(
            room_id=room_id,
            plan_id=plan_id,
            proposal=updated_proposal,
            actor_updates=actor_updates,
            scene_name=scene_name,
        )
        proposal_id = str(updated_proposal.get("proposal_id") or "")
        transform_results = (
            updated_proposal.get("engine_transform_results")
            if isinstance(updated_proposal.get("engine_transform_results"), list)
            else []
        )
        transform_failure_code_counts: dict[str, int] = {}
        ground_snapped_count = 0
        overlap_resolved_count = 0
        for transform_result in transform_results:
            if not isinstance(transform_result, Mapping):
                continue
            if bool(transform_result.get("ground_snapped")):
                ground_snapped_count += 1
            if bool(transform_result.get("overlap_resolved")):
                overlap_resolved_count += 1
            status = str(transform_result.get("status") or "").strip().lower()
            if status in {"failed", "failure", "error", "rejected"}:
                failure_code = RuntimeEventValidator.safe_text(
                    transform_result.get("failure_code")
                    or transform_result.get("reason")
                    or "layout_transform_failed"
                ).strip()
                if failure_code:
                    failure_code = failure_code[:80]
                    transform_failure_code_counts[failure_code] = (
                        transform_failure_code_counts.get(failure_code, 0) + 1
                    )
        if not transform_results:
            for applied_delta in updated_proposal.get("applied_deltas") or []:
                if isinstance(applied_delta, Mapping) and bool(applied_delta.get("ground_snapped")):
                    ground_snapped_count += 1
        transform_failed_count = sum(transform_failure_code_counts.values())
        transform_success_count = max(0, len(transform_results) - transform_failed_count)
        layout_fact_key = f"{plan_id}:{proposal_id or 'layout'}:layout_transform_result"
        layout_fact = {
            "room_id": room_id,
            "plan_id": plan_id,
            "proposal_id": proposal_id,
            "batch_id": self._batch_id_from_layout_proposal(updated_proposal),
            "source": "runtime_layout_transform_result",
            "status": str(updated_proposal.get("status") or ""),
            "applied_count": len(updated_proposal.get("applied_deltas") or []),
            "skipped_count": len(updated_proposal.get("skipped_deltas") or []),
            "transform_result_count": len(transform_results),
            "transform_success_count": transform_success_count,
            "transform_failed_count": transform_failed_count,
            "ground_snapped_count": ground_snapped_count,
            "overlap_resolved_count": overlap_resolved_count,
            "layout_transform_failure_code_counts": dict(sorted(transform_failure_code_counts.items())),
        }
        changes: dict[str, Any] = {
            "layout_adjustment_proposals": {plan_id: updated_proposal},
            "custom_report_facts": {layout_fact_key: layout_fact},
        }
        if actor_updates:
            changes["actors"] = actor_updates
        changes.update(sync_changes)
        return ToolResult(
            True,
            "layout adjustment deltas applied" if applied else "layout adjustment had no applicable deltas",
            state_patch=StatePatch(
                room_id=room_id,
                changes=changes,
                expected_version=self.state.version,
                source_tool_call_id=call.tool_call_id,
            ),
            payload={
                "proposal_id": str(updated_proposal.get("proposal_id") or ""),
                "applied": applied,
                "skipped": skipped,
            },
        )

    @staticmethod
    def _find_runtime_actor_for_delta(actors: dict[str, Any], actor_name: str) -> tuple[str, dict[str, Any]]:
        normalized = str(actor_name or "").strip()
        if normalized in actors and isinstance(actors[normalized], dict):
            return normalized, dict(actors[normalized])
        for actor_id, actor in actors.items():
            if not isinstance(actor, dict):
                continue
            candidate_names = [
                str(actor.get("name") or ""),
                str(actor.get("requested_name") or ""),
                str(actor.get("native_name") or ""),
                str(actor.get("display_name") or ""),
                str(actor.get("actor_id") or actor_id),
            ]
            aliases = actor.get("aliases") if isinstance(actor.get("aliases"), list) else []
            candidate_names.extend(str(item or "") for item in aliases)
            if any(str(candidate or "").strip() == normalized for candidate in candidate_names):
                return str(actor_id), dict(actor)
        return "", {}

    def _layout_transform_sync_changes(
        self,
        *,
        room_id: str,
        plan_id: str,
        proposal: Mapping[str, Any],
        actor_updates: Mapping[str, Any],
        scene_name: str = "",
    ) -> dict[str, Any]:
        if not actor_updates:
            return {}
        room_state = self.state.room(str(room_id))
        existing_sync_state = dict(room_state.get("sync_state") or {})
        existing_events = list(room_state.get("sync_events") or [])
        sync_state = {
            "event_count": int(existing_sync_state.get("event_count") or len(existing_events)),
            "room_status": str(existing_sync_state.get("room_status") or "active"),
            "last_event": dict(existing_sync_state.get("last_event") or {}),
            "peer_events": dict(existing_sync_state.get("peer_events") or {}),
            "actor_events": dict(existing_sync_state.get("actor_events") or {}),
            "asset_events": dict(existing_sync_state.get("asset_events") or {}),
        }
        timestamp = _now()
        batch_id = self._batch_id_from_layout_proposal(proposal)
        stored_events: list[dict[str, Any]] = []
        for actor_id, actor in actor_updates.items():
            if not isinstance(actor, Mapping):
                continue
            event = {
                "room_id": str(room_id),
                "event_type": "actor_transform",
                "source": "runtime_layout_transform",
                "plan_id": str(plan_id),
                "batch_id": str(actor.get("batch_id") or batch_id or ""),
                "actor_id": str(actor_id),
                "actor_name": str(actor.get("name") or actor_id),
                "status": "applied",
                "scene_name": str(actor.get("scene_name") or scene_name or ""),
                "timestamp": timestamp,
            }
            for vector_key in ("position", "rotation", "scale"):
                value = actor.get(vector_key)
                if isinstance(value, list) and len(value) >= 3:
                    event[vector_key] = list(value[:3])
            stored_event = SyncEventValidator.safe_storage_event(event)
            stored_events.append(stored_event)
            sync_state["event_count"] += 1
            sync_state["last_event"] = dict(stored_event)
            sync_state["actor_events"][str(actor_id)] = dict(stored_event)
        if not stored_events:
            return {}
        return {
            "sync_events": stored_events,
            "sync_state": sync_state,
        }

    @staticmethod
    def _safe_engine_transform_results(results: Any) -> list[dict[str, Any]]:
        if not isinstance(results, list):
            return []
        safe_results: list[dict[str, Any]] = []
        allowed_scalar_fields = {
            "actor_id",
            "actor_name",
            "failure_code",
            "name",
            "status",
            "reason",
            "observed_position",
            "ground_snapped",
            "overlap_resolved",
        }
        blocked_reason_tokens = (
            "api_key",
            "authorization",
            "bearer ",
            "c:\\",
            "e:\\",
            "http://",
            "https://",
            "metadata",
            "model_path",
            "prompt",
            "provider",
            "raw",
            "token",
            "url",
            "://",
        )
        for item in results:
            if not isinstance(item, Mapping):
                continue
            safe: dict[str, Any] = {}
            for field, value in item.items():
                normalized = str(field or "").strip()
                lowered = normalized.lower()
                if lowered in ReportRecordValidator._BLOCKED_FIELDS:
                    continue
                if normalized == "position" and isinstance(value, list) and len(value) >= 3:
                    try:
                        safe["position"] = [round(float(value[0]), 4), round(float(value[1]), 4), round(float(value[2]), 4)]
                    except (TypeError, ValueError):
                        pass
                    continue
                if normalized not in allowed_scalar_fields:
                    continue
                if isinstance(value, str):
                    if normalized in {"reason", "failure_code"} and any(
                        token in value.lower() for token in blocked_reason_tokens
                    ):
                        continue
                    safe[normalized] = value[:160]
                elif isinstance(value, (int, float, bool)):
                    safe[normalized] = value
            if safe:
                safe_results.append(safe)
        return safe_results

    @staticmethod
    def _safe_engine_transform_boundary(
        provider_result: Mapping[str, Any],
        *,
        requested_count: int,
        updated_count: int,
    ) -> dict[str, Any]:
        raw_engine_result = provider_result.get("engine_write_result") if isinstance(provider_result, Mapping) else None
        engine_result = raw_engine_result if isinstance(raw_engine_result, Mapping) else {}
        transform_results = (
            provider_result.get("transform_results")
            if isinstance(provider_result.get("transform_results"), list)
            else []
        )
        status_counts: dict[str, int] = {}
        observed_position_count = 0
        for item in transform_results:
            if not isinstance(item, Mapping):
                continue
            status_key = str(item.get("status") or "unknown").strip().lower() or "unknown"
            status_counts[status_key] = status_counts.get(status_key, 0) + 1
            if item.get("observed_position"):
                observed_position_count += 1
        return {
            "provider_source": AgentRuntime._safe_engine_write_provider_source(
                provider_result.get("source")
                or engine_result.get("provider_source")
                or "layout_transform_provider"
            ),
            "requested_count": int(engine_result.get("requested_count") or requested_count),
            "updated_count": int(engine_result.get("updated_count") or updated_count),
            "observed_position_count": int(engine_result.get("observed_position_count") or observed_position_count),
            "status_counts": AgentRuntime._safe_status_count_map(
                engine_result.get("status_counts") or status_counts
            ),
            **AgentRuntime._safe_engine_bridge_boundary_fields(engine_result),
        }

    @staticmethod
    def _safe_engine_write_provider_source(value: Any) -> str:
        text = str(value or "").strip().lower()
        allowed = {
            "layout_transform_provider",
            "engine_layout_transform_provider",
            "actor_import_provider",
            "engine_actor_import_provider",
            "environment_import_provider",
            "engine_environment_import_provider",
            "runtime_default_environment_import",
            "runtime_default_environment_import_provider",
            "actor_delete_provider",
            "engine_actor_delete_provider",
            "runtime_actor_import_precheck",
        }
        if text in allowed:
            return text
        return "layout_transform_provider"

    @staticmethod
    def _safe_engine_write_source_label(value: Any) -> str:
        text = str(value or "").strip().lower()
        labels = {
            "actor_import_provider": "runtime_actor_import",
            "engine_actor_import_provider": "engine_actor_import",
            "environment_import_provider": "runtime_environment_import",
            "engine_environment_import_provider": "engine_environment_import",
            "runtime_default_environment_import": "runtime_environment_import",
            "runtime_default_environment_import_provider": "runtime_environment_import",
            "runtime_actor_import_precheck": "runtime_actor_import_precheck",
            "layout_transform_provider": "runtime_layout_transform",
            "engine_layout_transform_provider": "engine_layout_transform",
            "actor_delete_provider": "runtime_actor_delete",
            "engine_actor_delete_provider": "engine_actor_delete",
        }
        return labels.get(text, "runtime_engine_write")

    @staticmethod
    def _safe_status_count_map(value: Any) -> dict[str, int]:
        if not isinstance(value, Mapping):
            return {}
        safe: dict[str, int] = {}
        for key, count in value.items():
            status = str(key or "").strip().lower()
            if not status or not re.fullmatch(r"[a-z_]{1,32}", status):
                continue
            try:
                safe[status] = max(0, int(count))
            except (TypeError, ValueError):
                continue
        return safe

    @staticmethod
    def _is_system_actor_name(name: str) -> bool:
        lowered = str(name or "").strip().lower()
        return lowered.startswith(("__", "_terrain", "terrain", "sky"))

    @staticmethod
    def _layout_support_type(actor: Mapping[str, Any]) -> str:
        return classify_support_type(
            (
                actor.get("requested_name"),
                actor.get("name"),
                actor.get("display_name"),
                actor.get("semantic_role"),
                actor.get("actor_name"),
                actor.get("actor_id"),
            ),
            explicit=actor.get("support_type"),
        )

    @staticmethod
    def _vector3_from(value: Any) -> list[float] | None:
        if not isinstance(value, list) or len(value) < 3:
            return None
        try:
            return [float(value[0]), float(value[1]), float(value[2])]
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _shift_actor_aabb(aabb: Any, offset: list[float]) -> dict[str, list[float]]:
        if not isinstance(aabb, Mapping):
            return {}
        min_v = AgentRuntime._vector3_from(aabb.get("min"))
        max_v = AgentRuntime._vector3_from(aabb.get("max"))
        if min_v is None or max_v is None:
            return {}
        return {
            "min": [round(min_v[index] + float(offset[index]), 4) for index in range(3)],
            "max": [round(max_v[index] + float(offset[index]), 4) for index in range(3)],
        }

    @staticmethod
    def _snap_actor_bottom_to_ground_if_supported(
        *,
        actor: Mapping[str, Any],
        support_type: str,
        ground_y: float = 0.0,
        epsilon: float = 0.03,
    ) -> dict[str, Any]:
        if support_type != "floor_supported":
            return {"snapped": False, "reason": f"{support_type} actor skipped"}
        position = AgentRuntime._vector3_from(actor.get("position"))
        if position is None:
            return {"snapped": False, "reason": "actor position unavailable"}
        aabb = dict(actor.get("aabb") or {}) if isinstance(actor.get("aabb"), Mapping) else {}
        min_v = AgentRuntime._vector3_from(aabb.get("min"))
        max_v = AgentRuntime._vector3_from(aabb.get("max"))
        if min_v is None or max_v is None:
            return {"snapped": False, "reason": "actor aabb unavailable"}
        bottom_y = float(min_v[1])
        delta_y = float(ground_y) - bottom_y
        if abs(delta_y) <= float(epsilon):
            return {"snapped": False, "reason": "already grounded"}
        position[1] += delta_y
        min_v[1] += delta_y
        max_v[1] += delta_y
        return {
            "snapped": True,
            "reason": "snap floor-supported object to ground",
            "position_y": round(position[1], 4),
            "aabb": {
                "min": [round(value, 4) for value in min_v],
                "max": [round(value, 4) for value in max_v],
            },
        }

    def _placement_for_actor(self, room_id: str, plan_id: str, actor_name: str) -> dict[str, Any]:
        room = self.state.room(room_id)
        plan_placements = dict(room.get("placement_proposals", {}).get(plan_id, {}) or {})
        placement = plan_placements.get(actor_name)
        return dict(placement or {})

    @staticmethod
    def _derive_title(text: str) -> str:
        clean = " ".join(str(text or "").split())
        return clean[:24] or "未命名场景方案"

    @staticmethod
    def _derive_mock_candidate_items(text: str) -> list[str]:
        from .tools import extract_candidate_items

        return extract_candidate_items(text)

    @staticmethod
    def _derive_mock_model_items(text: str) -> list[str]:
        from .tools import route_candidate_model_names

        return route_candidate_model_names(text)

    @staticmethod
    def _derive_delete_intervention_items(text: str) -> list[str]:
        from .tools import extract_candidate_items

        clean = str(text or "")
        aliases = {
            "金币": "金币堆",
            "钱币": "金币堆",
            "宝箱": "藏宝箱",
            "箱子": "木箱",
            "火把": "火把",
            "酒桶": "酒桶",
            "木桶": "木桶",
            "武器架": "武器架",
            "桌子": "木桌",
            "椅子": "木椅",
            "床": "床",
            "台灯": "台灯",
            "天使雕像": "天使雕像",
            "小狗": "小狗",
        }
        aliased = [canonical for alias, canonical in aliases.items() if alias in clean]
        if aliased:
            return list(dict.fromkeys(aliased))
        generic_placeholders = {"主体物件", "辅助物件"}
        items = [
            str(item)
            for item in extract_candidate_items(text)
            if str(item) and str(item) not in generic_placeholders
        ]
        return items

    @staticmethod
    def _derive_mock_layout_items(text: str) -> list[str]:
        from .tools import _derive_layout_items

        return _derive_layout_items(text)
